BOOK.add({
  subject: "cg",
  id: "cg-28",
  title: "छत्तीसगढ़ी जनऊला (पहेलियाँ), हाना (लोकोक्तियाँ), मुहावरे एवं छत्तीसगढ़ी शब्द-भंडार (विस्तृत अभ्यास)",
  notes: "\n<h3>1. परिचय — लोक-वाणी की तीन विधाएँ</h3>\n<table><tr><th>हिन्दी नाम</th><th>छत्तीसगढ़ी नाम</th><th>स्वरूप</th><th>उदाहरण</th></tr>\n<tr><td>पहेली (प्रहेलिका)</td><td><b>जनऊला / जनउला</b></td><td>प्रश्न के रूप में किसी वस्तु का घुमावदार वर्णन; सुनने वाले को उत्तर \"बूझना\" पड़ता है</td><td>एक गुफा, बत्तीस चौकीदार — मुँह</td></tr>\n<tr><td>लोकोक्ति / कहावत</td><td><b>हाना</b></td><td>पूरा वाक्य; अकेले बोला जा सकता है; अनुभव का निचोड़ या सीख</td><td>जइसन बोंही, तइसन लूही</td></tr>\n<tr><td>मुहावरा</td><td>मुहावरा</td><td>वाक्यांश; वाक्य के भीतर क्रिया की तरह जुड़ता है; अर्थ लाक्षणिक होता है</td><td>लबारी मारना — झूठ बोलना</td></tr></table>\n<div class=\"tip\">पहचान की ट्रिक: <b>हाना</b> = पूरा वाक्य (अपने-आप में पूर्ण) ; <b>मुहावरा</b> = अधूरा वाक्यांश, जिसके अंत में प्रायः \"-ना\" वाली क्रिया होती है (मारना, फुलाना, भरना)। पहेली = <b>जनऊला</b>, लोकोक्ति = <b>हाना</b> — परीक्षा में यह जोड़ी बार-बार पूछी जाती है।</div>\n<p>जनऊला प्रायः रात में भोजन के बाद, खलिहान (कोठार) में या अलाव के पास बड़े-बुज़ुर्ग बच्चों से पूछते हैं। इनमें घर-गृहस्थी (ढेंकी, जाँता, चलनी, सूपा), खेती (नाँगर, बइला), प्रकृति (सुरुज, चंदा, चंदैनी) और खान-पान (मिरचा, केरा, मुनगा) की वस्तुएँ सबसे अधिक आती हैं। कई जनऊला के अंत में चुनौती होती है — \"नइ जानही तेकर बाप भकुवा\" (जो न जाने उसका बाप मूर्ख)।</p>\n\n<h3>2. प्रमुख जनऊला (पहेलियाँ) — उत्तर एवं शब्दार्थ</h3>\n<table><tr><th>क्र.</th><th>जनऊला</th><th>उत्तर</th><th>कठिन शब्दों का अर्थ / संकेत</th></tr>\n<tr><td>1</td><td>लाल गाय लकड़ी खाय, पानी पीये मर जाय</td><td>आगी (आग)</td><td>पानी पड़ते ही आग बुझ (\"मर\") जाती है</td></tr>\n<tr><td>2</td><td>करिया घोड़ा, सफेद सवारी; एक उतरय त दूसर के बारी</td><td>तावा अउ रोटी</td><td>करिया = काला; बारी = पारी</td></tr>\n<tr><td>3</td><td>एक गुफा, बत्तीस चौकीदार</td><td>मुँह (जीभ-दाँत)</td><td>बत्तीस दाँत = चौकीदार</td></tr>\n<tr><td>4</td><td>एक थारी मोती भरे, सबके मुड़ म ओंधा धरे</td><td>अगास अउ तारा</td><td>थारी = थाली; मुड़ = सिर; ओंधा = उलटा</td></tr>\n<tr><td>5</td><td>पेट म अँगरी, मुड़ म पथरा</td><td>मुंदरी (अँगूठी)</td><td>अँगरी = उँगली; पथरा = नग</td></tr>\n<tr><td>6</td><td>कटोरा ऊपर कटोरा, बेटा बाप ले गोरा</td><td>नरियर (नारियल)</td><td>भीतर की गिरी (बेटा) खोल से अधिक सफ़ेद</td></tr>\n<tr><td>7</td><td>हरियर डारा, लाल कमान; खाय म मनखे होय हलाकान</td><td>मिरचा (मिर्च)</td><td>हलाकान = परेशान</td></tr>\n<tr><td>8</td><td>बाहिर ले हरियर, भीतर ले लाल; ओमा करिया-करिया बीजा</td><td>कलिंदर (तरबूज)</td><td>बीजा = बीज</td></tr>\n<tr><td>9</td><td>एक जनावर अइसन, जेकर पूँछी म पइसा</td><td>मंजूर (मोर)</td><td>पंखों की चंद्रिका = पैसे जैसी</td></tr>\n<tr><td>10</td><td>गोड़ नइ हे फेर रेंगथे, आँखी नइ हे फेर रोथे</td><td>बादर (बादल)</td><td>रेंगथे = चलता है; रोथे = रोता (बरसता) है</td></tr>\n<tr><td>11</td><td>जतके निकालबे, ओतके बाढ़त जाय</td><td>खोंचका (गड्ढा)</td><td>जतके = जितना; बाढ़त = बढ़ता</td></tr>\n<tr><td>12</td><td>एक आँखी के डोकरी, पाछू म लंबा पूँछी</td><td>सूजी अउ धागा</td><td>डोकरी = बुढ़िया; पाछू = पीछे</td></tr>\n<tr><td>13</td><td>नानकुन सिपाही, काठ के देंह, मुड़ म आगी</td><td>माचिस के काड़ी</td><td>नानकुन = छोटा; काठ = लकड़ी</td></tr>\n<tr><td>14</td><td>पानी म जनमे, पानी म मर जाय</td><td>नून (नमक)</td><td>समुद्री जल से बनता, पानी में घुल जाता</td></tr>\n<tr><td>15</td><td>बन ले लानेंव बेंदरी, घर म छेदेंव कान; दूध-भात के भोजन करके, फेंक देंव मैदान</td><td>पतरी (पत्तल)</td><td>बन = जंगल; पत्तों को सींक से छेदकर जोड़ते हैं</td></tr>\n<tr><td>16</td><td>पाँच कबूतर पाँचे रंग, महल म जाके एके रंग</td><td>पान-सुपारी (बीड़ा)</td><td>पान, कत्था, चूना, सुपारी आदि मुँह (महल) में जाकर एक (लाल) रंग</td></tr>\n<tr><td>17</td><td>गाँव म आगी लगे, वो गाँव म कुआँ</td><td>हुक्का</td><td>ऊपर चिलम में आग, नीचे पानी</td></tr>\n<tr><td>18</td><td>नानकुन डबरी, बूड़े भारी जहाज</td><td>दीया</td><td>डबरी = छोटा तालाब (तेल); जहाज = बाती</td></tr>\n<tr><td>19</td><td>पेट चिरहा, पीठ कुबरा</td><td>कौड़ी</td><td>चिरहा = चिरा हुआ; कुबरा = कूबड़ वाला</td></tr>\n<tr><td>20</td><td>पहाड़ ले उतरे रेचकी घोड़ी, ओकर पीला अठारा कोरी</td><td>चलनी</td><td>अठारा कोरी = 18 × 20 = 360 (छेद)</td></tr>\n<tr><td>21</td><td>फाँदे के बेर एक ठन, छोरे के बेर दू ठन</td><td>दतवन (दातुन)</td><td>बेर = समय; उपयोग के बाद चीरकर जीभी बनती है</td></tr>\n<tr><td>22</td><td>लाल बइला भागत हे, करिया बइला कुदावत हे</td><td>आगी अउ धुआँ</td><td>लाल लपट आगे, काला धुआँ पीछे</td></tr>\n<tr><td>23</td><td>काटे ले कटाय नहीं, भोंगे ले भोंगाय नहीं</td><td>छाँव (छइहाँ)</td><td>भोंगना = छेदना</td></tr>\n<tr><td>24</td><td>मूठा म धरे, अउ खँचवा म भरे</td><td>जाँता (हाथ-चक्की)</td><td>मूठ पकड़कर घुमाते, छेद में दाना भरते</td></tr>\n<tr><td>25</td><td>एक फूल फूले, सौ फर फरे</td><td>केरा (केला)</td><td>फर = फल; एक फूल से पूरी घौद</td></tr>\n<tr><td>26</td><td>फूल फूले रिंगी-चिंगी, फर फरे लमडोरा</td><td>मुनगा (सहजन)</td><td>लमडोरा = लंबी फली</td></tr>\n<tr><td>27</td><td>सूखा डबरी म बगुला फड़फड़ाय</td><td>लाई (धान का लावा)</td><td>सूखी कड़ाही में फूटता सफ़ेद लावा</td></tr>\n<tr><td>28</td><td>पान गुजगुज, फर लड़वा; एला नइ जानही तेकर बाप भकुवा</td><td>गोंदली (प्याज़)</td><td>गुजगुज = नरम; लड़वा = लड्डू जैसा गोल; भकुवा = मूर्ख</td></tr>\n<tr><td>29</td><td>फरे न फूले, नवे न डार; जब ले जीवय तब ले खाय</td><td>नून (नमक)</td><td>न फल, न फूल, न डाल — फिर भी जीवन भर खाया जाता</td></tr>\n<tr><td>30</td><td>पान के ओधा, माँस के घोंघा</td><td>भाटा (बैंगन)</td><td>पत्तों की ओट में गूदेदार फल</td></tr>\n<tr><td>31</td><td>दिखब म लाल, छुअब म गुजगुज</td><td>पताल (टमाटर)</td><td>गुजगुज = नरम, पिलपिला</td></tr>\n<tr><td>32</td><td>लाल नरियर के हरियर पूँछ</td><td>पताल / बंगाला (टमाटर)</td><td>हरी डंठल वाला लाल गोल फल</td></tr>\n<tr><td>33</td><td>बोवत देखेंव बाटरा, जामत म कुसियार; ढाई महीना के छोकरा, दाढ़ी-मेंछा म हुसियार</td><td>जोंधरी (भुट्टा)</td><td>कुसियार = गन्ना; भुट्टे के बाल = दाढ़ी-मूँछ</td></tr>\n<tr><td>34</td><td>छिछिल तलैया म, डूब मरय सितलैया</td><td>पूड़ी</td><td>छिछिल = उथला (कड़ाही का तेल)</td></tr>\n<tr><td>35</td><td>दूनो कोठा के गोबर ल, एके हाथ म हेरय</td><td>नाक</td><td>कोठा = पशुशाला (दो नथुने); हेरना = निकालना</td></tr>\n<tr><td>36</td><td>तरी पचरी, ऊपर परी, बीच म मोंगरी मछरी</td><td>जीभ</td><td>तरी = नीचे; दाँतों के बीच हिलती मछली</td></tr>\n<tr><td>37</td><td>करिया बन म रहिथँव, लाल पानी पीथँव</td><td>जूँ</td><td>करिया बन = काले बाल; लाल पानी = खून</td></tr>\n<tr><td>38</td><td>गाड़ा भर गहूँ म एक ठन गोटी</td><td>चंदा (तारों के बीच चंद्रमा)</td><td>गाड़ा = बैलगाड़ी; गोटी = गोल कंकड़</td></tr>\n<tr><td>39</td><td>पर्रा भर लाई, गने न सिराई</td><td>चंदैनी (तारे)</td><td>पर्रा = बाँस की बड़ी टोकरी/सूप; सिराई = समाप्त होना</td></tr>\n<tr><td>40</td><td>नंद बबा के नौ सौ गाय, रात चरय दिन बेंड़े जाय</td><td>चंदैनी (तारे)</td><td>बेंड़े जाय = बंद (ओझल) हो जाएँ</td></tr>\n<tr><td>41</td><td>देखब म दूनो रोटी एक बरोबर</td><td>सुरुज अउ चंदा</td><td>बरोबर = बराबर</td></tr>\n<tr><td>42</td><td>काँधे आय, काँधे जाय; नेंग-नेंग म मारे जाय</td><td>बाजा (ढोल)</td><td>नेंग = रस्म; कंधे पर लटकाकर बजाते</td></tr>\n<tr><td>43</td><td>कारी गाय, करंगा पिला; मर गे गाय, छटक गे पिला</td><td>बंदूक (अउ गोली)</td><td>पिला = बच्चा (गोली)</td></tr>\n<tr><td>44</td><td>ताकत हे, तुकावत हे, दूनो गोड़ अलगावत हे</td><td>कोकड़ा (बगुला)</td><td>ताकना = घात लगाकर देखना</td></tr>\n<tr><td>45</td><td>एक पेड़ के बारा डारा, तीस-तीस के झोंथा</td><td>बछर, महीना अउ दिन</td><td>बारा = 12 (महीने), तीस-तीस (दिन)</td></tr>\n<tr><td>46</td><td>खटिया गाँथे तान-बितान, दू सुतइया बाइस कान</td><td>रावन अउ मंदोदरी</td><td>20 + 2 = 22 कान</td></tr>\n<tr><td>47</td><td>तीन मूड़ शंकर नो हे, दूध देथे ते गाय नो हे, रुख म रहिथे ते पंछी नो हे</td><td>नरियर (नारियल)</td><td>नो हे = नहीं है; तीन \"आँखें\", भीतर दूध</td></tr>\n<tr><td>48</td><td>खुसुर-खुसुर खोर्री, छै आँखी तीन घोरी</td><td>नाँगर, बइला अउ मनखे</td><td>दो बैल + एक हलवाहा = छह आँखें</td></tr>\n<tr><td>49</td><td>उड़त देखे काँग-कुड़ी, बइठत डेना पसार</td><td>मछरी मारे के जाल</td><td>डेना = पंख; फेंकने पर फैलता है</td></tr>\n<tr><td>50</td><td>एक गोड़ के घोड़ा, दुइ झन भये सवार</td><td>रहचुली (झूला)</td><td>एक खूँटे पर घूमने वाला झूला</td></tr>\n<tr><td>51</td><td>बिना पाँव के अहिरा भइया, बिना सींग के गाय; अइसन अचरज हम नइ देखेन, खारन-खार कुदाय</td><td>साँप अउ मेचका (मेंढक)</td><td>अहिरा = चरवाहा; खार = खेतों का मैदान</td></tr>\n<tr><td>52</td><td>बिहनिया चार गोड़, मंझनिया दू गोड़, संझा तीन गोड़</td><td>मनखे (मनुष्य)</td><td>बचपन में घुटनों के बल, बुढ़ापे में लाठी</td></tr>\n<tr><td>53</td><td>जतका बाँटबे, ओतके बाढ़य</td><td>विद्या (ज्ञान)</td><td>बाँटबे = बाँटोगे</td></tr>\n<tr><td>54</td><td>रात-दिन चलथे, फेर कहूँ नइ जाय</td><td>घड़ी</td><td>कहूँ = कहीं</td></tr>\n<tr><td>55</td><td>करिया हे फेर कौंवा नोहय, लंबा हे फेर साँप नोहय</td><td>बेनी (चोटी)</td><td>नोहय = नहीं है</td></tr>\n<tr><td>56</td><td>जतके बरय, ओतके छोटे होवत जाय</td><td>मोमबत्ती</td><td>बरय = जले</td></tr>\n<tr><td>57</td><td>दू भाई संग-संग रहिथें, सब ल देखथें, फेर एक-दूसर ल कभू नइ देखँय</td><td>दूनो आँखी</td><td>कभू = कभी</td></tr>\n<tr><td>58</td><td>परत-परत कपड़ा पहिरे, काटे ले आँखी म आँसू लावय</td><td>गोंदली (प्याज़)</td><td>परत = तह</td></tr>\n</table>\n<div class=\"tip\">जनऊला हल करने की ट्रिक: (1) \"करिया/लाल/उज्जर\" जैसे रंग-शब्द, (2) \"गोड़, आँखी, पेट, मुड़\" जैसे अंग-शब्द, और (3) \"कोरी (20), बारा, बत्तीस\" जैसी संख्याएँ — इन्हीं में उत्तर छिपा होता है। जैसे \"अठारा कोरी\" = 360 छेद = चलनी; \"बत्तीस चौकीदार\" = 32 दाँत।</div>\n\n<h3>3. हाना (लोकोक्तियाँ) — अर्थ एवं प्रयोग</h3>\n<table><tr><th>हाना</th><th>हिन्दी अर्थ</th><th>कब बोला जाता है</th></tr>\n<tr><td>जइसन बोंही, तइसन लूही</td><td>जैसा बोओगे, वैसा काटोगे — कर्म के अनुसार फल</td><td>बुरे काम करने वाले को चेताते समय</td></tr>\n<tr><td>जइसन करनी, तइसन भरनी</td><td>जैसा कर्म, वैसा फल</td><td>कर्मफल की सीख में</td></tr>\n<tr><td>दूध के जरे ह मही ल फूँक-फूँक के पीथे</td><td>एक बार धोखा खाया व्यक्ति आगे बहुत सावधान रहता है (मही = छाछ)</td><td>ठोकर के बाद अति-सावधानी पर</td></tr>\n<tr><td>आमा के आमा, गोही के दाम</td><td>दोहरा लाभ (गोही = गुठली)</td><td>एक काम से दो लाभ होने पर</td></tr>\n<tr><td>एक पंथ दू काज</td><td>एक साथ दो काम सिद्ध होना</td><td>एक प्रयास से दो काम बनने पर</td></tr>\n<tr><td>बिन रोये दाई दूध नइ पियावय</td><td>बिना माँगे कुछ नहीं मिलता</td><td>अपनी बात न कहने वाले को</td></tr>\n<tr><td>घर के जोगी जोगड़ा, आन गाँव के सिद्ध</td><td>अपने घर के गुणी का आदर नहीं होता</td><td>घर के योग्य व्यक्ति की उपेक्षा पर</td></tr>\n<tr><td>घर के मुर्गी दार बरोबर</td><td>घर की वस्तु/व्यक्ति का मूल्य नहीं समझा जाता (दार = दाल)</td><td>घर की चीज़ की उपेक्षा पर</td></tr>\n<tr><td>हाथी के दाँत खाय के अउ, देखाय के अउ</td><td>कथनी और करनी में अंतर</td><td>दिखावटी व्यवहार पर</td></tr>\n<tr><td>ओस चाटे ले पियास नइ बुझाय</td><td>थोड़े साधन से बड़ी ज़रूरत पूरी नहीं होती</td><td>अपर्याप्त सहायता पर</td></tr>\n<tr><td>ऊँट के मुँह म जीरा</td><td>आवश्यकता की तुलना में बहुत कम</td><td>बड़ी ज़रूरत पर थोड़ा मिलने पर</td></tr>\n<tr><td>मुड़ मुड़ावत ओला परगे</td><td>काम शुरू करते ही विघ्न आना</td><td>शुरुआत में ही बाधा पर</td></tr>\n<tr><td>करिया अक्छर भइंस बरोबर</td><td>बिल्कुल निरक्षर होना</td><td>अनपढ़ व्यक्ति के लिए</td></tr>\n<tr><td>कुकुर के पूँछी टेड़गा के टेड़गा</td><td>स्वभाव कभी नहीं बदलता</td><td>न सुधरने वाले के लिए</td></tr>\n<tr><td>भइंस के आगू बीन बजाय, भइंस बइठे पगुराय</td><td>मूर्ख के सामने ज्ञान की बात व्यर्थ (पगुराय = जुगाली करे)</td><td>नासमझ को उपदेश देने पर</td></tr>\n<tr><td>अपन गली म कुकुर घलो शेर</td><td>अपने क्षेत्र में दुर्बल भी बलवान (घलो = भी)</td><td>घर में शेर बनने वाले पर</td></tr>\n<tr><td>बाँझ का जानय परसूत के पीरा</td><td>जिसने दुःख न भोगा हो, वह दूसरे की पीड़ा नहीं समझता</td><td>दूसरे के कष्ट को हल्का समझने पर</td></tr>\n<tr><td>जेकर पाँव न फटे बिवाई, ओ का जानय पीर पराई</td><td>वही अर्थ — भुक्तभोगी ही पीड़ा जानता है</td><td>संवेदनहीनता पर</td></tr>\n<tr><td>अपन मरे बिन सरग नइ दिखय</td><td>अपना काम स्वयं करने से ही बनता है</td><td>दूसरों के भरोसे बैठे व्यक्ति को</td></tr>\n<tr><td>अपन हाथ जगन्नाथ</td><td>अपना काम स्वयं करना सबसे अच्छा</td><td>आत्मनिर्भरता की सीख</td></tr>\n<tr><td>दुरिहा के ढोल सुहावन</td><td>दूर की चीज़ अच्छी लगती है (दुरिहा = दूर)</td><td>अनदेखी चीज़ के आकर्षण पर</td></tr>\n<tr><td>चोर के दाढ़ी म तिनका</td><td>दोषी स्वयं शंकित रहता है</td><td>अपराधी के घबराने पर</td></tr>\n<tr><td>नाचे न जाने अँगना टेड़गा</td><td>काम न आने पर साधनों को दोष देना</td><td>बहानेबाज़ के लिए</td></tr>\n<tr><td>अँधरा म कनवा राजा</td><td>मूर्खों में थोड़ा जानकार भी श्रेष्ठ (कनवा = काना)</td><td>अयोग्यों के बीच थोड़े योग्य पर</td></tr>\n<tr><td>जेकर लाठी तेकर भइंस</td><td>शक्तिशाली की ही चलती है</td><td>बलवान की मनमानी पर</td></tr>\n<tr><td>बइठे ले बेगार भला</td><td>खाली बैठने से कुछ काम करते रहना अच्छा</td><td>निठल्ले को</td></tr>\n<tr><td>आँखी के अंधरा, नाव नैनसुख</td><td>नाम के विपरीत गुण</td><td>नाम बड़ा, गुण उलटा होने पर</td></tr>\n<tr><td>बेंदरा का जानय अदरक के सुवाद</td><td>मूर्ख अच्छी वस्तु का मूल्य नहीं जानता</td><td>गुण की कद्र न करने वाले पर</td></tr>\n<tr><td>मन चंगा त कठौती म गंगा</td><td>मन पवित्र हो तो घर में ही तीर्थ</td><td>आडंबर के बजाय मन की शुद्धता पर</td></tr>\n<tr><td>जेकर बेंदरा, तेकरे ले नाचय</td><td>व्यक्ति अपने स्वामी/पालक का ही कहा मानता है</td><td>जब कोई केवल अपने मालिक की बात माने</td></tr>\n<tr><td>ठलहा बनिया का करय, ए कोठी के धान ओ कोठी करय</td><td>बेकार बैठा व्यक्ति व्यर्थ के काम करता है (ठलहा = खाली)</td><td>निठल्लेपन में बेमतलब काम पर</td></tr>\n<tr><td>बड़े-बड़े बोहा गें, गदहा पूछय कतका पानी</td><td>जहाँ समर्थ हार गए, वहाँ असमर्थ का दावा</td><td>सामर्थ्य से बड़ी बात पर</td></tr>\n<tr><td>आगी लगे म कुआँ खोदना</td><td>संकट आने पर ही उपाय करना</td><td>पहले से तैयारी न करने वाले पर</td></tr>\n<tr><td>खेती अपन सेती, नइ त नदिया के रेती</td><td>खेती स्वयं देखभाल करने से ही सफल; नहीं तो रेत समान व्यर्थ</td><td>खेती दूसरों के भरोसे छोड़ने वाले को</td></tr>\n<tr><td>नवा-नवा नौ दिन, जुन्ना-जुन्ना सौ दिन</td><td>नई वस्तु का आकर्षण थोड़े दिन, पुरानी लंबे समय काम आती है (जुन्ना = पुराना)</td><td>पुरानी विश्वसनीय वस्तु की प्रशंसा में</td></tr>\n<tr><td>नवा बइला के नवा सींग, चल रे बइला टिंगे-टिंग</td><td>नए-नए व्यक्ति का अति उत्साह</td><td>नए सदस्य के जोश पर</td></tr>\n<tr><td>जइसे नागनाथ, तइसे साँपनाथ</td><td>दोनों विकल्प एक समान बुरे</td><td>दो बुरों में चुनना हो तब</td></tr>\n<tr><td>मुँह म राम, बगल म छुरी</td><td>ऊपर से मित्रता, भीतर से शत्रुता</td><td>कपटी व्यक्ति के लिए</td></tr>\n<tr><td>जिहाँ चाह, उहाँ राह</td><td>इच्छा दृढ़ हो तो रास्ता निकलता है</td><td>हताश को प्रेरित करते समय</td></tr>\n<tr><td>एक हाथ ले ताली नइ बाजय</td><td>झगड़े में दोनों पक्ष दोषी</td><td>केवल एक को दोष देने पर</td></tr>\n<tr><td>घी के लड्डू टेड़गा घलो भला</td><td>उत्तम वस्तु का रूप बिगड़ा हो तब भी अच्छी</td><td>गुणवान पर सादी वस्तु के लिए</td></tr>\n<tr><td>भूख न जानय जूठा भात, नींद न जानय टूटी खाट</td><td>ज़रूरत के समय सुविधा नहीं देखी जाती</td><td>विवशता में जो मिले स्वीकारने पर</td></tr>\n<tr><td>मार के आगू भूत भागय</td><td>दंड के भय से दुष्ट भी सीधा होता है</td><td>शरारती को डाँट से सुधारने पर</td></tr>\n<tr><td>चोर-चोर मौसेरा भाई</td><td>बुरे लोग आपस में मिले रहते हैं</td><td>दुष्टों की मिलीभगत पर</td></tr>\n<tr><td>पानी म रहि के मगर ले बैर</td><td>आश्रयदाता से शत्रुता करना</td><td>मालिक से बैर करने वाले पर</td></tr>\n<tr><td>अंधरा पीसय, कुकुर खाय</td><td>असावधान की कमाई दूसरे उड़ा ले जाते हैं</td><td>लापरवाह की मेहनत पर</td></tr>\n<tr><td>बोकरा के जीव जाय, खवइया ल अलोना</td><td>एक का भारी नुकसान, फिर भी दूसरे को संतोष नहीं (अलोना = बिना नमक का)</td><td>बड़े त्याग की कद्र न होने पर</td></tr>\n<tr><td>उल्टा चोर कोतवाल ल डाँटय</td><td>दोषी उलटे निर्दोष को दोष दे</td><td>अपराधी के अकड़ने पर</td></tr>\n<tr><td>नौ नगद न तेरह उधार</td><td>उधार के अधिक लाभ से नकद का थोड़ा लाभ अच्छा</td><td>लेन-देन में नकद को प्राथमिकता देते समय</td></tr>\n<tr><td>हाथ कंगन ल आरसी का</td><td>प्रत्यक्ष को प्रमाण की आवश्यकता नहीं (आरसी = दर्पण)</td><td>सामने की बात पर बहस होने पर</td></tr>\n<tr><td>अब पछताय होत का, जब चिरई चुग गे खेत</td><td>अवसर निकलने के बाद पछताना व्यर्थ (चिरई = चिड़िया)</td><td>समय पर काम न करने वाले पर</td></tr>\n<tr><td>का बरसा जब खेती सुखाय</td><td>समय निकलने पर सहायता व्यर्थ</td><td>देर से मिली मदद पर</td></tr>\n<tr><td>रस्सी जर गे, फेर अँइठन नइ गिस</td><td>सब नष्ट होने पर भी घमंड नहीं गया (जर गे = जल गई)</td><td>बर्बाद होकर भी अकड़ने वाले पर</td></tr>\n<tr><td>सौ सुनार के, एक लोहार के</td><td>बलवान का एक प्रहार कमज़ोर के सौ के बराबर</td><td>निर्णायक एक प्रहार पर</td></tr>\n<tr><td>बिच्छी के मंतर नइ जानय, साँप के बिला म हाथ डारय</td><td>सामर्थ्य से बड़ा जोखिम उठाना (बिच्छी = बिच्छू)</td><td>छोटी योग्यता से बड़ा काम करने वाले पर</td></tr>\n<tr><td>चार दिन के चाँदनी, फेर अँधियारी रात</td><td>सुख-वैभव थोड़े दिन का</td><td>क्षणिक सुख पर इतराने वाले को</td></tr>\n<tr><td>कौंवा चलिस हंस के चाल, अपनो चाल भुलागे</td><td>नकल में अपना गुण भी गँवाना</td><td>अंधानुकरण पर</td></tr>\n<tr><td>डूबत ल तिनका के सहारा</td><td>संकट में छोटी सहायता भी बड़ी</td><td>विपत्ति में थोड़ी मदद पर</td></tr>\n<tr><td>होनहार बिरवान के होत चीकन पात</td><td>प्रतिभा बचपन में ही दिख जाती है (बिरवा = पौधा)</td><td>प्रतिभाशाली बालक की प्रशंसा में</td></tr>\n<tr><td>जिहाँ गुड़, उहाँ चाँटी</td><td>जहाँ लाभ, वहाँ लोग जुटते हैं (चाँटी = चींटी)</td><td>स्वार्थी भीड़ पर</td></tr>\n<tr><td>घर के भेदी लंका ढाहय</td><td>घर का भेदी ही सबसे बड़ा नुकसान करता है</td><td>आपसी फूट से हानि पर</td></tr>\n<tr><td>पढ़े फारसी, बेचे तेल</td><td>योग्यता के विपरीत छोटा काम करना पड़ना</td><td>शिक्षित की दुर्दशा पर</td></tr>\n<tr><td>खिसियानी बिलई खंभा नोचय</td><td>लज्जित होकर क्रोध दूसरे पर उतारना</td><td>हार की झेंप में बिगड़ने वाले पर</td></tr>\n<tr><td>अपन दही ल कोनो खट्टा नइ कहय</td><td>अपनी वस्तु की सब प्रशंसा ही करते हैं</td><td>अपनी चीज़ के दोष न मानने पर</td></tr>\n<tr><td>सावन के अंधरा ल हरियर-हरियर सूझथे</td><td>एक स्थिति में पला व्यक्ति सबको वैसा ही समझता है</td><td>एकांगी दृष्टि पर</td></tr>\n<tr><td>बाप न मारिस मेचका, बेटा तीरंदाज</td><td>खानदान में योग्यता न होने पर भी बड़ी-बड़ी बातें (मेचका = मेंढक)</td><td>झूठी शान पर</td></tr>\n<tr><td>कोइला के दलाली म मुँह करिया</td><td>बुरे काम में हाथ डालने से बदनामी अवश्य</td><td>गलत धंधे से बचने की सीख</td></tr>\n<tr><td>ऊँच दुकान, फीका पकवान</td><td>दिखावा अधिक, गुण कम</td><td>बाहरी चमक वाली घटिया चीज़ पर</td></tr>\n<tr><td>नाम बड़े, दरसन छोटे</td><td>ख्याति अधिक, गुण कम</td><td>प्रसिद्ध पर साधारण निकलने पर</td></tr>\n<tr><td>दाँत हे त चना नइ, चना हे त दाँत नइ</td><td>साधन और सामर्थ्य एक साथ न होना</td><td>अवसर व क्षमता के बेमेल पर</td></tr>\n<tr><td>भागत भूत के लँगोटी भली</td><td>जहाँ कुछ न मिलता हो, वहाँ जो मिले वही अच्छा</td><td>डूबे धन में से थोड़ा मिलने पर</td></tr>\n<tr><td>एक तो करेला, ऊपर ले लीम चढ़े</td><td>एक दोष के साथ दूसरा दोष जुड़ना (लीम = नीम)</td><td>बुरे में और बुराई पर</td></tr>\n<tr><td>घर म नइ हे दाना, दाई चलिस भुंजाय</td><td>सामर्थ्य न होने पर भी दिखावा</td><td>हैसियत से बढ़कर दिखावे पर</td></tr>\n<tr><td>रात भर रमायन सुनिस, बिहनिया पूछय सीता काकर ददा</td><td>पूरी बात सुनकर भी कुछ न समझना (काकर = किसका)</td><td>बार-बार समझाने पर भी न समझने वाले पर</td></tr>\n<tr><td>हाथी चलय बजार, कुकुर भूँकय हजार</td><td>महान व्यक्ति निंदकों की परवाह नहीं करते</td><td>आलोचना में अडिग व्यक्ति पर</td></tr>\n<tr><td>धोबी के कुकुर, न घर के न घाट के</td><td>दो पक्षों के बीच कहीं का न रहना</td><td>दुविधा में दोनों ओर से छूटने पर</td></tr>\n<tr><td>जिहाँ न जाय रवि, उहाँ जाय कवि</td><td>कवि की कल्पना हर जगह पहुँचती है</td><td>कल्पना-शक्ति की प्रशंसा में</td></tr>\n<tr><td>थोथा चना, बाजय घना</td><td>कम गुण वाला अधिक बोलता है</td><td>डींग हाँकने वाले अल्पज्ञ पर</td></tr>\n<tr><td>अधजल गगरी छलकत जाय</td><td>अधूरे ज्ञान वाला अधिक दिखावा करता है</td><td>अल्पज्ञ के प्रदर्शन पर</td></tr>\n<tr><td>एक अनार, सौ बीमार</td><td>वस्तु एक, चाहने वाले अनेक</td><td>एक पद के अनेक दावेदारों पर</td></tr>\n<tr><td>जइसन देस, तइसन भेस</td><td>जहाँ रहें, वहाँ के अनुसार आचरण</td><td>नई जगह ढलने की सीख</td></tr>\n<tr><td>आगू नाथ न पाछू पगहा</td><td>कोई ज़िम्मेदारी/बंधन न होना (नाथ = नाक की रस्सी, पगहा = पशु बाँधने की रस्सी)</td><td>अकेले, निश्चिंत व्यक्ति पर</td></tr>\n<tr><td>बिन गुरु गियान नइ</td><td>गुरु के बिना ज्ञान नहीं</td><td>गुरु के महत्त्व पर</td></tr>\n<tr><td>पर उपदेस कुसल बहुतेरे</td><td>दूसरों को उपदेश देना सरल, स्वयं पालन कठिन</td><td>उपदेशक के अपने आचरण पर</td></tr>\n<tr><td>जल्दी के काम सैतान के</td><td>जल्दबाज़ी का काम बिगड़ता है</td><td>हड़बड़ी करने वाले को</td></tr>\n<tr><td>उतावला सो बावला</td><td>जल्दबाज़ मूर्खता कर बैठता है</td><td>अधीर को</td></tr>\n<tr><td>सहज पके सो मीठ होय</td><td>धैर्य से किया काम मीठा फल देता है</td><td>धीरज की सीख</td></tr>\n<tr><td>बूँद-बूँद ले घइला भरथे</td><td>थोड़ा-थोड़ा जोड़ने से बड़ा संचय (घइला = घड़ा)</td><td>बचत की सीख</td></tr>\n<tr><td>सौ दिन चोर के, एक दिन साहूकार के</td><td>अपराधी एक दिन अवश्य पकड़ा जाता है</td><td>बार-बार अपराधी को चेताते समय</td></tr>\n<tr><td>अकेल्ला चना भाड़ नइ फोरय</td><td>अकेला व्यक्ति बड़ा काम नहीं कर सकता</td><td>संगठन के महत्त्व पर</td></tr>\n<tr><td>आप भला त जग भला</td><td>स्वयं अच्छे तो संसार अच्छा</td><td>सद्व्यवहार की सीख</td></tr>\n<tr><td>जइसन संगत, तइसन रंगत</td><td>जैसी संगति, वैसा प्रभाव</td><td>बुरी संगत से बचाने हेतु</td></tr>\n<tr><td>सबो धान बाईस पसेरी</td><td>अच्छे-बुरे सबको एक समान समझना (पसेरी = पाँच सेर)</td><td>विवेकहीन मूल्यांकन पर</td></tr>\n<tr><td>तीन म न तेरह म</td><td>किसी गिनती/पक्ष में न होना</td><td>उपेक्षित/तटस्थ व्यक्ति पर</td></tr>\n<tr><td>नौ सौ मुसुवा खा के बिलई चलिस हज बर</td><td>जीवन भर पाप करके अंत में धर्मात्मा बनने का ढोंग</td><td>पापी के धार्मिक दिखावे पर</td></tr>\n<tr><td>खोदिस पहाड़, निकलिस मुसुवा</td><td>बहुत परिश्रम, बहुत थोड़ा फल</td><td>बड़ी मेहनत के तुच्छ परिणाम पर</td></tr>\n<tr><td>जेन गरजथे, तेन बरसय नइ</td><td>बहुत डींग मारने वाले काम कम करते हैं</td><td>धमकी देने वाले से न डरने की बात में</td></tr>\n<tr><td>बेंदरा के हाथ म उस्तुरा</td><td>अयोग्य के हाथ में अधिकार/खतरनाक वस्तु</td><td>नासमझ को बड़ा अधिकार मिलने पर</td></tr>\n<tr><td>मान न मान, मैं तोर पहुना</td><td>ज़बरदस्ती संबंध जोड़ना (पहुना = मेहमान)</td><td>बिन बुलाए गले पड़ने वाले पर</td></tr>\n<tr><td>अंत भला त सब भला</td><td>परिणाम अच्छा तो सब अच्छा</td><td>कठिनाई के बाद सफल अंत पर</td></tr>\n<tr><td>कुकरा नइ बासही त का बिहान नइ होही</td><td>किसी एक के बिना संसार का काम नहीं रुकता (कुकरा = मुर्गा, बिहान = सवेरा)</td><td>अपने को अपरिहार्य समझने वाले पर</td></tr>\n<tr><td>छोटे मुँह, बड़े गोठ</td><td>हैसियत से बड़ी बात करना (गोठ = बात)</td><td>अपनी स्थिति से बढ़कर बोलने पर</td></tr>\n<tr><td>जतके ओढ़ना, ततके गोड़ लमाय</td><td>आय के अनुसार ही खर्च (ओढ़ना = चादर, लमाय = फैलाए)</td><td>फ़िज़ूलखर्ची रोकने की सीख</td></tr>\n<tr><td>आधा छोड़ पूरा ल धावय, आधा मिलय न पूरा पावय</td><td>लालच में जो पास है वह भी खोना</td><td>अधिक लोभी को</td></tr>\n<tr><td>दीया तरी अँधियार</td><td>निकट की बुराई दिखाई नहीं देती (तरी = नीचे)</td><td>अधिकारी के पास ही गड़बड़ी पर</td></tr>\n<tr><td>बिना बिचारे जो करय, सो पाछू पछताय</td><td>बिना सोचे काम करने वाला बाद में पछताता है</td><td>जल्दबाज़ निर्णय पर</td></tr>\n<tr><td>गुड़ खाय, गुलगुला ले परहेज</td><td>दिखावटी परहेज</td><td>ढोंगी संयम पर</td></tr>\n<tr><td>न रही बाँस, न बाजही बँसुरी</td><td>झगड़े की जड़ ही मिटा देना</td><td>समस्या का मूल नष्ट करने पर</td></tr>\n<tr><td>बिलई के भाग ले सींका टूटिस</td><td>संयोग से अचानक लाभ (सींका = छींका)</td><td>भाग्य से मिले लाभ पर</td></tr>\n<tr><td>अपन-अपन ढपली, अपन-अपन राग</td><td>सबका अलग मत, एकता न होना</td><td>समूह में मतभेद पर</td></tr>\n<tr><td>पाँचो अँगरी बरोबर नइ होवय</td><td>सब लोग एक समान नहीं होते</td><td>सबको एक जैसा समझने वाले को</td></tr>\n<tr><td>काठ के हँड़िया एके बार चढ़थे</td><td>छल-कपट एक ही बार सफल होता है</td><td>बार-बार धोखा देने वाले को</td></tr>\n<tr><td>एक म्यान म दू तलवार नइ समाय</td><td>एक स्थान पर दो समान अधिकारी नहीं रह सकते</td><td>दो प्रतिद्वंद्वियों के टकराव पर</td></tr>\n<tr><td>कहाँ राजा भोज, कहाँ गंगू तेली</td><td>बड़े-छोटे में कोई तुलना नहीं</td><td>बेमेल तुलना पर</td></tr>\n<tr><td>अंधेर नगरी, चौपट राजा</td><td>कुशासन और अन्याय</td><td>अव्यवस्थित शासन पर</td></tr>\n<tr><td>चमड़ी जाय फेर दमड़ी झन जाय</td><td>अत्यधिक कंजूस (दमड़ी = सबसे छोटा सिक्का, झन = मत)</td><td>कंजूस के लिए</td></tr>\n<tr><td>गंगा गे त गंगादास, जमुना गे त जमुनादास</td><td>अवसर देखकर पक्ष बदलने वाला</td><td>अवसरवादी पर</td></tr>\n<tr><td>जंगल म मोर नाचिस, कोन देखिस</td><td>जहाँ कोई देखने वाला न हो, वहाँ गुण-प्रदर्शन व्यर्थ</td><td>अनदेखे अच्छे काम पर</td></tr>\n<tr><td>बाहना म मुड़ डारे त मूसर ले का डर्राना</td><td>कठिन काम हाथ में लिया तो कष्टों से क्या डरना (बाहना = ओखली)</td><td>जोखिम का काम शुरू करने पर</td></tr>\n<tr><td>साँप घलो मर जाय, लाठी घलो झन टूटय</td><td>काम भी बन जाए, हानि भी न हो</td><td>चतुर समाधान पर</td></tr>\n<tr><td>आमा खाय ले मतलब, रुख गिने ले का</td><td>अपने काम से मतलब रखो (रुख = पेड़)</td><td>अनावश्यक पूछताछ पर</td></tr>\n<tr><td>कौंवा के कोसे ले ढोर नइ मरय</td><td>दुष्ट के बुरा चाहने से सज्जन का अहित नहीं होता (ढोर = पशु)</td><td>निंदक की बददुआ पर</td></tr>\n<tr><td>चलनी म दूध दुहय, करम ल दोस देवय</td><td>अपनी मूर्खता से हानि कर भाग्य को दोष देना</td><td>अपनी गलती न मानने वाले पर</td></tr>\n<tr><td>दार-भात म मूसरचंद</td><td>बिना बुलाए दखल देने वाला</td><td>बीच में टाँग अड़ाने वाले पर</td></tr>\n</table>\n<div class=\"tip\">हाना पहचानने की ट्रिक: छत्तीसगढ़ी हाने प्रायः \"जइसन-तइसन\", \"जेकर-तेकर\", \"जिहाँ-उहाँ\", \"जतके-ततके/ओतके\" जैसे सह-संबंधी जोड़ों पर टिके होते हैं — हिन्दी के \"जैसा-वैसा, जिसका-उसका, जहाँ-वहाँ, जितना-उतना\"।</div>\n\n<h3>4. छत्तीसगढ़ी मुहावरे — अर्थ</h3>\n<table><tr><th>मुहावरा</th><th>अर्थ</th><th>मुहावरा</th><th>अर्थ</th></tr>\n<tr><td>आँखी म धुर्रा झोंकना</td><td>धोखा देना</td><td>लबारी मारना</td><td>झूठ बोलना</td></tr>\n<tr><td>आँखी गुड़ेरना</td><td>क्रोध से घूरना</td><td>पेट म मुसुवा कूदना</td><td>बहुत भूख लगना</td></tr>\n<tr><td>करेजा जुड़ाना</td><td>मन को शांति/संतोष मिलना</td><td>दार नइ गलना</td><td>युक्ति सफल न होना</td></tr>\n<tr><td>गोड़ भारी होना</td><td>गर्भवती होना</td><td>छाती म मूँग दरना</td><td>पास रहकर कष्ट देना</td></tr>\n<tr><td>आँखी के पुतरी होना</td><td>अत्यंत प्रिय होना</td><td>गोड़ तरी के भुइयाँ खसकना</td><td>होश उड़ जाना</td></tr>\n<tr><td>कोहनी म गुड़ लगाना</td><td>झूठी आशा/लालच देना</td><td>मुड़ म चढ़ाना</td><td>अधिक लाड़ से बिगाड़ना</td></tr>\n<tr><td>मुँह फुलाना</td><td>रूठ जाना</td><td>कान भरना</td><td>चुगली करना</td></tr>\n<tr><td>नाक कटाना</td><td>प्रतिष्ठा खोना</td><td>हाथ-गोड़ फूलना</td><td>घबरा जाना</td></tr>\n<tr><td>दाँत निपोरना</td><td>गिड़गिड़ाना / बेशर्मी से हँसना</td><td>आँखी फेरना</td><td>उपेक्षा करना, प्रेम घटा लेना</td></tr>\n<tr><td>आँखी बिछाना</td><td>प्रेम से स्वागत करना</td><td>आँखी चुराना</td><td>लज्जा/भय से सामने न आना</td></tr>\n<tr><td>आँखी खुलना</td><td>वास्तविकता का ज्ञान होना</td><td>आँखी के काँटा होना</td><td>अत्यंत अप्रिय लगना</td></tr>\n<tr><td>आँखी म रात काटना</td><td>चिंता में रात भर जागना</td><td>कान खड़ा होना</td><td>सतर्क हो जाना</td></tr>\n<tr><td>कान म तेल डार के बइठना</td><td>बात अनसुनी करना</td><td>कान के कच्चा होना</td><td>सुनी-सुनाई बात पर तुरंत विश्वास करना</td></tr>\n<tr><td>कान पकड़ना</td><td>गलती मानकर फिर न करने का प्रण</td><td>नाक के बाल होना</td><td>अत्यंत प्रिय व विश्वासपात्र होना</td></tr>\n<tr><td>नाक रगड़ना</td><td>दीनता से विनती करना</td><td>नाक म दम करना</td><td>बहुत परेशान करना</td></tr>\n<tr><td>नाक ऊँचा होना</td><td>प्रतिष्ठा बढ़ना</td><td>मुँह म पानी आना</td><td>लालच होना</td></tr>\n<tr><td>मुँह के खाना</td><td>बुरी तरह पराजित होना</td><td>मुँह ताकना</td><td>दूसरे पर आश्रित रहना</td></tr>\n<tr><td>मुँह म दही जमना</td><td>चुप रह जाना</td><td>मुँह करिया करना</td><td>कलंकित करना</td></tr>\n<tr><td>मुँह लुकाना</td><td>लज्जा से छिपना</td><td>मुँह मोड़ना</td><td>विमुख हो जाना</td></tr>\n<tr><td>हाथ धो के पाछू पड़ना</td><td>पूरी तरह पीछे पड़ जाना</td><td>हाथ मलना</td><td>पछताना</td></tr>\n<tr><td>हाथ पसारना</td><td>माँगना</td><td>हाथ खींचना</td><td>सहयोग बंद करना</td></tr>\n<tr><td>हाथ बँटाना</td><td>काम में सहायता करना</td><td>हाथ-पाँव मारना</td><td>बहुत प्रयत्न करना</td></tr>\n<tr><td>गोड़ उखड़ना</td><td>हारकर भाग खड़ा होना</td><td>गोड़ जमाना</td><td>स्थिर होना, स्थान पक्का करना</td></tr>\n<tr><td>पेट म दाढ़ी होना</td><td>कम उम्र में अधिक चतुर</td><td>पेट काटना</td><td>खर्च घटाकर बचत करना</td></tr>\n<tr><td>पेट म बात नइ पचना</td><td>कोई बात छिपा न पाना</td><td>करेजा फटना</td><td>अत्यधिक दुःख होना</td></tr>\n<tr><td>करेजा के टुकड़ा</td><td>अत्यंत प्रिय संतान</td><td>छाती ठोंकना</td><td>साहस से दावा करना</td></tr>\n<tr><td>छाती फूलना</td><td>गर्व अनुभव होना</td><td>छाती म साँप लोटना</td><td>ईर्ष्या होना</td></tr>\n<tr><td>दाँत खट्टा करना</td><td>बुरी तरह हराना</td><td>दाँत काटी रोटी</td><td>गहरी मित्रता</td></tr>\n<tr><td>मुड़ धुनना</td><td>पछताना / शोक करना</td><td>मुड़ उठाना</td><td>विद्रोह करना</td></tr>\n<tr><td>मुड़ म कफन बाँधना</td><td>मरने को तैयार रहना</td><td>परान ल हथेली म धरना</td><td>प्राण संकट में डालना</td></tr>\n<tr><td>माथा ठनकना</td><td>अनिष्ट की आशंका होना</td><td>एड़ी-चोटी के जोर लगाना</td><td>पूरी शक्ति लगाना</td></tr>\n<tr><td>अगास-पताल एक करना</td><td>बहुत अधिक प्रयास करना</td><td>लहू-पसीना एक करना</td><td>कठोर परिश्रम करना</td></tr>\n<tr><td>लहू सूखना</td><td>बहुत डर जाना</td><td>पानी-पानी होना</td><td>बहुत लज्जित होना</td></tr>\n<tr><td>चुल्लू भर पानी म बूड़ मरना</td><td>अत्यंत लज्जित होना</td><td>पानी फेरना</td><td>किए-कराए को नष्ट करना</td></tr>\n<tr><td>आगी बबूला होना</td><td>अत्यंत क्रोधित होना</td><td>आगी म घी डारना</td><td>झगड़ा/क्रोध और भड़काना</td></tr>\n<tr><td>ईंटा ले ईंटा बजाना</td><td>पूर्णतः नष्ट कर देना</td><td>गड़े मुर्दा उखाड़ना</td><td>पुरानी बात फिर उठाना</td></tr>\n<tr><td>घाव म नून छिंचना</td><td>दुखी को और दुःख देना</td><td>डूमर के फूल होना</td><td>दुर्लभ होना (डूमर = गूलर)</td></tr>\n<tr><td>ढोल के पोल खुलना</td><td>असलियत प्रकट होना</td><td>थूक के चाटना</td><td>कही बात से मुकरना</td></tr>\n<tr><td>लोहा मानना</td><td>श्रेष्ठता स्वीकार करना</td><td>लोहा के चना चबाना</td><td>अत्यंत कठिन काम करना</td></tr>\n<tr><td>अपन मुँह मियाँ मिट्ठू बनना</td><td>अपनी प्रशंसा स्वयं करना</td><td>गाल बजाना</td><td>डींग मारना</td></tr>\n<tr><td>दिन म तारा दिखना</td><td>घोर संकट में घबरा जाना</td><td>अँगरी उठाना</td><td>दोष लगाना / आलोचना करना</td></tr>\n<tr><td>अँगरी म नचाना</td><td>पूरी तरह वश में रखना</td><td>टेड़गा अँगरी ले घी निकालना</td><td>कड़ाई/चतुराई से काम निकालना</td></tr>\n<tr><td>पथरा के लकीर</td><td>अमिट, अटल बात</td><td>पइसा ल पानी कस बोहाना</td><td>अंधाधुंध खर्च करना</td></tr>\n<tr><td>चार चाँद लगाना</td><td>शोभा बढ़ाना</td><td>सोना म सुहागा</td><td>अच्छी वस्तु में और अच्छाई</td></tr>\n<tr><td>हवा हो जाना</td><td>गायब हो जाना</td><td>नौ दू ग्यारह होना</td><td>चुपके से भाग जाना</td></tr>\n<tr><td>पीठ देखाना</td><td>मैदान छोड़कर भागना</td><td>पीठ ठोंकना</td><td>शाबाशी देना</td></tr>\n<tr><td>कुआँ के मेचका</td><td>सीमित ज्ञान वाला व्यक्ति</td><td>बेंदरा बाँट</td><td>बीच वाले द्वारा सब हड़पने वाला बँटवारा</td></tr>\n<tr><td>तेली के बइला</td><td>दिन-रात खटने वाला पर आगे न बढ़ने वाला</td><td>दू नाव म गोड़ रखना</td><td>दो पक्षों का साथ एक साथ निभाने की कोशिश</td></tr>\n<tr><td>अँधरा के लाठी</td><td>एकमात्र सहारा</td><td>उल्टा गंगा बोहाना</td><td>परंपरा के विपरीत काम</td></tr>\n<tr><td>घी-खिचरी होना</td><td>बहुत घुलमिल जाना</td><td>खिचरी पकाना</td><td>गुप्त योजना बनाना</td></tr>\n<tr><td>गागर म सागर भरना</td><td>थोड़े शब्दों में बहुत कहना</td><td>तिल के ताड़ बनाना</td><td>छोटी बात को बहुत बढ़ाना</td></tr>\n<tr><td>नून-मिरचा लगाना</td><td>बात बढ़ा-चढ़ाकर कहना</td><td>भुइयाँ म गोड़ नइ परना</td><td>अत्यधिक प्रसन्न होना</td></tr>\n<tr><td>लकीर के फकीर</td><td>आँख मूँदकर पुरानी परंपरा पर चलने वाला</td><td>अक्कल के दुसमन</td><td>मूर्ख व्यक्ति</td></tr>\n<tr><td>कनिहा कसना</td><td>किसी काम के लिए तैयार होना</td><td>कनिहा टूटना</td><td>हिम्मत/आर्थिक शक्ति टूटना</td></tr>\n<tr><td>गर के हार होना</td><td>अत्यंत प्रिय होना</td><td>गुड़-गोबर करना</td><td>बना-बनाया काम बिगाड़ना</td></tr>\n<tr><td>आँधी के आमा</td><td>बिना परिश्रम मिली सस्ती वस्तु</td><td>हथियार डारना</td><td>हार मान लेना</td></tr>\n<tr><td>भीजे बिलई बनना</td><td>डर से सहम जाना</td><td>आँसू पोंछना</td><td>सांत्वना देना</td></tr>\n<tr><td>बात के धनी</td><td>वचन का पक्का</td><td>बात बनाना</td><td>बहाना बनाना</td></tr>\n<tr><td>मन के लड्डू खाना</td><td>कल्पना में ही प्रसन्न होना</td><td>हवा म महल बनाना</td><td>काल्पनिक योजनाएँ बनाना</td></tr>\n<tr><td>करम फूटना</td><td>भाग्य खराब होना</td><td>गंगा नहाना</td><td>कठिन काम पूरा कर निश्चिंत होना</td></tr>\n<tr><td>अपन गोड़ म टँगिया मारना</td><td>अपना नुकसान स्वयं करना</td><td>गोड़ पसारना</td><td>प्रभाव/क्षेत्र फैलाना</td></tr>\n</table>\n<div class=\"tip\">शरीर-अंग वाले मुहावरे सबसे अधिक पूछे जाते हैं — पहले अंग का छत्तीसगढ़ी नाम पहचानें: <b>मुड़</b> = सिर, <b>आँखी</b> = आँख, <b>गोड़</b> = पैर, <b>करेजा</b> = कलेजा, <b>कनिहा</b> = कमर, <b>अँगरी</b> = उँगली, <b>गर</b> = गला। फिर हिन्दी मुहावरे से मिलाएँ (मुड़ धुनना = सिर धुनना, कनिहा टूटना = कमर टूटना)।</div>\n\n<h3>5. छत्तीसगढ़ी शब्द-भंडार</h3>\n<h4>(क) रिश्ते-नाते</h4>\n<table><tr><th>छत्तीसगढ़ी</th><th>हिन्दी</th><th>छत्तीसगढ़ी</th><th>हिन्दी</th><th>छत्तीसगढ़ी</th><th>हिन्दी</th></tr>\n<tr><td>दाई</td><td>माँ</td><td>ददा</td><td>पिता</td><td>दाई-ददा</td><td>माता-पिता</td></tr>\n<tr><td>बबा</td><td>दादा</td><td>डोकरी दाई</td><td>दादी</td><td>डोकरा</td><td>बूढ़ा</td></tr>\n<tr><td>कका</td><td>चाचा</td><td>काकी</td><td>चाची</td><td>बड़े ददा</td><td>ताऊ</td></tr>\n<tr><td>ममा</td><td>मामा</td><td>मामी</td><td>मामी</td><td>फूफू</td><td>बुआ</td></tr>\n<tr><td>भाँटो</td><td>जीजा</td><td>भउजी</td><td>भाभी</td><td>बहिनी</td><td>बहन</td></tr>\n<tr><td>सारा</td><td>साला</td><td>सारी</td><td>साली</td><td>दमांद</td><td>दामाद</td></tr>\n<tr><td>बहुरिया / बहू</td><td>बहू</td><td>नाती</td><td>पोता / नाती</td><td>भतीजा</td><td>भतीजा</td></tr>\n<tr><td>डउका</td><td>पति</td><td>डउकी</td><td>पत्नी</td><td>गोसइयाँ</td><td>पति / मालिक</td></tr>\n<tr><td>गोसइन</td><td>पत्नी / मालकिन</td><td>नोनी</td><td>लड़की, बेटी</td><td>बाबू</td><td>लड़का, बेटा (स्नेह से)</td></tr>\n<tr><td>टूरा</td><td>लड़का</td><td>टूरी</td><td>लड़की</td><td>लइका</td><td>बच्चा</td></tr>\n<tr><td>सियान</td><td>बुज़ुर्ग</td><td>मितान</td><td>मित्र</td><td>पहुना</td><td>मेहमान / दामाद</td></tr>\n<tr><td>सगा</td><td>रिश्तेदार</td><td>मनखे</td><td>मनुष्य</td><td>संगवारी</td><td>साथी, मित्र</td></tr></table>\n\n<h4>(ख) शरीर के अंग</h4>\n<table><tr><th>छत्तीसगढ़ी</th><th>हिन्दी</th><th>छत्तीसगढ़ी</th><th>हिन्दी</th><th>छत्तीसगढ़ी</th><th>हिन्दी</th></tr>\n<tr><td>मुड़</td><td>सिर</td><td>चुंदी</td><td>बाल</td><td>आँखी</td><td>आँख</td></tr>\n<tr><td>ओंठ</td><td>होंठ</td><td>घेंच</td><td>गर्दन</td><td>गर</td><td>गला</td></tr>\n<tr><td>खांध</td><td>कंधा</td><td>अँगरी</td><td>उँगली</td><td>नख</td><td>नाखून</td></tr>\n<tr><td>कनिहा</td><td>कमर</td><td>माड़ी</td><td>घुटना</td><td>गोड़</td><td>पैर</td></tr>\n<tr><td>करेजा</td><td>कलेजा</td><td>देंह</td><td>शरीर</td><td>पीठ</td><td>पीठ</td></tr></table>\n\n<h4>(ग) खान-पान, साग-सब्ज़ी, फल</h4>\n<table><tr><th>छत्तीसगढ़ी</th><th>हिन्दी</th><th>छत्तीसगढ़ी</th><th>हिन्दी</th><th>छत्तीसगढ़ी</th><th>हिन्दी</th></tr>\n<tr><td>भात</td><td>पका चावल</td><td>चाउँर</td><td>चावल (कच्चा)</td><td>दार</td><td>दाल</td></tr>\n<tr><td>साग</td><td>सब्ज़ी</td><td>भाजी</td><td>पत्तेदार सब्ज़ी</td><td>बासी</td><td>रात में पानी में भिगोया पका भात</td></tr>\n<tr><td>पेज</td><td>चावल का माँड़-युक्त पतला पेय</td><td>मही</td><td>छाछ</td><td>घीव</td><td>घी</td></tr>\n<tr><td>गुर</td><td>गुड़</td><td>नून</td><td>नमक</td><td>हरदी</td><td>हल्दी</td></tr>\n<tr><td>लसुन</td><td>लहसुन</td><td>गोंदली</td><td>प्याज़</td><td>पताल</td><td>टमाटर</td></tr>\n<tr><td>भाटा</td><td>बैंगन</td><td>रमकेलिया</td><td>भिंडी</td><td>मुनगा</td><td>सहजन</td></tr>\n<tr><td>कुम्हड़ा</td><td>कद्दू</td><td>तुमा</td><td>लौकी</td><td>जिमीकांदा</td><td>जमीकंद (सूरन)</td></tr>\n<tr><td>कलिंदर</td><td>तरबूज</td><td>जोंधरी</td><td>मक्का (भुट्टा)</td><td>कुसियार</td><td>गन्ना</td></tr>\n<tr><td>बोइर</td><td>बेर</td><td>बिही</td><td>अमरूद</td><td>अमली</td><td>इमली</td></tr>\n<tr><td>केरा</td><td>केला</td><td>आमा</td><td>आम</td><td>मुर्रा</td><td>मुरमुरा</td></tr>\n<tr><td>राहेर</td><td>अरहर</td><td>उरिद</td><td>उड़द</td><td>तिवरा</td><td>खेसारी (लाखड़ी)</td></tr>\n<tr><td>गहूँ</td><td>गेहूँ</td><td>मिरचा</td><td>मिर्च</td><td>लाई</td><td>लावा (भुना धान)</td></tr></table>\n<p>प्रमुख छत्तीसगढ़ी व्यंजन: चीला, फरा, अंगाकर रोटी, ठेठरी, खुरमी, अइरसा, देहरौरी, चौसेला, बोबरा; पेय — पेज, बासी।</p>\n\n<h4>(घ) खेती-किसानी</h4>\n<table><tr><th>छत्तीसगढ़ी</th><th>हिन्दी</th><th>छत्तीसगढ़ी</th><th>हिन्दी</th></tr>\n<tr><td>नाँगर</td><td>हल</td><td>बइला</td><td>बैल</td></tr>\n<tr><td>कोठार</td><td>खलिहान</td><td>कोठी</td><td>अनाज रखने का भंडार</td></tr>\n<tr><td>कोठा</td><td>पशुशाला</td><td>गरुवा</td><td>मवेशी</td></tr>\n<tr><td>बोनी</td><td>बुवाई</td><td>खुर्रा बोनी</td><td>सूखे खेत में (वर्षा से पहले) बुवाई</td></tr>\n<tr><td>रोपा</td><td>धान की रोपाई</td><td>बियासी</td><td>खड़ी धान की फसल में हल चलाना</td></tr>\n<tr><td>निंदई</td><td>निराई</td><td>लुवई</td><td>कटाई</td></tr>\n<tr><td>मिंजई</td><td>मड़ाई (दाना अलग करना)</td><td>पैरा</td><td>पुआल</td></tr>\n<tr><td>खातू</td><td>खाद</td><td>कुदारी</td><td>कुदाल</td></tr>\n<tr><td>रापा</td><td>फावड़ा</td><td>टँगिया</td><td>कुल्हाड़ी</td></tr>\n<tr><td>हँसिया</td><td>हँसिया (फसल काटने का औज़ार)</td><td>बरदी</td><td>मवेशियों का झुंड</td></tr>\n<tr><td>खुमरी</td><td>बाँस-पत्तों की छतरीनुमा टोपी</td><td>बारी</td><td>घर से लगी सब्ज़ी-बाड़ी</td></tr>\n<tr><td>धरसा</td><td>खेतों के बीच का कच्चा रास्ता</td><td>मेड़</td><td>खेत की सीमा-मेड़</td></tr>\n<tr><td>डोली</td><td>खेत</td><td>खार</td><td>गाँव से बाहर खेतों का बड़ा मैदान</td></tr>\n<tr><td>कन्हार</td><td>काली (भारी) मिट्टी</td><td>भाठा</td><td>कंकरीली, कम उपजाऊ ऊँची भूमि</td></tr>\n<tr><td>बहरा</td><td>नीची, पानी रुकने वाली भूमि</td><td>टिकरा</td><td>ऊँची भूमि</td></tr></table>\n<p>छत्तीसगढ़ के मैदान की चार प्रमुख मिट्टियाँ (स्थानीय नाम): <b>कन्हार</b> (काली), <b>मटासी</b> (पीली-भूरी, दोमट), <b>डोरसा</b> (कन्हार और मटासी के बीच की) और <b>भाठा</b> (कंकरीली-लाल, कम उपजाऊ)।</p>\n\n<h4>(ङ) घर-गृहस्थी</h4>\n<table><tr><th>छत्तीसगढ़ी</th><th>हिन्दी</th><th>छत्तीसगढ़ी</th><th>हिन्दी</th><th>छत्तीसगढ़ी</th><th>हिन्दी</th></tr>\n<tr><td>कुरिया</td><td>छोटा कमरा, झोपड़ी</td><td>अँगना</td><td>आँगन</td><td>परछी</td><td>बरामदा</td></tr>\n<tr><td>छानी</td><td>छप्पर</td><td>दुवारी</td><td>दरवाज़ा (द्वार)</td><td>भिथिया</td><td>दीवार</td></tr>\n<tr><td>हँड़िया</td><td>हांडी</td><td>कराही</td><td>कड़ाही</td><td>थारी</td><td>थाली</td></tr>\n<tr><td>सूपा</td><td>सूप</td><td>चलनी</td><td>छलनी</td><td>टुकना</td><td>बड़ी टोकरी</td></tr>\n<tr><td>पर्रा</td><td>बाँस की बड़ी चपटी टोकरी</td><td>बहरी</td><td>झाड़ू</td><td>खटिया</td><td>खाट</td></tr>\n<tr><td>कथरी</td><td>गुदड़ी</td><td>लुगरा</td><td>साड़ी</td><td>पोलखा</td><td>ब्लाउज़</td></tr>\n<tr><td>पागा</td><td>पगड़ी</td><td>पनही</td><td>जूता-चप्पल</td><td>ककई</td><td>कंघी</td></tr>\n<tr><td>ढेंकी</td><td>धान कूटने का लकड़ी का यंत्र</td><td>जाँता</td><td>हाथ-चक्की</td><td>बाहना</td><td>ओखली</td></tr>\n<tr><td>मूसर</td><td>मूसल</td><td>घइला</td><td>घड़ा</td><td>डबरी</td><td>छोटा तालाब</td></tr>\n<tr><td>तरिया</td><td>तालाब</td><td>दीया</td><td>दीपक</td><td>मुंदरी</td><td>अँगूठी</td></tr></table>\n\n<h4>(च) प्रकृति, समय एवं दिशाएँ</h4>\n<table><tr><th>छत्तीसगढ़ी</th><th>हिन्दी</th><th>छत्तीसगढ़ी</th><th>हिन्दी</th><th>छत्तीसगढ़ी</th><th>हिन्दी</th></tr>\n<tr><td>अगास</td><td>आकाश</td><td>भुइयाँ</td><td>धरती</td><td>सुरुज</td><td>सूर्य</td></tr>\n<tr><td>चंदा</td><td>चंद्रमा</td><td>चंदैनी</td><td>तारे</td><td>बादर</td><td>बादल</td></tr>\n<tr><td>करा</td><td>ओला</td><td>पुरवाही</td><td>पूर्व से चलने वाली हवा</td><td>धुर्रा</td><td>धूल</td></tr>\n<tr><td>चिखला</td><td>कीचड़</td><td>पथरा</td><td>पत्थर</td><td>पाना</td><td>पत्ता</td></tr>\n<tr><td>डारा</td><td>डाल (शाखा)</td><td>रुख</td><td>पेड़</td><td>बन</td><td>जंगल</td></tr>\n<tr><td>घाम</td><td>धूप</td><td>जाड़</td><td>ठंड</td><td>छइहाँ</td><td>छाया</td></tr>\n<tr><td>बिहनिया</td><td>सुबह</td><td>मंझनिया</td><td>दोपहर</td><td>संझा</td><td>शाम</td></tr>\n<tr><td>रतिहा</td><td>रात</td><td>बिहान</td><td>सवेरा / अगला दिन</td><td>बेरा</td><td>समय</td></tr>\n<tr><td>अबेर</td><td>देर</td><td>काली</td><td>कल (बीता या आने वाला)</td><td>बछर</td><td>वर्ष</td></tr>\n<tr><td>उत्ती</td><td>पूर्व दिशा</td><td>बुड़ती</td><td>पश्चिम दिशा</td><td>रक्सहूँ</td><td>दक्षिण दिशा</td></tr>\n<tr><td>भंडार</td><td>उत्तर दिशा</td><td>खाल्हे</td><td>नीचे</td><td>ऊपर</td><td>ऊपर</td></tr></table>\n<div class=\"tip\">दिशा-ट्रिक: <b>उत्ती</b> = सूर्य के उदय (उठने) की दिशा = पूर्व; <b>बुड़ती</b> = सूर्य के बूड़ने (डूबने) की दिशा = पश्चिम; <b>रक्सहूँ</b> = दक्षिण; <b>भंडार</b> = उत्तर।</div>\n\n<h4>(छ) पशु-पक्षी, जीव-जंतु</h4>\n<table><tr><th>छत्तीसगढ़ी</th><th>हिन्दी</th><th>छत्तीसगढ़ी</th><th>हिन्दी</th><th>छत्तीसगढ़ी</th><th>हिन्दी</th></tr>\n<tr><td>कुकुर</td><td>कुत्ता</td><td>बिलई</td><td>बिल्ली</td><td>मुसुवा</td><td>चूहा</td></tr>\n<tr><td>बघवा</td><td>बाघ</td><td>कोलिहा</td><td>सियार</td><td>बेंदरा</td><td>बंदर</td></tr>\n<tr><td>भइंस</td><td>भैंस</td><td>छेरी</td><td>बकरी</td><td>बोकरा</td><td>बकरा</td></tr>\n<tr><td>गोल्लर</td><td>साँड</td><td>मंजूर</td><td>मोर</td><td>कुकरा</td><td>मुर्गा</td></tr>\n<tr><td>सुवा</td><td>तोता</td><td>परेवा</td><td>कबूतर</td><td>कौंवा</td><td>कौआ</td></tr>\n<tr><td>कोकड़ा</td><td>बगुला</td><td>घुघुवा</td><td>उल्लू</td><td>चिरई</td><td>चिड़िया</td></tr>\n<tr><td>मेचका</td><td>मेंढक</td><td>केकरा</td><td>केकड़ा</td><td>बिच्छी</td><td>बिच्छू</td></tr>\n<tr><td>मकरा</td><td>मकड़ी</td><td>चाँटी</td><td>चींटी</td><td>माछी</td><td>मक्खी</td></tr>\n<tr><td>मछरी</td><td>मछली</td><td>दियाँर</td><td>दीमक</td><td>गदहा</td><td>गधा</td></tr></table>\n\n<h4>(ज) संख्या, दिन, महीने</h4>\n<table><tr><th>छत्तीसगढ़ी</th><th>हिन्दी</th><th>छत्तीसगढ़ी</th><th>हिन्दी</th><th>छत्तीसगढ़ी</th><th>हिन्दी</th></tr>\n<tr><td>दू</td><td>दो</td><td>छै</td><td>छह</td><td>बारा</td><td>बारह</td></tr>\n<tr><td>पंदरा</td><td>पंद्रह</td><td>अठारा</td><td>अठारह</td><td>कोरी</td><td>बीस (20) की इकाई</td></tr>\n<tr><td>पहिली</td><td>पहला</td><td>दूसर</td><td>दूसरा</td><td>अढ़ाई</td><td>ढाई</td></tr>\n<tr><td>इतवार</td><td>रविवार</td><td>बिरस्पत</td><td>बृहस्पतिवार</td><td>सनिच्चर</td><td>शनिवार</td></tr>\n<tr><td>चइत</td><td>चैत्र</td><td>कुवाँर</td><td>आश्विन (क्वार)</td><td>कातिक</td><td>कार्तिक</td></tr>\n<tr><td>अग्घन</td><td>मार्गशीर्ष (अगहन)</td><td>पूस</td><td>पौष</td><td>सावन</td><td>श्रावण</td></tr></table>\n<p>गिनती की \"कोरी\" प्रणाली: एक कोरी = 20, दू कोरी = 40, पाँच कोरी = 100, अठारा कोरी = 360। गाँवों में अंडे, आम, कंडे आदि कोरी में गिने जाते हैं।</p>\n\n<h4>(झ) विशेषण, क्रिया-विशेषण, प्रश्नवाचक</h4>\n<table><tr><th>छत्तीसगढ़ी</th><th>हिन्दी</th><th>छत्तीसगढ़ी</th><th>हिन्दी</th><th>छत्तीसगढ़ी</th><th>हिन्दी</th></tr>\n<tr><td>बने</td><td>अच्छा</td><td>सुग्घर</td><td>सुंदर</td><td>अड़बड़</td><td>बहुत</td></tr>\n<tr><td>थोरकुन</td><td>थोड़ा</td><td>जम्मो</td><td>सब, सारा</td><td>नानकुन</td><td>छोटा</td></tr>\n<tr><td>बड़का</td><td>बड़ा</td><td>उज्जर</td><td>सफ़ेद</td><td>करिया</td><td>काला</td></tr>\n<tr><td>पीयर</td><td>पीला</td><td>हरियर</td><td>हरा</td><td>मीठ</td><td>मीठा</td></tr>\n<tr><td>करू</td><td>कड़वा</td><td>चुरपुर</td><td>तीखा</td><td>अलोना</td><td>बिना नमक का</td></tr>\n<tr><td>पातर</td><td>पतला</td><td>गरू</td><td>भारी</td><td>हरु</td><td>हल्का</td></tr>\n<tr><td>जुड़</td><td>ठंडा</td><td>तात</td><td>गरम</td><td>जुन्ना</td><td>पुराना</td></tr>\n<tr><td>नवा</td><td>नया</td><td>बाहिर</td><td>बाहर</td><td>भीतरी</td><td>अंदर</td></tr>\n<tr><td>आगू</td><td>आगे</td><td>पाछू</td><td>पीछे</td><td>तीर</td><td>पास</td></tr>\n<tr><td>दुरिहा</td><td>दूर</td><td>इहाँ</td><td>यहाँ</td><td>उहाँ</td><td>वहाँ</td></tr>\n<tr><td>कहाँ</td><td>कहाँ</td><td>कइसे</td><td>कैसे</td><td>काबर</td><td>क्यों</td></tr>\n<tr><td>कतका</td><td>कितना</td><td>कोन</td><td>कौन</td><td>का</td><td>क्या</td></tr>\n<tr><td>घलो</td><td>भी</td><td>हव</td><td>हाँ</td><td>नइ</td><td>नहीं</td></tr>\n<tr><td>झन</td><td>मत (निषेध)</td><td>अउ</td><td>और</td><td>फेर</td><td>फिर / परंतु</td></tr>\n<tr><td>असन / कस</td><td>जैसा</td><td>बरोबर</td><td>बराबर</td><td>अबड़</td><td>बहुत</td></tr></table>\n\n<h4>(ञ) सामान्य क्रियाएँ</h4>\n<table><tr><th>छत्तीसगढ़ी</th><th>हिन्दी</th><th>छत्तीसगढ़ी</th><th>हिन्दी</th><th>छत्तीसगढ़ी</th><th>हिन्दी</th></tr>\n<tr><td>गोठियाना</td><td>बात करना</td><td>रेंगना</td><td>चलना</td><td>सुतना</td><td>सोना (नींद)</td></tr>\n<tr><td>बिसाना</td><td>खरीदना</td><td>राँधना</td><td>भोजन पकाना</td><td>बुताना</td><td>बुझाना</td></tr>\n<tr><td>अगोरना</td><td>प्रतीक्षा करना</td><td>चिन्हना</td><td>पहचानना</td><td>टोरना</td><td>तोड़ना</td></tr>\n<tr><td>डर्राना</td><td>डरना</td><td>सकेलना</td><td>समेटना, इकट्ठा करना</td><td>हाँसना</td><td>हँसना</td></tr>\n<tr><td>हेरना</td><td>निकालना / खोजना</td><td>बोंना</td><td>बोना</td><td>लूना</td><td>फसल काटना</td></tr></table>\n\n<h3>6. सर्वनाम एवं क्रिया-रूप</h3>\n<table><tr><th>हिन्दी</th><th>छत्तीसगढ़ी (कर्ता)</th><th>संबंध (का/की)</th><th>कर्म (को)</th></tr>\n<tr><td>मैं</td><td>मैं / मँय</td><td>मोर (मेरा)</td><td>मोला (मुझे)</td></tr>\n<tr><td>हम</td><td>हमन</td><td>हमर (हमारा)</td><td>हमन ल (हमें)</td></tr>\n<tr><td>तू / तुम</td><td>तैं / तँय</td><td>तोर (तेरा)</td><td>तोला (तुझे)</td></tr>\n<tr><td>तुम लोग / आप</td><td>तुमन</td><td>तुंहर (तुम्हारा)</td><td>तुमन ल</td></tr>\n<tr><td>वह</td><td>वो / ओ</td><td>ओकर (उसका)</td><td>ओला (उसे)</td></tr>\n<tr><td>वे</td><td>ओमन</td><td>ओमन के (उनका)</td><td>ओमन ल (उन्हें)</td></tr>\n<tr><td>यह</td><td>ए / येहा</td><td>एकर (इसका)</td><td>एला (इसे)</td></tr>\n<tr><td>जो / सो</td><td>जेन / तेन</td><td>जेकर / तेकर (जिसका / उसका)</td><td>जेला / तेला</td></tr></table>\n<p>कारक-चिह्न: <b>ल</b> = को, <b>ले</b> = से, <b>म</b> = में, <b>के</b> = का/की/के, <b>बर</b> = के लिए, <b>ह</b> = कर्ता के साथ बल देने वाला निपात (राम ह = राम ने/राम)।</p>\n<table><tr><th>कर्ता</th><th>वर्तमान (जाना)</th><th>भूत</th><th>भविष्य</th><th>\"होना\" (वर्तमान)</th></tr>\n<tr><td>मैं</td><td>जाथँव (जाता हूँ)</td><td>गेंव (गया)</td><td>जाहूँ (जाऊँगा)</td><td>हँव (हूँ)</td></tr>\n<tr><td>तैं</td><td>जाथस (जाते हो)</td><td>गेस</td><td>जाबे</td><td>हस (हो)</td></tr>\n<tr><td>वो</td><td>जाथे (जाता है)</td><td>गिस (गया)</td><td>जाही (जाएगा)</td><td>हे (है)</td></tr>\n<tr><td>हमन</td><td>जाथन (जाते हैं)</td><td>गेन</td><td>जाबो (जाएँगे)</td><td>हन (हैं)</td></tr>\n<tr><td>तुमन</td><td>जाथव</td><td>गेव</td><td>जाहू</td><td>हव</td></tr>\n<tr><td>ओमन</td><td>जाथें</td><td>गिन</td><td>जाहीं</td><td>हें</td></tr></table>\n<p>इसी प्रकार: करथँव (करता हूँ), करथे (करता है), करिस (किया), करही (करेगा); खाथँव, खाथे, खाइस, खाही। सतत रूप: \"मैं जावत हँव\" (मैं जा रहा हूँ), \"वो खावत हे\" (वह खा रहा है)। भूतकाल का \"रहिस\" = था, \"रहेंव\" = (मैं) था। निषेध: \"नइ जाँव\" (नहीं जाऊँगा/जाता), आज्ञा-निषेध: \"झन जा\" (मत जा)।</p>\n\n<h3>7. रोज़मर्रा के वाक्यांश</h3>\n<table><tr><th>छत्तीसगढ़ी</th><th>हिन्दी</th></tr>\n<tr><td>जय जोहार / राम-राम</td><td>नमस्कार (अभिवादन)</td></tr>\n<tr><td>कइसे हस? / का हाल-चाल हे?</td><td>कैसे हो? / क्या हाल-चाल है?</td></tr>\n<tr><td>बने हँव</td><td>ठीक हूँ</td></tr>\n<tr><td>तोर नाँव का हे?</td><td>तुम्हारा नाम क्या है?</td></tr>\n<tr><td>कहाँ जावत हस?</td><td>कहाँ जा रहे हो?</td></tr>\n<tr><td>आवव, बइठव</td><td>आइए, बैठिए</td></tr>\n<tr><td>भात खा ले</td><td>भोजन कर लो</td></tr>\n<tr><td>मोला नइ पता</td><td>मुझे नहीं पता</td></tr>\n<tr><td>काली आहूँ</td><td>कल आऊँगा</td></tr>\n<tr><td>अड़बड़ सुग्घर हे</td><td>बहुत सुंदर है</td></tr>\n<tr><td>थोरकुन अगोर</td><td>थोड़ा रुको / प्रतीक्षा करो</td></tr>\n<tr><td>झन डर्रा</td><td>मत डरो</td></tr>\n<tr><td>का करत हस?</td><td>क्या कर रहे हो?</td></tr>\n<tr><td>गोठ बात कर ले</td><td>बातचीत कर लो</td></tr>\n<tr><td>छत्तीसगढ़िया सबले बढ़िया</td><td>छत्तीसगढ़ के लोग सबसे अच्छे (प्रसिद्ध नारा)</td></tr></table>\n",
  extra: "\n<h3>हिन्दी लोकोक्तियों के छत्तीसगढ़ी समतुल्य</h3>\n<table><tr><th>हिन्दी लोकोक्ति</th><th>छत्तीसगढ़ी हाना</th></tr>\n<tr><td>जैसी करनी, वैसी भरनी / जैसा बोओगे वैसा काटोगे</td><td>जइसन बोंही, तइसन लूही</td></tr>\n<tr><td>आम के आम, गुठलियों के दाम</td><td>आमा के आमा, गोही के दाम</td></tr>\n<tr><td>दूध का जला छाछ भी फूँक-फूँक कर पीता है</td><td>दूध के जरे ह मही ल फूँक-फूँक के पीथे</td></tr>\n<tr><td>भैंस के आगे बीन बजाए, भैंस खड़ी पगुराय</td><td>भइंस के आगू बीन बजाय, भइंस बइठे पगुराय</td></tr>\n<tr><td>सिर मुँड़ाते ही ओले पड़े</td><td>मुड़ मुड़ावत ओला परगे</td></tr>\n<tr><td>काला अक्षर भैंस बराबर</td><td>करिया अक्छर भइंस बरोबर</td></tr>\n<tr><td>कुत्ते की दुम टेढ़ी की टेढ़ी</td><td>कुकुर के पूँछी टेड़गा के टेड़गा</td></tr>\n<tr><td>आगे नाथ न पीछे पगहा</td><td>आगू नाथ न पाछू पगहा</td></tr>\n<tr><td>बकरे की जान गई, खाने वाले को स्वाद न आया</td><td>बोकरा के जीव जाय, खवइया ल अलोना</td></tr>\n<tr><td>घर की मुर्गी दाल बराबर</td><td>घर के मुर्गी दार बरोबर</td></tr>\n<tr><td>नौ सौ चूहे खाकर बिल्ली हज को चली</td><td>नौ सौ मुसुवा खा के बिलई चलिस हज बर</td></tr>\n<tr><td>खोदा पहाड़, निकली चुहिया</td><td>खोदिस पहाड़, निकलिस मुसुवा</td></tr>\n<tr><td>ओखली में सिर दिया तो मूसल से क्या डरना</td><td>बाहना म मुड़ डारे त मूसर ले का डर्राना</td></tr>\n<tr><td>तेते पाँव पसारिए, जेती लाँबी सौर</td><td>जतके ओढ़ना, ततके गोड़ लमाय</td></tr>\n<tr><td>चिराग तले अँधेरा</td><td>दीया तरी अँधियार</td></tr>\n<tr><td>बिल्ली के भाग्य से छींका टूटा</td><td>बिलई के भाग ले सींका टूटिस</td></tr>\n<tr><td>सारी रामायण सुन ली, सीता किसका बाप?</td><td>रात भर रमायन सुनिस, बिहनिया पूछय सीता काकर ददा</td></tr>\n<tr><td>अकेला चना भाड़ नहीं फोड़ सकता</td><td>अकेल्ला चना भाड़ नइ फोरय</td></tr>\n<tr><td>एक तो करेला, दूजा नीम चढ़ा</td><td>एक तो करेला, ऊपर ले लीम चढ़े</td></tr>\n<tr><td>सब धान बाईस पसेरी</td><td>सबो धान बाईस पसेरी</td></tr></table>\n<div class=\"tip\">ध्वनि-परिवर्तन के नियम जिनसे हिन्दी हाना छत्तीसगढ़ी बनता है: <b>ल</b> = को, <b>ले</b> = से/के बाद, <b>म</b> = में; \"ड़/ल\" का \"र\" (जला → जरे, दाल → दार, गुड़ → गुर); \"स\" अधिकतर बना रहता है पर \"श\" → \"स\" (शैतान → सैतान, देश → देस); \"क्ष\" → \"छ\" (अक्षर → अक्छर); टेढ़ा → टेड़गा।</div>\n\n<h3>भ्रम पैदा करने वाले शब्द-युग्म</h3>\n<table><tr><th>शब्द</th><th>सही अर्थ</th><th>किससे भ्रम होता है</th></tr>\n<tr><td>भाटा</td><td>बैंगन</td><td><b>भाठा</b> = कंकरीली कम उपजाऊ भूमि</td></tr>\n<tr><td>पताल</td><td>टमाटर</td><td>हिन्दी \"पाताल\" (नीचे का लोक) नहीं</td></tr>\n<tr><td>मुनगा</td><td>सहजन</td><td>\"मूँग\" दाल नहीं</td></tr>\n<tr><td>गोंदली</td><td>प्याज़</td><td>\"गोंद\" नहीं; लहसुन = लसुन</td></tr>\n<tr><td>कोठा / कोठी / कोठार</td><td>पशुशाला / अनाज-भंडार / खलिहान</td><td>तीनों एक-दूसरे से उलझते हैं</td></tr>\n<tr><td>तुमा / कुम्हड़ा</td><td>लौकी / कद्दू</td><td>दोनों बेल वाली सब्ज़ियाँ</td></tr>\n<tr><td>बोइर / बिही</td><td>बेर / अमरूद</td><td>\"बिही\" को सेब समझने की भूल</td></tr>\n<tr><td>गरू / हरु</td><td>भारी / हल्का</td><td>ठीक उलटे अर्थ</td></tr>\n<tr><td>जुड़ / तात</td><td>ठंडा / गरम</td><td>\"जुड़ाना\" = ठंडा या शांत होना</td></tr>\n<tr><td>करू / चुरपुर</td><td>कड़वा / तीखा</td><td>दोनों स्वाद-सूचक</td></tr>\n<tr><td>मंजूर</td><td>मोर</td><td>हिन्दी \"मंज़ूर\" (स्वीकृत) नहीं</td></tr>\n<tr><td>सुवा / सूजी</td><td>तोता / सुई</td><td>\"सुआ नृत्य\" तोते के प्रतीक से जुड़ा है</td></tr>\n<tr><td>बारी</td><td>घर से लगी बाड़ी; पारी (बारी)</td><td>प्रसंग से अर्थ तय होता है</td></tr>\n<tr><td>काली</td><td>कल (बीता या आने वाला)</td><td>देवी \"काली\" या रंग \"काला\" नहीं; काला = करिया</td></tr>\n<tr><td>करा</td><td>ओला</td><td>\"करना\" क्रिया नहीं</td></tr>\n<tr><td>पहुना</td><td>मेहमान (विशेषकर दामाद)</td><td>\"पाहुना\" का ही रूप</td></tr>\n<tr><td>माड़ी</td><td>घुटना</td><td>\"माँड़\" (चावल का पानी) नहीं</td></tr>\n<tr><td>भंडार</td><td>उत्तर दिशा</td><td>हिन्दी \"भंडार\" (गोदाम) नहीं; अनाज-भंडार = कोठी</td></tr>\n<tr><td>उत्ती / बुड़ती</td><td>पूर्व / पश्चिम</td><td>उलट देने की भूल आम है</td></tr>\n<tr><td>गोसइयाँ / गोसइन</td><td>पति (मालिक) / पत्नी (मालकिन)</td><td>\"गोसाईं\" (साधु) नहीं</td></tr></table>\n\n<h3>व्याकरण से जुड़े गहन तथ्य</h3>\n<ul>\n<li>छत्तीसगढ़ी में संबंध-सर्वनाम लिंग से नहीं बदलते — \"मोर दाई\" (मेरी माँ) और \"मोर ददा\" (मेरे पिता) दोनों में \"मोर\"। हिन्दी की तरह मेरा/मेरी/मेरे का भेद नहीं।</li>\n<li>बहुवचन प्रायः \"-मन\" जोड़कर: लइकामन (बच्चे), टूरामन (लड़के), हमन, तुमन, ओमन।</li>\n<li>वर्तमान काल का चिह्न \"-थ-\" है: जाथँव, जाथे, खाथे, करथन। भविष्य का चिह्न \"-ह-\" या \"-ब-\": जाही, जाहूँ, जाबो, जाबे।</li>\n<li>\"ह\" कर्ता के बाद आने वाला निपात है — \"राम ह गिस\" = राम गया। \"दूध के जरे <b>ह</b>\" में यही \"ह\" है।</li>\n<li>\"झन\" निषेधवाचक (मत) है, \"नइ\" सामान्य नकार (नहीं) — \"झन जा\" = मत जाओ, \"नइ जाँव\" = नहीं जाऊँगा।</li>\n<li>छत्तीसगढ़ी का प्रथम व्याकरण हीरालाल काव्योपाध्याय ने 1885 में लिखा; जॉर्ज ग्रियर्सन ने 1890 में उसका अंग्रेज़ी अनुवाद/संपादन प्रकाशित कराया और अपने \"भारतीय भाषा-सर्वेक्षण\" (लिंग्विस्टिक सर्वे ऑफ़ इंडिया) में छत्तीसगढ़ी को पूर्वी हिन्दी के अंतर्गत रखा।</li>\n<li>डॉ. नरेंद्र देव वर्मा का शोध-ग्रंथ \"छत्तीसगढ़ी भाषा का उद्विकास\" छत्तीसगढ़ी के भाषा-वैज्ञानिक अध्ययन का आधार-ग्रंथ माना जाता है; वे राजगीत \"अरपा पैरी के धार\" के रचयिता भी हैं।</li>\n<li>कोदूराम \"दलित\" जैसे छत्तीसगढ़ी कवियों की रचनाओं में हानों का सहज प्रयोग मिलता है; लोक-गीतों (ददरिया, सुआ) में भी हाना-शैली की पंक्तियाँ आती हैं।</li>\n</ul>\n\n<h3>परीक्षा-ट्रिक्स</h3>\n<ul>\n<li>प्रश्न में \"हाना\" लिखा हो तो उत्तर \"लोकोक्ति/कहावत\" वाले अर्थ में खोजें; \"जनऊला\" लिखा हो तो किसी वस्तु का नाम।</li>\n<li>अपरिचित शब्द हो तो उसे हिन्दी के निकट रूप से जोड़ें: अगोरना ↔ अगोरना (प्रतीक्षा), बिसाना ↔ बिसाहना (खरीदना), बुताना ↔ बुझाना, चिन्हना ↔ चीन्हना (पहचानना)।</li>\n<li>पर कुछ शब्द \"छलावा\" हैं (पताल, मंजूर, भंडार, काली) — इनके हिन्दी जैसे दिखने वाले अर्थ प्रायः गलत विकल्प के रूप में दिए जाते हैं।</li>\n<li>जनऊला में संख्या-संकेत: बत्तीस = दाँत; बाइस कान = रावण (20) + मंदोदरी (2); अठारा कोरी = 360 (चलनी के छेद); बारा डारा = 12 महीने।</li>\n</ul>\n",
  questions: [
    {"q":"जनऊला \"पेट चिरहा, पीठ कुबरा\" का उत्तर है—","o":["कौड़ी","कछुआ","घोंघा","सीप"],"a":0,"e":"कौड़ी का निचला भाग (पेट) चिरा हुआ और ऊपरी भाग (पीठ) कूबड़ जैसा उभरा होता है। चिरहा = चिरा हुआ, कुबरा = कुबड़ा।"},
    {"q":"जनऊला \"पहाड़ ले उतरे रेचकी घोड़ी, ओकर पीला अठारा कोरी\" का उत्तर है—","o":["सूपा","चलनी","टुकना","जाँता"],"a":1,"e":"अठारा कोरी = 18 × 20 = 360; चलनी के अनगिनत छेद ही उसके \"पीला\" (बच्चे) हैं। \"कोरी\" बीस की इकाई है।"},
    {"q":"जनऊला \"फाँदे के बेर एक ठन, छोरे के बेर दू ठन\" का उत्तर है—","o":["पनही","खटिया","दतवन (दातुन)","नाँगर"],"a":2,"e":"दातुन उपयोग के समय एक होती है, बाद में चीरकर जीभ साफ़ करने के लिए दो हो जाती है। बेर = समय।"},
    {"q":"जनऊला \"नानकुन डबरी, बूड़े भारी जहाज\" का उत्तर है—","o":["डोंगा","घइला","तरिया","दीया"],"a":3,"e":"दीये का तेल छोटी-सी डबरी (तालाब) है और उसमें डूबी बाती \"जहाज\"। डबरी = छोटा तालाब।"},
    {"q":"जनऊला \"पाँच कबूतर पाँचे रंग, महल म जाके एके रंग\" का उत्तर है—","o":["पान-सुपारी का बीड़ा","इंद्रधनुष","पाँच उँगलियाँ","रंगोली"],"a":0,"e":"पान, कत्था, चूना, सुपारी आदि अलग-अलग रंग के होते हैं, पर मुँह (महल) में जाकर सब एक (लाल) रंग हो जाते हैं।"},
    {"q":"जनऊला \"गाँव म आगी लगे, वो गाँव म कुआँ\" किस वस्तु के लिए है?","o":["चूल्हा","हुक्का","दीया","चिलम-तवा"],"a":1,"e":"हुक्के के ऊपर चिलम में आग और नीचे पानी भरा पात्र (कुआँ) होता है।"},
    {"q":"जनऊला \"लाल बइला भागत हे, करिया बइला कुदावत हे\" का उत्तर है—","o":["आगी अउ धुआँ","सुरुज अउ बादर","दिन अउ रात","लहू अउ पसीना"],"a":0,"e":"लाल लपटें (लाल बइला) आगे भागती हैं और काला धुआँ (करिया बइला) पीछे दौड़ता है।"},
    {"q":"जनऊला \"काटे ले कटाय नहीं, भोंगे ले भोंगाय नहीं\" का उत्तर है—","o":["लकड़ी","छाँव (छइहाँ)","कपड़ा","पथरा"],"a":1,"e":"छाया न कटती है, न छेदी जा सकती है। भोंगना = छेद करना; लकड़ी, कपड़ा, पत्थर सब कटते-छिदते हैं।"},
    {"q":"जनऊला \"मूठा म धरे, अउ खँचवा म भरे\" किसके लिए कहा जाता है?","o":["ढेंकी","बाहना","सूपा","जाँता"],"a":3,"e":"जाँता (हाथ-चक्की) की मूठ पकड़कर घुमाते हैं और उसके छेद (खँचवा) में दाना भरते हैं।"},
    {"q":"जनऊला \"एक फूल फूले, सौ फर फरे\" का उत्तर है—","o":["आमा","केरा (केला)","अनार","कुम्हड़ा"],"a":1,"e":"केले के एक फूल (घौद) से दर्जनों फल लगते हैं। फर = फल, फरना = फलना।"},
    {"q":"जनऊला \"फूल फूले रिंगी-चिंगी, फर फरे लमडोरा\" का उत्तर है—","o":["भाटा","रमकेलिया","मुनगा (सहजन)","करेला"],"a":2,"e":"सहजन के छोटे-छोटे सफ़ेद फूल और लंबी-लंबी फलियाँ (लमडोरा) होती हैं।"},
    {"q":"जनऊला \"सूखा डबरी म बगुला फड़फड़ाय\" का उत्तर है—","o":["मछरी","पूड़ी","पैरा","लाई (लावा)"],"a":3,"e":"सूखी कड़ाही (सूखा डबरी) में धान भूनने पर सफ़ेद लावा बगुले जैसा उछलता-फड़फड़ाता है।"},
    {"q":"जनऊला \"पान गुजगुज, फर लड़वा; एला नइ जानही तेकर बाप भकुवा\" का उत्तर है—","o":["गोंदली (प्याज़)","आलू","बोइर","मूँगफली"],"a":0,"e":"प्याज़ के पत्ते मुलायम (गुजगुज) और कंद लड्डू (लड़वा) जैसा गोल होता है। भकुवा = मूर्ख।"},
    {"q":"जनऊला \"फरे न फूले, नवे न डार; जब ले जीवय तब ले खाय\" का उत्तर है—","o":["पानी","नून (नमक)","गुर","अन्न"],"a":1,"e":"नमक न फलता, न फूलता, न उसकी डाल होती है; फिर भी मनुष्य जीवन भर खाता है।"},
    {"q":"जनऊला \"दिखब म लाल, छुअब म गुजगुज\" का उत्तर है—","o":["मिरचा","बोइर","पताल (टमाटर)","अनार"],"a":2,"e":"टमाटर देखने में लाल और छूने में नरम (गुजगुज) होता है। मिर्च लाल होती है पर नरम नहीं।"},
    {"q":"जनऊला \"छिछिल तलैया म, डूब मरय सितलैया\" का उत्तर है—","o":["मछरी","पूड़ी","दीया","कमल"],"a":1,"e":"कड़ाही के उथले (छिछिल) तेल में पूड़ी \"डूबकर\" तली जाती है।"},
    {"q":"जनऊला \"दूनो कोठा के गोबर ल, एके हाथ म हेरय\" का उत्तर है—","o":["कान","आँखी","नाक","मुँह"],"a":2,"e":"नाक के दोनों नथुने दो \"कोठा\" (पशुशाला) हैं। हेरना = निकालना।"},
    {"q":"जनऊला \"तरी पचरी, ऊपर परी, बीच म मोंगरी मछरी\" का उत्तर है—","o":["मछरी","दाँत","आँखी","जीभ"],"a":3,"e":"नीचे-ऊपर दाँतों के बीच मछली की तरह हिलती-डुलती जीभ। तरी = नीचे।"},
    {"q":"जनऊला \"करिया बन म रहिथँव, लाल पानी पीथँव\" का उत्तर है—","o":["जूँ","जोंक","मच्छर","मकरा"],"a":0,"e":"जूँ काले बालों (करिया बन = काला जंगल) में रहती है और खून (लाल पानी) पीती है।"},
    {"q":"जनऊला \"गाड़ा भर गहूँ म एक ठन गोटी\" में \"गोटी\" किसका प्रतीक है?","o":["सुरुज","धुरवा तारा","चंदा (चंद्रमा)","बादर"],"a":2,"e":"गाड़ी भर गेहूँ = असंख्य तारे; उनके बीच एक गोल गोटी = चंद्रमा। गाड़ा = बैलगाड़ी।"},
    {"q":"जनऊला \"नंद बबा के नौ सौ गाय, रात चरय दिन बेंड़े जाय\" का उत्तर है—","o":["बादर","जुगनू","चमगादड़","चंदैनी (तारे)"],"a":3,"e":"तारे रात में आकाश में \"चरते\" दिखते हैं और दिन में ओझल (बंद) हो जाते हैं। चंदैनी = तारे।"},
    {"q":"जनऊला \"काँधे आय, काँधे जाय; नेंग-नेंग म मारे जाय\" का उत्तर है—","o":["बाजा (ढोल)","कावड़","पागा","टँगिया"],"a":0,"e":"ढोल कंधे पर लटकाकर लाया-ले जाया जाता है और हर रस्म (नेंग) में \"मारा\" (बजाया) जाता है।"},
    {"q":"जनऊला \"कारी गाय, करंगा पिला; मर गे गाय, छटक गे पिला\" का उत्तर है—","o":["धनुष-बाण","बंदूक अउ गोली","गुलेल","तोप"],"a":1,"e":"काली बंदूक (गाय) \"मरती\" (चलती) है तो गोली (पिला = बच्चा) छिटककर निकल जाती है।"},
    {"q":"जनऊला \"ताकत हे, तुकावत हे, दूनो गोड़ अलगावत हे\" का उत्तर है—","o":["कोकड़ा (बगुला)","बिलई","मंजूर","मेचका"],"a":0,"e":"बगुला पानी में टाँगें फैलाए मछली की घात लगाकर (ताकत) खड़ा रहता है। कोकड़ा = बगुला।"},
    {"q":"जनऊला \"खटिया गाँथे तान-बितान, दू सुतइया बाइस कान\" का उत्तर है—","o":["राम अउ सीता","कुंभकरन अउ ओकर पत्नी","शिव अउ पार्वती","रावन अउ मंदोदरी"],"a":3,"e":"रावण के 10 सिर = 20 कान, मंदोदरी के 2 — कुल 22 (बाइस) कान।"},
    {"q":"जनऊला \"तीन मूड़ शंकर नो हे, दूध देथे ते गाय नो हे, रुख म रहिथे ते पंछी नो हे\" का उत्तर है—","o":["बेल","नरियर (नारियल)","महुआ","मधुमक्खी"],"a":1,"e":"नारियल पर तीन \"आँखें\" (शंकर के त्रिनेत्र जैसी), भीतर दूध (नारियल-पानी) और पेड़ पर रहता है। \"नो हे\" = नहीं है।"},
    {"q":"जनऊला \"खुसुर-खुसुर खोर्री, छै आँखी तीन घोरी\" में छह आँखें किनकी हैं?","o":["तीन मनखे","तीन बइला","दो बइला अउ एक हलवाहा","एक गाय अउ दो बछड़े"],"a":2,"e":"हल (नाँगर) जोतते समय दो बैल और एक हलवाहा = 6 आँखें। उत्तर: नाँगर, बइला अउ मनखे।"},
    {"q":"जनऊला \"बन ले लानेंव बेंदरी, घर म छेदेंव कान; दूध-भात के भोजन करके, फेंक देंव मैदान\" का उत्तर है—","o":["टुकना (टोकरी)","पतरी (पत्तल)","बाँस की सूपा","कथरी"],"a":1,"e":"जंगल (बन) से पत्ते लाकर सींकों से छेदकर पत्तल बनाते हैं; भोजन के बाद उसे फेंक देते हैं।"},
    {"q":"जनऊला \"पान के ओधा, माँस के घोंघा\" का उत्तर है—","o":["केरा","कुम्हड़ा","भाटा (बैंगन)","मुनगा"],"a":2,"e":"पत्तों की ओट (ओधा) में लटका गूदेदार (माँस जैसा) फल = बैंगन। भाटा = बैंगन।"},
    {"q":"जनऊला \"बोवत देखेंव बाटरा, जामत म कुसियार; ढाई महीना के छोकरा, दाढ़ी-मेंछा म हुसियार\" का उत्तर है—","o":["धान","कुसियार (गन्ना)","राहेर","जोंधरी (भुट्टा)"],"a":3,"e":"मक्का का दाना बोते समय गोल, उगने पर गन्ने जैसा पौधा, और ढाई महीने में भुट्टे के \"बाल\" (दाढ़ी-मूँछ) निकल आते हैं।"},
    {"q":"जनऊला \"पर्रा भर लाई, गने न सिराई\" का उत्तर है—","o":["मुर्रा","धान","चाँटी","चंदैनी (तारे)"],"a":3,"e":"आकाश (पर्रा = बड़ी टोकरी) में बिखरा लावा = तारे, जो गिनने से खत्म नहीं होते (सिराई = समाप्त होना)।"},
    {"q":"जनऊला \"देखब म दूनो रोटी एक बरोबर\" किन दो के लिए है?","o":["सुरुज अउ चंदा","दूनो आँखी","तावा अउ थारी","दिन अउ रात"],"a":0,"e":"आकाश में सूर्य और चंद्रमा देखने में दो बराबर (बरोबर) गोल रोटियों जैसे लगते हैं।"},
    {"q":"जनऊला \"एक पेड़ के बारा डारा, तीस-तीस के झोंथा\" का उत्तर है—","o":["मुनगा के पेड़","बछर, महीना अउ दिन","घड़ी, घंटा अउ मिनट","राजा, मंत्री अउ प्रजा"],"a":1,"e":"एक वर्ष (पेड़) के 12 महीने (डारा) और हर महीने के 30 दिन (झोंथा = गुच्छा)।"},
    {"q":"जनऊला \"उड़त देखे काँग-कुड़ी, बइठत डेना पसार\" का उत्तर है—","o":["पतंग","चमगादड़","छाता","मछरी मारे के जाल"],"a":3,"e":"फेंका गया जाल उड़ता दिखता है और पानी पर गिरते ही पंख (डेना) की तरह फैल जाता है।"},
    {"q":"जनऊला \"एक गोड़ के घोड़ा, दुइ झन भये सवार\" का उत्तर है—","o":["रहचुली (झूला)","साइकिल","बइलागाड़ी","डोंगा"],"a":0,"e":"रहचुली एक खूँटे (एक पैर) पर घूमने वाला झूला है, जिस पर दोनों ओर एक-एक व्यक्ति बैठता है। दुइ झन = दो लोग।"},
    {"q":"जनऊला \"बिना पाँव के अहिरा भइया, बिना सींग के गाय... खारन-खार कुदाय\" में \"बिना सींग के गाय\" कौन है?","o":["छेरी","खरहा","मेचका (मेंढक)","मछरी"],"a":2,"e":"बिना पाँव का चरवाहा (अहिरा) = साँप, और जिसे वह खेतों (खार) में दौड़ाता है वह बिना सींग की गाय = मेंढक।"},
    {"q":"जनऊला \"बिहनिया चार गोड़, मंझनिया दू गोड़, संझा तीन गोड़\" का उत्तर है—","o":["मनखे (मनुष्य)","खटिया","बेंदरा","कुकरा"],"a":0,"e":"जीवन की सुबह (बचपन) में घुटनों के बल चार, जवानी में दो और बुढ़ापे (संझा) में लाठी सहित तीन पैर।"},
    {"q":"जनऊला \"जतका बाँटबे, ओतके बाढ़य\" का उत्तर है—","o":["धन","विद्या (ज्ञान)","अनाज","करजा"],"a":1,"e":"विद्या बाँटने से घटती नहीं, बढ़ती है। बाँटबे = बाँटोगे, बाढ़य = बढ़े।"},
    {"q":"जनऊला \"करिया हे फेर कौंवा नोहय, लंबा हे फेर साँप नोहय\" का उत्तर है—","o":["रस्सी","नार (बेल)","बेनी (चोटी)","धुआँ"],"a":2,"e":"चोटी काली और लंबी होती है, पर न कौआ है न साँप। नोहय = नहीं है।"},
    {"q":"हाना \"जेकर बेंदरा, तेकरे ले नाचय\" का अर्थ है—","o":["बंदर सबके सामने नाचता है","मनोरंजन से पैसा मिलता है","जानवर पालना कठिन है","व्यक्ति अपने स्वामी या पालक का ही कहा मानता है"],"a":3,"e":"मदारी का बंदर केवल अपने मालिक के इशारे पर नाचता है। जेकर = जिसका, तेकरे = उसी का।"},
    {"q":"हाना \"ठलहा बनिया का करय, ए कोठी के धान ओ कोठी करय\" किसके लिए कहा जाता है?","o":["बेकार बैठकर व्यर्थ के काम करने वाले के लिए","मेहनती व्यापारी के लिए","अनाज की चोरी करने वाले के लिए","कंजूस किसान के लिए"],"a":0,"e":"ठलहा = खाली/बेकार; खाली बैठा व्यापारी एक कोठी का धान दूसरी कोठी में डालता रहता है — निरर्थक व्यस्तता।"},
    {"q":"हाना \"बड़े-बड़े बोहा गें, गदहा पूछय कतका पानी\" का भाव है—","o":["नदी में बाढ़ आना","जहाँ समर्थ लोग असफल हो गए, वहाँ असमर्थ का दावा करना","गधे की मूर्खता पर हँसना","पानी की गहराई नापना"],"a":1,"e":"बड़े-बड़े बह गए (बोहा गें), गधा पूछता है कितना पानी (कतका पानी) है — सामर्थ्य से बड़ी बात।"},
    {"q":"हाना \"आगी लगे म कुआँ खोदना\" का अर्थ है—","o":["आग बुझाने का सही उपाय","कुआँ खोदना पुण्य का काम","संकट आने पर ही उपाय करना (पहले से तैयारी न करना)","जल-संरक्षण करना"],"a":2,"e":"आग लगने पर कुआँ खोदना देर से की गई तैयारी है। आगी = आग।"},
    {"q":"हाना \"खेती अपन सेती, नइ त नदिया के रेती\" का अर्थ है—","o":["नदी किनारे की खेती सबसे अच्छी","खेती छोड़ देनी चाहिए","खेती में रेत मिलानी चाहिए","खेती स्वयं देखभाल करने से ही सफल होती है, अन्यथा व्यर्थ"],"a":3,"e":"खेती अपने हाथ (सेती = स्वयं की देखरेख) से सफल होती है, नहीं तो नदी की रेत जैसी निष्फल।"},
    {"q":"हाना \"नवा-नवा नौ दिन, जुन्ना-जुन्ना सौ दिन\" में \"जुन्ना\" का अर्थ है—","o":["पुराना","नया","जूना (रस्सी)","जवान"],"a":0,"e":"जुन्ना = पुराना, नवा = नया। अर्थ: नई चीज़ का आकर्षण थोड़े दिन, पुरानी विश्वसनीय चीज़ लंबे समय काम आती है।"},
    {"q":"हाना \"नवा बइला के नवा सींग, चल रे बइला टिंगे-टिंग\" किस स्थिति में कहा जाता है?","o":["बैल बेचते समय","नए-नए व्यक्ति के अति उत्साह पर","पशु के बीमार होने पर","खेत जोतने के बाद"],"a":1,"e":"नया बैल, नए सींग — नया सदस्य शुरू में बहुत उछल-कूद (टिंगे-टिंग) करता है।"},
    {"q":"हाना \"जइसे नागनाथ, तइसे साँपनाथ\" का अर्थ है—","o":["दोनों विकल्प अच्छे होना","साँपों की पूजा करना","दोनों विकल्प एक समान बुरे होना","एक बुरा, एक अच्छा"],"a":2,"e":"नागनाथ हो या साँपनाथ, दोनों विषैले — जब दोनों विकल्प समान रूप से बुरे हों।"},
    {"q":"हाना \"एक हाथ ले ताली नइ बाजय\" का भाव है—","o":["ताली बजाना शुभ है","अकेले काम करना अच्छा","हाथ से काम करो","झगड़े में दोनों पक्ष दोषी होते हैं"],"a":3,"e":"ताली दो हाथों से बजती है; झगड़ा भी एक पक्ष से नहीं होता। ले = से, नइ = नहीं।"},
    {"q":"हाना \"घी के लड्डू टेड़गा घलो भला\" का अर्थ है—","o":["उत्तम वस्तु का रूप बिगड़ा हो तब भी वह अच्छी है","टेढ़ी चीज़ बुरी होती है","मिठाई सेहत के लिए हानिकारक है","घी महँगा होता है"],"a":0,"e":"घी का लड्डू टेढ़ा (टेड़गा) भी हो तो अच्छा (भला) ही है। घलो = भी।"},
    {"q":"हाना \"भूख न जानय जूठा भात, नींद न जानय टूटी खाट\" का भाव है—","o":["जूठा नहीं खाना चाहिए","ज़रूरत के समय सुविधा-असुविधा नहीं देखी जाती","टूटी खाट पर नहीं सोना चाहिए","भूख लगने पर नींद नहीं आती"],"a":1,"e":"भूखे को जूठा भात भी चलता है और नींद आए तो टूटी खाट भी — विवशता में जो मिले वही स्वीकार।"},
    {"q":"हाना \"मार के आगू भूत भागय\" का अर्थ है—","o":["भूत-प्रेत होते हैं","मार-पीट बुरी बात है","दंड के भय से दुष्ट भी सीधा हो जाता है","डरपोक भाग जाता है"],"a":2,"e":"मार (दंड) के आगे भूत भी भागता है। आगू = आगे।"},
    {"q":"हाना \"पानी म रहि के मगर ले बैर\" का अर्थ है—","o":["पानी में मगर रहते हैं","मगर से दोस्ती करनी चाहिए","नदी में तैरना खतरनाक है","जिसके आश्रय में रहें उसी से शत्रुता करना"],"a":3,"e":"पानी में रहकर मगरमच्छ से दुश्मनी मूर्खता है — आश्रयदाता से बैर।"},
    {"q":"हाना \"अंधरा पीसय, कुकुर खाय\" का अर्थ है—","o":["असावधान व्यक्ति की कमाई दूसरे उड़ा ले जाते हैं","अंधे को सहायता करनी चाहिए","कुत्ता वफ़ादार होता है","मेहनत का फल मीठा"],"a":0,"e":"अंधा पीसता है और कुत्ता आटा खा जाता है — लापरवाह की मेहनत का लाभ दूसरे को।"},
    {"q":"हाना \"बोकरा के जीव जाय, खवइया ल अलोना\" में \"अलोना\" का अर्थ है—","o":["अधिक नमक वाला","बिना नमक का (फीका)","कड़वा","जला हुआ"],"a":1,"e":"अलोना = बिना नमक का। बकरे की जान गई, खाने वाले को फीका लगा — बड़े त्याग की कद्र न होना।"},
    {"q":"हाना \"उल्टा चोर कोतवाल ल डाँटय\" का अर्थ है—","o":["कोतवाल ईमानदार है","चोर पकड़ा गया","दोषी व्यक्ति उलटे निर्दोष को दोष दे","कोतवाल चोर से डरता है"],"a":2,"e":"अपराधी स्वयं अकड़कर दूसरों को दोषी ठहराए। ल = को।"},
    {"q":"हाना \"हाथ कंगन ल आरसी का\" में \"आरसी\" का अर्थ है—","o":["आरती","आलसी","आरी","दर्पण"],"a":3,"e":"आरसी = दर्पण। हाथ के कंगन को देखने के लिए दर्पण की ज़रूरत नहीं — प्रत्यक्ष को प्रमाण की आवश्यकता नहीं।"},
    {"q":"हाना \"अब पछताय होत का, जब चिरई चुग गे खेत\" का अर्थ है—","o":["अवसर निकल जाने के बाद पछताना व्यर्थ है","चिड़ियों से फसल बचानी चाहिए","पछताने से पाप धुलते हैं","खेत में दाना डालना चाहिए"],"a":0,"e":"चिड़िया (चिरई) खेत चुग गई, अब पछताने से क्या होगा। समय पर काम करने की सीख।"},
    {"q":"हाना \"रस्सी जर गे, फेर अँइठन नइ गिस\" का अर्थ है—","o":["रस्सी मज़बूत होती है","सब कुछ नष्ट होने पर भी घमंड नहीं गया","आग से सावधान रहना चाहिए","पुरानी रस्सी बदल देनी चाहिए"],"a":1,"e":"रस्सी जल गई (जर गे), फिर भी ऐंठन नहीं गई — बर्बाद होकर भी अकड़ना। फेर = फिर भी।"},
    {"q":"हाना \"सौ सुनार के, एक लोहार के\" का भाव है—","o":["सुनार बेईमान होते हैं","लोहार का काम कठिन है","बलवान का एक प्रहार कमज़ोर के सौ प्रहारों के बराबर","सौ में एक ही सच्चा"],"a":2,"e":"सुनार की सौ हल्की चोटें, लोहार की एक भारी चोट के बराबर — निर्णायक एक प्रहार।"},
    {"q":"हाना \"बिच्छी के मंतर नइ जानय, साँप के बिला म हाथ डारय\" का अर्थ है—","o":["मंत्र-तंत्र में विश्वास करना","साँप पकड़ना एक कला है","बिच्छू साँप से अधिक ज़हरीला","छोटी योग्यता होते हुए बड़ा जोखिम उठाना"],"a":3,"e":"बिच्छू का मंत्र भी नहीं आता और साँप के बिल में हाथ डालता है। बिच्छी = बिच्छू, बिला = बिल।"},
    {"q":"हाना \"कौंवा चलिस हंस के चाल, अपनो चाल भुलागे\" का अर्थ है—","o":["दूसरों की नकल में अपना गुण भी गँवा देना","हंस की चाल सुंदर होती है","कौआ चतुर पक्षी है","चलना सीखना ज़रूरी"],"a":0,"e":"कौआ हंस की चाल चलने गया और अपनी चाल भी भूल गया (भुलागे) — अंधानुकरण का दुष्परिणाम।"},
    {"q":"हाना \"होनहार बिरवान के होत चीकन पात\" में \"बिरवा\" का अर्थ है—","o":["वीर","पौधा","विरह","बिरादरी"],"a":1,"e":"बिरवा = पौधा, चीकन = चिकने। होनहार पौधे के पत्ते शुरू से चिकने होते हैं — प्रतिभा बचपन में ही दिख जाती है।"},
    {"q":"हाना \"जिहाँ गुड़, उहाँ चाँटी\" का अर्थ है—","o":["गुड़ ढककर रखना चाहिए","चींटियाँ मेहनती होती हैं","जहाँ लाभ हो, वहाँ लोग जुट जाते हैं","मीठा खाना हानिकारक"],"a":2,"e":"जहाँ (जिहाँ) गुड़ होगा, वहाँ (उहाँ) चींटियाँ (चाँटी) पहुँचेंगी — स्वार्थी भीड़।"},
    {"q":"हाना \"घर के भेदी लंका ढाहय\" किस भाव को व्यक्त करता है?","o":["लंका सोने की थी","शत्रु बाहर से आता है","घर बनाना कठिन है","घर का भेद जानने वाला ही सबसे बड़ा नुकसान करता है"],"a":3,"e":"विभीषण के प्रसंग से — घर का भेदी लंका ढहा (ढाहय) देता है। आपसी फूट से हानि।"},
    {"q":"हाना \"खिसियानी बिलई खंभा नोचय\" का अर्थ है—","o":["लज्जित होकर क्रोध दूसरे पर उतारना","बिल्ली खंभे पर चढ़ती है","नाखून काटने चाहिए","पालतू पशु घर बिगाड़ते हैं"],"a":0,"e":"खिसियाई बिल्ली (बिलई) खंभा नोचती है — हार की झेंप में किसी और पर बिगड़ना।"},
    {"q":"हाना \"अपन दही ल कोनो खट्टा नइ कहय\" का अर्थ है—","o":["दही खट्टा नहीं होना चाहिए","अपनी वस्तु की सब प्रशंसा ही करते हैं","दूसरों की वस्तु अच्छी होती है","कोई सच नहीं बोलता"],"a":1,"e":"अपने दही को कोई (कोनो) खट्टा नहीं कहता — अपनी चीज़ के दोष कोई नहीं मानता।"},
    {"q":"हाना \"बाप न मारिस मेचका, बेटा तीरंदाज\" का अर्थ है—","o":["पिता-पुत्र दोनों वीर","मेंढक मारना पाप है","खानदान में कोई योग्यता न होते हुए भी बढ़-चढ़कर बातें करना","बेटा पिता से आगे निकलता है"],"a":2,"e":"बाप ने कभी मेंढक (मेचका) भी नहीं मारा और बेटा तीरंदाज बनता है — झूठी शान।"},
    {"q":"हाना \"कोइला के दलाली म मुँह करिया\" का अर्थ है—","o":["कोयले का व्यापार लाभदायक","दलाल बेईमान होते हैं","चेहरा साफ़ रखना चाहिए","बुरे काम में हाथ डालने से बदनामी अवश्य होती है"],"a":3,"e":"कोयले की दलाली में मुँह काला (करिया) होना तय है — गलत संगत/धंधे से बचें।"},
    {"q":"हाना \"दाँत हे त चना नइ, चना हे त दाँत नइ\" का अर्थ है—","o":["साधन और सामर्थ्य एक साथ न होना","चना दाँतों के लिए हानिकारक","बुढ़ापे में दाँत गिरते हैं","गरीबी में चना खाया जाता है"],"a":0,"e":"जवानी में दाँत हैं तो चना नहीं, बुढ़ापे में चना है तो दाँत नहीं — अवसर और क्षमता का बेमेल। हे = है, त = तो।"},
    {"q":"हाना \"एक तो करेला, ऊपर ले लीम चढ़े\" में \"लीम\" का अर्थ है—","o":["नींबू","नीम","लौकी","लहसुन"],"a":1,"e":"लीम = नीम। एक तो करेला कड़वा, ऊपर से नीम पर चढ़ा — एक दोष के साथ दूसरा दोष जुड़ना।"},
    {"q":"हाना \"घर म नइ हे दाना, दाई चलिस भुंजाय\" का भाव है—","o":["माँ मेहनती है","अनाज भूनकर खाना चाहिए","सामर्थ्य न होने पर भी बड़ा दिखावा करना","घर में अनाज की कमी नहीं"],"a":2,"e":"घर में दाना नहीं और माँ (दाई) भुनाने चली — हैसियत से बढ़कर दिखावा। (हिन्दी: घर में नहीं दाने, अम्मा चली भुनाने।)"},
    {"q":"हाना \"रात भर रमायन सुनिस, बिहनिया पूछय सीता काकर ददा\" किसके लिए कहा जाता है?","o":["रामायण के ज्ञाता के लिए","रात भर जागने वाले के लिए","जिज्ञासु बालक के लिए","पूरी बात सुनकर भी कुछ न समझने वाले के लिए"],"a":3,"e":"रात भर रामायण सुनी, सुबह (बिहनिया) पूछता है सीता किसका (काकर) पिता (ददा) है — समझ का अभाव।"},
    {"q":"हाना \"हाथी चलय बजार, कुकुर भूँकय हजार\" का अर्थ है—","o":["महान व्यक्ति निंदकों की परवाह नहीं करते","बाज़ार में भीड़ होती है","कुत्ते हाथी से डरते हैं","हाथी पालना महँगा है"],"a":0,"e":"हाथी बाज़ार में चलता रहता है, कुत्ते हज़ार भौंकें (भूँकय) — आलोचना के बीच अडिग रहना।"},
    {"q":"हाना \"धोबी के कुकुर, न घर के न घाट के\" का अर्थ है—","o":["धोबी का काम कठिन है","दो पक्षों के बीच व्यक्ति कहीं का नहीं रहता","कुत्ता घर की रखवाली करता है","नदी किनारे रहना अच्छा"],"a":1,"e":"दुविधा में दोनों ओर से छूट जाना। घाट = नदी का किनारा जहाँ धोबी कपड़े धोता है।"},
    {"q":"हाना \"आगू नाथ न पाछू पगहा\" में \"पगहा\" का अर्थ है—","o":["पगड़ी","पैर","पशु बाँधने की रस्सी","पगडंडी"],"a":2,"e":"नाथ = बैल की नाक में डाली रस्सी, पगहा = पशु बाँधने की रस्सी। अर्थ — कोई बंधन/ज़िम्मेदारी न होना।"},
    {"q":"हाना \"सबो धान बाईस पसेरी\" का अर्थ है—","o":["धान महँगा होना","अच्छी फसल होना","अनाज बराबर बाँटना","अच्छे-बुरे सबको एक समान समझना"],"a":3,"e":"हर किस्म का धान एक ही भाव (बाईस पसेरी) — विवेकहीन मूल्यांकन। पसेरी = पाँच सेर का माप।"},
    {"q":"हाना \"नौ सौ मुसुवा खा के बिलई चलिस हज बर\" का अर्थ है—","o":["जीवन भर पाप करके अंत में धर्मात्मा बनने का ढोंग","बिल्ली चूहे खाती है","तीर्थ यात्रा पुण्य का काम","भूखे को भोजन देना"],"a":0,"e":"नौ सौ चूहे (मुसुवा) खाकर बिल्ली हज के लिए (बर) चली — पापी का धार्मिक दिखावा। बर = के लिए।"},
    {"q":"हाना \"खोदिस पहाड़, निकलिस मुसुवा\" का भाव है—","o":["पहाड़ों में चूहे रहते हैं","बहुत परिश्रम पर बहुत थोड़ा फल","खुदाई से खज़ाना मिलता है","मेहनत कभी बेकार नहीं जाती"],"a":1,"e":"पहाड़ खोदा, निकला चूहा — बड़ी मेहनत का तुच्छ परिणाम। खोदिस = खोदा।"},
    {"q":"हाना \"जेन गरजथे, तेन बरसय नइ\" का अर्थ है—","o":["बादल गरजकर ही बरसते हैं","वर्षा का अनुमान लगाना","बहुत डींग मारने वाले काम कम करते हैं","क्रोधी व्यक्ति दयालु होता है"],"a":2,"e":"जो (जेन) गरजता है, वह (तेन) बरसता नहीं — धमकी देने वाले से डरने की आवश्यकता नहीं।"},
    {"q":"हाना \"बेंदरा के हाथ म उस्तुरा\" का अर्थ है—","o":["बंदर नकलची होता है","हजामत बनाना","बंदर से सावधान रहना","अयोग्य के हाथ में अधिकार या खतरनाक वस्तु"],"a":3,"e":"बंदर के हाथ में उस्तरा — नासमझ को बड़ा अधिकार मिलना, जिससे हानि निश्चित।"},
    {"q":"हाना \"मान न मान, मैं तोर पहुना\" में \"पहुना\" का अर्थ है—","o":["मेहमान","पड़ोसी","पहलवान","पुजारी"],"a":0,"e":"पहुना = मेहमान (विशेषकर दामाद)। अर्थ — ज़बरदस्ती किसी से संबंध जोड़ना, बिन बुलाए गले पड़ना।"},
    {"q":"हाना \"कुकरा नइ बासही त का बिहान नइ होही\" का अर्थ है—","o":["मुर्गा सुबह बाँग देता है","किसी एक के बिना संसार का काम नहीं रुकता","सुबह जल्दी उठना चाहिए","मुर्गा पालना लाभदायक"],"a":1,"e":"मुर्गा (कुकरा) बाँग न दे तो क्या सवेरा (बिहान) नहीं होगा? — अपने को अपरिहार्य समझने वाले पर व्यंग्य।"},
    {"q":"हाना \"जतके ओढ़ना, ततके गोड़ लमाय\" का अर्थ है—","o":["ठंड में चादर ओढ़नी चाहिए","पैर फैलाकर सोना अच्छा","आय के अनुसार ही खर्च करना चाहिए","बड़ी चादर ख़रीदनी चाहिए"],"a":2,"e":"जितनी (जतके) चादर (ओढ़ना), उतने (ततके) पैर (गोड़) फैलाओ (लमाय) — फ़िज़ूलखर्ची से बचें।"},
    {"q":"हाना \"आधा छोड़ पूरा ल धावय, आधा मिलय न पूरा पावय\" किस दोष की ओर संकेत करता है?","o":["आलस्य","क्रोध","अहंकार","लोभ (लालच)"],"a":3,"e":"आधे को छोड़ पूरे के पीछे दौड़ने (धावय) वाला दोनों गँवाता है — अधिक लोभ का फल।"},
    {"q":"हाना \"दीया तरी अँधियार\" का अर्थ है—","o":["निकट की बुराई दिखाई नहीं देती","दीया जलाना शुभ है","अँधेरे से डरना नहीं चाहिए","रोशनी हर जगह पहुँचती है"],"a":0,"e":"दीये के नीचे (तरी) अँधेरा — ज्ञानी/अधिकारी के पास ही गड़बड़ी। (हिन्दी: चिराग तले अँधेरा।)"},
    {"q":"हाना \"बिलई के भाग ले सींका टूटिस\" का अर्थ है—","o":["बिल्ली बड़ी चालाक होती है","संयोग से अचानक लाभ हो जाना","छींका ऊँचा टाँगना चाहिए","परिश्रम से भाग्य बनता है"],"a":1,"e":"बिल्ली (बिलई) के भाग्य से छींका (सींका) टूट गया — बिना प्रयास भाग्य से लाभ।"},
    {"q":"हाना \"पाँचो अँगरी बरोबर नइ होवय\" का अर्थ है—","o":["उँगलियाँ अलग-अलग काम करती हैं","हाथ की सफ़ाई ज़रूरी","सब लोग एक समान नहीं होते","पाँच लोग मिलकर काम करें"],"a":2,"e":"पाँचों उँगलियाँ (अँगरी) बराबर (बरोबर) नहीं होतीं — सबको एक जैसा न समझें।"},
    {"q":"हाना \"काठ के हँड़िया एके बार चढ़थे\" का अर्थ है—","o":["लकड़ी के बर्तन में खाना नहीं पकता","हांडी चूल्हे पर चढ़ानी चाहिए","एक बार में काम पूरा करो","छल-कपट एक ही बार सफल होता है"],"a":3,"e":"लकड़ी (काठ) की हांडी (हँड़िया) एक ही बार चूल्हे पर चढ़ती है, फिर जल जाती है — धोखा बार-बार नहीं चलता।"},
    {"q":"हाना \"चमड़ी जाय फेर दमड़ी झन जाय\" किसके लिए कहा जाता है?","o":["अत्यधिक कंजूस व्यक्ति के लिए","घायल व्यक्ति के लिए","दानी व्यक्ति के लिए","चमड़े के व्यापारी के लिए"],"a":0,"e":"चमड़ी चली जाए पर दमड़ी (सबसे छोटा सिक्का) न जाए — घोर कंजूसी। झन = मत।"},
    {"q":"हाना \"गंगा गे त गंगादास, जमुना गे त जमुनादास\" किसके लिए कहा जाता है?","o":["तीर्थयात्री के लिए","अवसर देखकर पक्ष बदलने वाले के लिए","नदी पार करने वाले के लिए","संन्यासी के लिए"],"a":1,"e":"गंगा गया तो गंगादास, यमुना गया तो यमुनादास — अवसरवादी व्यक्ति। गे = गया।"},
    {"q":"हाना \"बाहना म मुड़ डारे त मूसर ले का डर्राना\" में \"बाहना\" का अर्थ है—","o":["बहाना","वाहन","ओखली","बहन"],"a":2,"e":"बाहना = ओखली, मूसर = मूसल। ओखली में सिर डाला तो मूसल से क्या डरना — कठिन काम उठाया तो कष्टों से न डरें।"},
    {"q":"हाना \"साँप घलो मर जाय, लाठी घलो झन टूटय\" का अर्थ है—","o":["साँप को मारना पाप है","लाठी मज़बूत होनी चाहिए","साँप से दूर रहना चाहिए","काम भी बन जाए और कोई हानि भी न हो"],"a":3,"e":"साँप भी (घलो) मर जाए और लाठी भी न टूटे — चतुराई भरा समाधान।"},
    {"q":"हाना \"आमा खाय ले मतलब, रुख गिने ले का\" में \"रुख\" का अर्थ है—","o":["पेड़","रुख़ (दिशा)","रुपया","रूखा"],"a":0,"e":"रुख = पेड़। आम खाने से मतलब रखो, पेड़ गिनने से क्या — अपने काम से काम।"},
    {"q":"हाना \"कौंवा के कोसे ले ढोर नइ मरय\" का अर्थ है—","o":["कौआ अशुभ पक्षी है","दुष्ट के बुरा चाहने से सज्जन का अहित नहीं होता","पशुओं की देखभाल करनी चाहिए","कोसना बुरी आदत"],"a":1,"e":"कौए के कोसने से पशु (ढोर) नहीं मरते — निंदक की बददुआ से कुछ नहीं बिगड़ता।"},
    {"q":"हाना \"चलनी म दूध दुहय, करम ल दोस देवय\" का अर्थ है—","o":["दूध छानकर पीना चाहिए","भाग्य सबसे बलवान है","अपनी मूर्खता से हानि करके भाग्य को दोष देना","गाय दुहना कठिन है"],"a":2,"e":"छलनी में दूध दुहे और फिर भाग्य (करम) को दोष दे — अपनी गलती न मानना।"},
    {"q":"हाना \"अकेल्ला चना भाड़ नइ फोरय\" का भाव है—","o":["चना भूनकर खाना चाहिए","भाड़ में आग तेज़ होनी चाहिए","अकेले रहना सुखद है","अकेला व्यक्ति बड़ा काम नहीं कर सकता"],"a":3,"e":"अकेला चना भाड़ (भूनने की भट्टी) नहीं फोड़ सकता — संगठन का महत्त्व।"},
    {"q":"हाना \"बूँद-बूँद ले घइला भरथे\" में \"घइला\" का अर्थ है—","o":["घड़ा","घर","घायल","घाट"],"a":0,"e":"घइला = घड़ा। बूँद-बूँद से घड़ा भरता है — थोड़ी-थोड़ी बचत से बड़ा संचय।"},
    {"q":"हाना \"जइसन संगत, तइसन रंगत\" का अर्थ है—","o":["संगीत से मन रंगता है","जैसी संगति, वैसा प्रभाव","रंग-बिरंगे कपड़े पहनने चाहिए","संगत में गाना"],"a":1,"e":"जैसी (जइसन) संगति, वैसा (तइसन) रंग — बुरी संगत से बचना चाहिए।"},
    {"q":"हाना \"घर के मुर्गी दार बरोबर\" में \"दार\" का अर्थ है—","o":["दरवाज़ा","लकड़ी","दाल","शराब"],"a":2,"e":"दार = दाल, बरोबर = बराबर। घर की मुर्गी दाल बराबर — घर की चीज़ का उचित मूल्य नहीं समझा जाता।"},
    {"q":"छत्तीसगढ़ी मुहावरा \"आँखी फेरना\" का अर्थ है—","o":["आँखें घुमाना","नींद आना","ध्यान से देखना","उपेक्षा करना / प्रेम घटा लेना"],"a":3,"e":"आँखी फेरना = पहले जैसा स्नेह न रखना, मुँह मोड़ लेना। (हिन्दी: आँखें फेरना।)"},
    {"q":"मुहावरा \"आँखी बिछाना\" का अर्थ है—","o":["प्रेमपूर्वक स्वागत करना","सो जाना","आँखें बंद करना","रोना"],"a":0,"e":"किसी के आगमन पर अत्यंत स्नेह से प्रतीक्षा व स्वागत करना।"},
    {"q":"मुहावरा \"आँखी चुराना\" का अर्थ है—","o":["चोरी करना","लज्जा या भय से सामने आने से बचना","आँख का इलाज कराना","जासूसी करना"],"a":1,"e":"गलती करने वाला व्यक्ति सामने आने से कतराता है — आँखी चुराना।"},
    {"q":"मुहावरा \"आँखी के काँटा होना\" का अर्थ है—","o":["आँख में चोट लगना","बहुत प्रिय होना","अत्यंत अप्रिय लगना","तेज़ नज़र होना"],"a":2,"e":"जो व्यक्ति खटकता रहे, वह आँख का काँटा है। उलटा भाव: आँखी के पुतरी होना = अत्यंत प्रिय।"},
    {"q":"मुहावरा \"आँखी म रात काटना\" का अर्थ है—","o":["रात में काम करना","सपने देखना","आँखों का रोग होना","चिंता में रात भर जागते रहना"],"a":3,"e":"चिंता या दुःख के कारण रात भर नींद न आना।"},
    {"q":"मुहावरा \"कान खड़ा होना\" का अर्थ है—","o":["सतर्क हो जाना","बहरा हो जाना","नाराज़ होना","शर्मिंदा होना"],"a":0,"e":"किसी आहट या संदेह पर सावधान हो जाना।"},
    {"q":"मुहावरा \"कान म तेल डार के बइठना\" का अर्थ है—","o":["कान का उपचार करना","बात को अनसुना करना","ध्यान से सुनना","आराम करना"],"a":1,"e":"बार-बार कहने पर भी ध्यान न देना। डार के = डालकर।"},
    {"q":"मुहावरा \"कान के कच्चा होना\" का अर्थ है—","o":["कम सुनना","कान छिदवाना","सुनी-सुनाई बात पर तुरंत विश्वास कर लेना","संगीत न समझना"],"a":2,"e":"बिना जाँचे किसी की भी बात मान लेने वाला व्यक्ति \"कान का कच्चा\" कहलाता है।"},
    {"q":"मुहावरा \"नाक के बाल होना\" का अर्थ है—","o":["घमंडी होना","अपमानित होना","बहुत बूढ़ा होना","अत्यंत प्रिय और विश्वासपात्र होना"],"a":3,"e":"जिस पर बहुत भरोसा हो, जो हर समय साथ रहे — नाक का बाल।"},
    {"q":"मुहावरा \"नाक रगड़ना\" का अर्थ है—","o":["दीनतापूर्वक विनती करना","नाक साफ़ करना","घमंड करना","लड़ाई करना"],"a":0,"e":"गिड़गिड़ाकर, बार-बार झुककर प्रार्थना करना।"},
    {"q":"मुहावरा \"नाक म दम करना\" का अर्थ है—","o":["साँस रोकना","बहुत परेशान करना","प्रतिष्ठा बढ़ाना","ज़ुकाम होना"],"a":1,"e":"किसी को इतना तंग करना कि वह ऊब जाए।"},
    {"q":"मुहावरा \"मुँह के खाना\" का अर्थ है—","o":["भोजन करना","चुगली करना","बुरी तरह पराजित होना","झूठ बोलना"],"a":2,"e":"प्रतिद्वंद्वी से करारी हार होना।"},
    {"q":"मुहावरा \"मुँह ताकना\" का अर्थ है—","o":["घूरना","सुंदरता देखना","मज़ाक उड़ाना","दूसरे पर आश्रित रहना / सहायता की आशा से देखना"],"a":3,"e":"किसी की कृपा या सहायता की प्रतीक्षा करना।"},
    {"q":"मुहावरा \"मुँह म दही जमना\" का अर्थ है—","o":["चुप रह जाना (कुछ न बोल पाना)","मीठा बोलना","भूख लगना","दही खाना"],"a":0,"e":"ज़रूरत के समय भी कुछ न बोलना — जैसे मुँह में दही जम गया हो।"},
    {"q":"मुहावरा \"मुँह लुकाना\" का अर्थ है—","o":["मुँह धोना","लज्जा के कारण छिपना","खाना छिपाना","मुस्कराना"],"a":1,"e":"लुकाना = छिपाना। शर्म से सामने न आना।"},
    {"q":"मुहावरा \"हाथ धो के पाछू पड़ना\" का अर्थ है—","o":["हाथ साफ़ रखना","पीछे हट जाना","पूरी तरह किसी के पीछे पड़ जाना","भोजन के बाद आराम करना"],"a":2,"e":"किसी काम या व्यक्ति के पीछे पूरी शक्ति से लग जाना। पाछू = पीछे।"},
    {"q":"मुहावरा \"हाथ मलना\" का अर्थ है—","o":["हाथ गरम करना","सहायता करना","ताली बजाना","पछताना"],"a":3,"e":"अवसर हाथ से निकल जाने पर पछताना।"},
    {"q":"मुहावरा \"हाथ बँटाना\" का अर्थ है—","o":["काम में सहायता करना","संपत्ति बाँटना","झगड़ा करना","हाथ मिलाना"],"a":0,"e":"किसी के काम में भागीदारी करके उसकी मदद करना।"},
    {"q":"मुहावरा \"हाथ खींचना\" का अर्थ है—","o":["हाथ पकड़ना","सहयोग बंद कर देना","चोरी करना","अधिकार जताना"],"a":1,"e":"पहले दी जा रही सहायता या साथ को रोक लेना।"},
    {"q":"मुहावरा \"गोड़ उखड़ना\" का अर्थ है—","o":["पैर में मोच आना","नाचना","हारकर भाग खड़ा होना","स्थिर हो जाना"],"a":2,"e":"मुकाबले में टिक न पाना। गोड़ = पैर। उलटा: गोड़ जमाना = स्थिर होना।"},
    {"q":"मुहावरा \"गोड़ जमाना\" का अर्थ है—","o":["पैर ठंडे होना","भाग जाना","नाचना-कूदना","स्थिर होना / अपना स्थान पक्का करना"],"a":3,"e":"किसी जगह या पद पर अपनी स्थिति मज़बूत कर लेना।"},
    {"q":"मुहावरा \"पेट म दाढ़ी होना\" का अर्थ है—","o":["कम उम्र में अधिक चतुर होना","मोटा होना","बहुत भूखा होना","बूढ़ा दिखना"],"a":0,"e":"छोटी उम्र में ही बड़ों जैसी चालाकी होना।"},
    {"q":"मुहावरा \"पेट काटना\" का अर्थ है—","o":["ऑपरेशन करना","खर्च घटाकर बचत करना","भूख मिटाना","धोखा देना"],"a":1,"e":"अपनी ज़रूरतें कम करके पैसे बचाना।"},
    {"q":"मुहावरा \"पेट म बात नइ पचना\" किसके लिए कहा जाता है?","o":["अपच के रोगी के लिए","कम खाने वाले के लिए","जो कोई बात छिपा न सके","चुप रहने वाले के लिए"],"a":2,"e":"जो व्यक्ति सुनी हुई बात तुरंत दूसरों को बता दे। नइ = नहीं।"},
    {"q":"मुहावरा \"करेजा फटना\" का अर्थ है—","o":["हृदय-रोग होना","बहुत साहसी होना","ईर्ष्या होना","अत्यधिक दुःख होना"],"a":3,"e":"करेजा = कलेजा। भारी शोक से मन फट जाना। तुलना: करेजा जुड़ाना = मन को शांति मिलना।"},
    {"q":"मुहावरा \"करेजा के टुकड़ा\" का अर्थ है—","o":["अत्यंत प्रिय संतान","दुश्मन","टूटा हुआ दिल","बीमार व्यक्ति"],"a":0,"e":"माता-पिता के लिए प्यारी संतान \"कलेजे का टुकड़ा\" होती है।"},
    {"q":"मुहावरा \"छाती म साँप लोटना\" का अर्थ है—","o":["डर जाना","ईर्ष्या होना","बीमार होना","प्रसन्न होना"],"a":1,"e":"दूसरे की उन्नति देखकर जलना। तुलना: छाती फूलना = गर्व अनुभव होना।"},
    {"q":"मुहावरा \"दाँत खट्टा करना\" का अर्थ है—","o":["खट्टा खाना","दाँत में दर्द होना","बुरी तरह हराना","चिढ़ाना"],"a":2,"e":"शत्रु को ऐसी हार देना कि वह फिर सामने न आए।"},
    {"q":"मुहावरा \"दाँत काटी रोटी\" का अर्थ है—","o":["आधी रोटी","भूख","झगड़ा","गहरी मित्रता"],"a":3,"e":"एक ही रोटी को दाँत से काटकर बाँट लेने जितनी घनिष्ठ दोस्ती।"},
    {"q":"मुहावरा \"मुड़ उठाना\" का अर्थ है—","o":["विद्रोह करना","सम्मान देना","सिर दर्द होना","जागना"],"a":0,"e":"मुड़ = सिर। सत्ता या व्यवस्था के विरुद्ध खड़े होना।"},
    {"q":"मुहावरा \"मुड़ धुनना\" का अर्थ है—","o":["बाल धोना","पछताना / शोक करना","नाचना","सोचना"],"a":1,"e":"भारी हानि या भूल पर सिर पीटकर पछताना।"},
    {"q":"मुहावरा \"माथा ठनकना\" का अर्थ है—","o":["सिर में चोट लगना","ज़ोर से हँसना","अनिष्ट की आशंका होना","क्रोध आना"],"a":2,"e":"किसी बात पर अचानक बुरे परिणाम का संदेह होना।"},
    {"q":"मुहावरा \"लहू सूखना\" का अर्थ है—","o":["घाव भरना","कमज़ोर होना","बहुत परिश्रम करना","बहुत डर जाना"],"a":3,"e":"भय से जैसे खून सूख जाए। लहू = खून। तुलना: लहू-पसीना एक करना = कठोर परिश्रम।"},
    {"q":"मुहावरा \"पानी फेरना\" का अर्थ है—","o":["किए-कराए को नष्ट कर देना","सिंचाई करना","स्नान करना","लज्जित होना"],"a":0,"e":"किसी की मेहनत या योजना को बेकार कर देना। (पानी-पानी होना = लज्जित होना।)"},
    {"q":"मुहावरा \"आगी म घी डारना\" का अर्थ है—","o":["हवन करना","क्रोध या झगड़े को और भड़काना","खाना पकाना","शांत करना"],"a":1,"e":"आग में घी डालने से लपटें बढ़ती हैं — विवाद को और बढ़ाना। डारना = डालना।"},
    {"q":"मुहावरा \"घाव म नून छिंचना\" का अर्थ है—","o":["घाव का इलाज करना","भोजन में नमक डालना","दुखी को और दुःख देना","सहानुभूति दिखाना"],"a":2,"e":"नून = नमक। घाव पर नमक छिड़कने से पीड़ा बढ़ती है।"},
    {"q":"मुहावरा \"डूमर के फूल होना\" का अर्थ है—","o":["सुंदर होना","सस्ता होना","मुरझा जाना","दुर्लभ होना"],"a":3,"e":"डूमर = गूलर; गूलर का फूल दिखाई नहीं देता, इसलिए दुर्लभ वस्तु/व्यक्ति के लिए प्रयोग।"},
    {"q":"मुहावरा \"थूक के चाटना\" का अर्थ है—","o":["कही हुई बात से मुकर जाना","गंदगी फैलाना","अपमान करना","भूखा होना"],"a":0,"e":"अपने वचन या निर्णय को वापस ले लेना।"},
    {"q":"मुहावरा \"लोहा मानना\" का अर्थ है—","o":["लोहे का व्यापार करना","किसी की श्रेष्ठता स्वीकार करना","कठोर होना","हार न मानना"],"a":1,"e":"प्रतिद्वंद्वी की शक्ति या योग्यता को स्वीकार कर लेना। (लोहा के चना चबाना = अत्यंत कठिन काम।)"},
    {"q":"मुहावरा \"गाल बजाना\" का अर्थ है—","o":["गाना गाना","थप्पड़ मारना","डींग मारना","मुस्कराना"],"a":2,"e":"बढ़-चढ़कर अपनी बड़ाई करना, बेकार की बातें करना।"},
    {"q":"मुहावरा \"दिन म तारा दिखना\" का अर्थ है—","o":["अद्भुत घटना देखना","नज़र तेज़ होना","आकाश साफ़ होना","घोर संकट में घबरा जाना"],"a":3,"e":"भारी विपत्ति आने पर होश उड़ जाना।"},
    {"q":"मुहावरा \"अँगरी म नचाना\" का अर्थ है—","o":["पूरी तरह वश में रखना","नृत्य सिखाना","दोष लगाना","इशारा करना"],"a":0,"e":"अँगरी = उँगली। किसी को अपनी इच्छा से चलाना। (अँगरी उठाना = दोष लगाना।)"},
    {"q":"मुहावरा \"टेड़गा अँगरी ले घी निकालना\" का अर्थ है—","o":["घी बनाना","कड़ाई या चतुराई से काम निकालना","चोरी करना","उँगली टेढ़ी होना"],"a":1,"e":"सीधी उँगली से घी न निकले तो टेढ़ी (टेड़गा) करनी पड़ती है — सीधे तरीके से काम न बने तो युक्ति लगाना।"},
    {"q":"मुहावरा \"पथरा के लकीर\" का अर्थ है—","o":["पत्थर पर चित्र","कठोर हृदय","अमिट, अटल बात","मार्ग का निशान"],"a":2,"e":"पत्थर (पथरा) पर खिंची लकीर नहीं मिटती — कभी न बदलने वाली बात।"},
    {"q":"मुहावरा \"कुआँ के मेचका\" किसके लिए प्रयुक्त होता है?","o":["तैराक के लिए","शोर करने वाले के लिए","आलसी के लिए","सीमित ज्ञान वाले व्यक्ति के लिए"],"a":3,"e":"मेचका = मेंढक। कुएँ का मेंढक बाहरी दुनिया नहीं जानता — संकुचित दृष्टि वाला।"},
    {"q":"मुहावरा \"बेंदरा बाँट\" का अर्थ है—","o":["बीच वाले द्वारा सब हड़प लेने वाला अनुचित बँटवारा","बराबर बँटवारा","बंदरों को भोजन देना","खेल-खेल में बाँटना"],"a":0,"e":"दो बिल्लियों की रोटी बराबर करने के बहाने बंदर पूरी रोटी खा गया — इसी कथा से।"},
    {"q":"मुहावरा \"तेली के बइला\" किसके लिए कहा जाता है?","o":["बलवान व्यक्ति","दिन-रात खटने वाला पर आगे न बढ़ पाने वाला","आलसी व्यक्ति","धनवान व्यापारी"],"a":1,"e":"कोल्हू का बैल गोल-गोल घूमता रहता है — मेहनत बहुत, प्रगति नहीं। बइला = बैल।"},
    {"q":"मुहावरा \"आँधी के आमा\" का अर्थ है—","o":["कच्चा आम","तूफ़ान से नुकसान","बिना परिश्रम मिली सस्ती वस्तु","दुर्लभ फल"],"a":2,"e":"आँधी में गिरे आम मुफ़्त में बटोर लिए जाते हैं — सस्ती/बिना मेहनत की चीज़।"},
    {"q":"मुहावरा \"भीजे बिलई बनना\" का अर्थ है—","o":["बारिश में भीगना","चालाकी करना","क्रोधित होना","डर से सहम जाना"],"a":3,"e":"भीगी (भीजे) बिल्ली (बिलई) की तरह दबकर चुप हो जाना।"},
    {"q":"मुहावरा \"कनिहा टूटना\" का अर्थ है—","o":["हिम्मत या आर्थिक शक्ति टूट जाना","कमर में दर्द होना","झुककर चलना","काम के लिए तैयार होना"],"a":0,"e":"कनिहा = कमर। भारी हानि से सहारा टूट जाना। उलटा भाव: कनिहा कसना = काम के लिए तैयार होना।"},
    {"q":"मुहावरा \"भुइयाँ म गोड़ नइ परना\" का अर्थ है—","o":["उड़ना","अत्यधिक प्रसन्न होना","घमंड से गिर जाना","लंगड़ाकर चलना"],"a":1,"e":"भुइयाँ = धरती, गोड़ = पैर। ख़ुशी के मारे पैर ज़मीन पर न पड़ना।"},
    {"q":"मुहावरा \"अपन गोड़ म टँगिया मारना\" का अर्थ है—","o":["लकड़ी काटना","चोट का इलाज करना","अपना नुकसान स्वयं करना","दूसरे को हानि पहुँचाना"],"a":2,"e":"टँगिया = कुल्हाड़ी। अपने ही पैर पर कुल्हाड़ी मारना।"},
    {"q":"छत्तीसगढ़ी शब्द \"घेंच\" का हिन्दी अर्थ है—","o":["घुटना","घर","घी","गर्दन"],"a":3,"e":"घेंच = गर्दन। गर = गला; माड़ी = घुटना।"},
    {"q":"छत्तीसगढ़ी शब्द \"माड़ी\" का अर्थ है—","o":["घुटना","मिट्टी","चावल का माँड़","मटका"],"a":0,"e":"माड़ी = घुटना। चावल के पानी (माँड़) से भ्रमित न हों।"},
    {"q":"छत्तीसगढ़ी में \"खांध\" किस अंग को कहते हैं?","o":["कमर","कंधा","कोहनी","छाती"],"a":1,"e":"खांध = कंधा; कनिहा = कमर।"},
    {"q":"छत्तीसगढ़ी में \"अँगरी\" का अर्थ है—","o":["अंगूर","अँगूठी","उँगली","आँगन"],"a":2,"e":"अँगरी = उँगली; अँगूठी = मुंदरी; आँगन = अँगना।"},
    {"q":"छत्तीसगढ़ी शब्द \"डउकी\" का अर्थ है—","o":["डोली","बेटी","दादी","पत्नी"],"a":3,"e":"डउका = पति, डउकी = पत्नी। गोसइयाँ/गोसइन भी पति/पत्नी के लिए प्रयुक्त।"},
    {"q":"छत्तीसगढ़ी में \"फूफू\" किस रिश्ते के लिए है?","o":["बुआ","मौसी","मामी","चाची"],"a":0,"e":"फूफू = बुआ (पिता की बहन); काकी = चाची, मामी = मामी।"},
    {"q":"छत्तीसगढ़ी में \"दमांद\" किसे कहते हैं?","o":["देवर","दामाद","दादा","भतीजा"],"a":1,"e":"दमांद = दामाद। दामाद को आदर से \"पहुना\" (मेहमान) भी कहते हैं।"},
    {"q":"छत्तीसगढ़ी में \"नोनी\" शब्द किसके लिए प्रयुक्त होता है?","o":["नानी","नौकरानी","लड़की / बेटी","नई बहू"],"a":2,"e":"नोनी = लड़की, बेटी (स्नेह से); \"बाबू\" = बेटा।"},
    {"q":"छत्तीसगढ़ी शब्द \"संगवारी\" का अर्थ है—","o":["संगीतकार","संगम","सगा भाई","साथी / मित्र"],"a":3,"e":"संगवारी = साथी। \"मितान\" भी मित्र के लिए, पर मितान प्रायः विधिवत् बदा गया मित्र होता है।"},
    {"q":"छत्तीसगढ़ी शब्द \"मनखे\" का अर्थ है—","o":["मनुष्य","मन","मक्खन","मनौती"],"a":0,"e":"मनखे = मनुष्य; बहुवचन — मनखेमन।"},
    {"q":"छत्तीसगढ़ी में \"तुमा\" किस सब्ज़ी को कहते हैं?","o":["कद्दू","लौकी","तोरई","टमाटर"],"a":1,"e":"तुमा = लौकी; कुम्हड़ा = कद्दू; पताल = टमाटर।"},
    {"q":"छत्तीसगढ़ी में \"कुम्हड़ा\" का अर्थ है—","o":["कुम्हार","लौकी","कद्दू","करेला"],"a":2,"e":"कुम्हड़ा = कद्दू (कुम्हड़ा/कोंहड़ा)। लौकी = तुमा।"},
    {"q":"छत्तीसगढ़ी शब्द \"बिही\" का हिन्दी अर्थ है—","o":["बीज","बेर","सेब","अमरूद"],"a":3,"e":"बिही = अमरूद; बोइर = बेर।"},
    {"q":"छत्तीसगढ़ी में \"बोइर\" किस फल को कहते हैं?","o":["बेर","बेल","बड़हल","जामुन"],"a":0,"e":"बोइर = बेर; बेल = बेल, जामुन = जामुन। बोइर छत्तीसगढ़ के वनों और मेड़ों पर सहज मिलने वाला फल है।"},
    {"q":"छत्तीसगढ़ी में \"कुसियार\" का अर्थ है—","o":["कुश घास","गन्ना","कुल्हाड़ी","केसर"],"a":1,"e":"कुसियार = गन्ना। जनऊला में भुट्टे के पौधे की तुलना कुसियार से की गई है।"},
    {"q":"छत्तीसगढ़ी में \"अमली\" का अर्थ है—","o":["आँवला","आम","इमली","अमचूर"],"a":2,"e":"अमली = इमली; आमा = आम। अमली (इमली) बस्तर का प्रमुख वनोपज है।"},
    {"q":"छत्तीसगढ़ी शब्द \"तिवरा\" किस दलहन फसल का नाम है?","o":["मसूर","उड़द","अरहर","खेसारी (लाखड़ी)"],"a":3,"e":"तिवरा = खेसारी (लाखड़ी); राहेर = अरहर, उरिद = उड़द।"},
    {"q":"छत्तीसगढ़ी में \"राहेर\" का अर्थ है—","o":["अरहर","राई","रास्ता","रहट"],"a":0,"e":"राहेर = अरहर (तुअर) दाल। रास्ता = रद्दा।"},
    {"q":"छत्तीसगढ़ी शब्द \"हरदी\" का अर्थ है—","o":["हरा","हल्दी","हड्डी","हार"],"a":1,"e":"हरदी = हल्दी। विवाह की \"हरदाही\" रस्म इसी से। हरा = हरियर।"},
    {"q":"छत्तीसगढ़ी में \"लसुन\" का अर्थ है—","o":["प्याज़","मूली","लहसुन","अदरक"],"a":2,"e":"लसुन = लहसुन; प्याज़ = गोंदली।"},
    {"q":"छत्तीसगढ़ी में \"घीव\" का अर्थ है—","o":["गेहूँ","गुड़","गीला","घी"],"a":3,"e":"घीव = घी; गुर = गुड़; गहूँ = गेहूँ।"},
    {"q":"छत्तीसगढ़ी में \"बासी\" किसे कहते हैं?","o":["रात में पानी में भिगोया पका भात","सड़ा हुआ भोजन","बाँस की सब्ज़ी","चावल का आटा"],"a":0,"e":"बासी छत्तीसगढ़ का पारंपरिक भोजन है — पके भात को रात भर पानी में भिगोकर सुबह खाते हैं। ध्यान दें — यहाँ बासी का अर्थ \"सड़ा\" नहीं है।"},
    {"q":"छत्तीसगढ़ी में \"पेज\" क्या है?","o":["किताब का पन्ना","चावल का माँड़-युक्त पतला पेय","पीपल का पत्ता","पानी का घड़ा"],"a":1,"e":"पेज — चावल को अधिक पानी में पकाकर बना पतला पेय; ग्रामीण छत्तीसगढ़ का पारंपरिक आहार।"},
    {"q":"छत्तीसगढ़ी में \"नाँगर\" किसे कहते हैं?","o":["नगर","नगाड़ा","हल","नाव"],"a":2,"e":"नाँगर = हल। हरेली पर्व पर नाँगर सहित कृषि-औज़ारों की पूजा होती है।"},
    {"q":"छत्तीसगढ़ी शब्द \"कोठार\" का अर्थ है—","o":["पशुशाला","अनाज भंडार","कोठरी","खलिहान"],"a":3,"e":"कोठार = खलिहान (जहाँ फसल की मिंजाई होती है); कोठा = पशुशाला; कोठी = अनाज भंडार।"},
    {"q":"छत्तीसगढ़ी में \"कोठा\" किसे कहते हैं?","o":["पशुशाला","खलिहान","कोठी","कोठरी"],"a":0,"e":"कोठा = गाय-बैल बाँधने की जगह। गौठान = गाँव के पशुओं के एकत्र होने का स्थान।"},
    {"q":"छत्तीसगढ़ी कृषि-शब्द \"बियासी\" का अर्थ है—","o":["बीज बोना","खड़ी धान की फसल में हल चलाना","फसल काटना","बीज का भंडारण"],"a":1,"e":"बियासी — धान बोने के लगभग एक माह बाद खड़ी फसल में हल चलाकर निराई-छँटाई की पारंपरिक विधि।"},
    {"q":"छत्तीसगढ़ी शब्द \"मिंजई\" का अर्थ है—","o":["सिंचाई","बुवाई","मड़ाई (बालियों से दाना अलग करना)","निराई"],"a":2,"e":"मिंजई = मिंजाई/मड़ाई, जो कोठार (खलिहान) में होती है। निंदई = निराई, लुवई = कटाई।"},
    {"q":"छत्तीसगढ़ी में \"लुवई\" का अर्थ है—","o":["बुवाई","रोपाई","सिंचाई","फसल की कटाई"],"a":3,"e":"लुवई = कटाई; \"लूना\" = काटना। हाना \"जइसन बोंही, तइसन लूही\" में \"लूही\" = काटेगा।"},
    {"q":"छत्तीसगढ़ी में \"खुर्रा बोनी\" किसे कहते हैं?","o":["सूखे खेत में वर्षा से पहले बुवाई","पानी भरे खेत में रोपाई","खुरपी से निराई","खलिहान की सफ़ाई"],"a":0,"e":"खुर्रा बोनी — सूखी भूमि में बीज बो देना, जिससे पहली वर्षा के साथ अंकुरण हो। बोनी = बुवाई।"},
    {"q":"छत्तीसगढ़ी में \"पैरा\" किसे कहते हैं?","o":["पैर","पुआल","पहरा","पानी"],"a":1,"e":"पैरा = धान का पुआल, जो पशु-आहार के रूप में काम आता है। गोड़ = पैर।"},
    {"q":"छत्तीसगढ़ी शब्द \"खातू\" का अर्थ है—","o":["खाता","खाना","खाद","खेत"],"a":2,"e":"खातू = खाद (विशेषकर गोबर-खाद)।"},
    {"q":"छत्तीसगढ़ी में \"रापा\" किस औज़ार को कहते हैं?","o":["हँसिया","कुल्हाड़ी","कुदाल","फावड़ा"],"a":3,"e":"रापा = फावड़ा; टँगिया = कुल्हाड़ी; कुदारी = कुदाल।"},
    {"q":"छत्तीसगढ़ी में \"टँगिया\" का अर्थ है—","o":["कुल्हाड़ी","टाँग","खूँटी","टोकरी"],"a":0,"e":"टँगिया = कुल्हाड़ी। मुहावरा: अपन गोड़ म टँगिया मारना = अपना नुकसान स्वयं करना।"},
    {"q":"छत्तीसगढ़ी में \"बरदी\" का अर्थ है—","o":["वर्दी","मवेशियों का झुंड","बरसात","बारात"],"a":1,"e":"बरदी = गाय-बैलों का झुंड जिसे चरवाहा (राउत) चराने ले जाता है।"},
    {"q":"छत्तीसगढ़ी में \"खुमरी\" क्या है?","o":["खाट","मिट्टी का घड़ा","बाँस और पत्तों से बनी छतरीनुमा टोपी","धान का भंडार"],"a":2,"e":"खुमरी — बारिश-धूप से बचाव के लिए किसान/चरवाहे इसे सिर पर पहनते हैं।"},
    {"q":"छत्तीसगढ़ी में \"धरसा\" किसे कहते हैं?","o":["धरती","धान का पौधा","नदी का किनारा","खेतों के बीच का कच्चा रास्ता"],"a":3,"e":"धरसा = गाँव से खेतों की ओर जाने वाला कच्चा रास्ता। रद्दा = रास्ता (सामान्य)।"},
    {"q":"छत्तीसगढ़ी में \"कन्हार\" किस प्रकार की मिट्टी है?","o":["काली (भारी, चिकनी) मिट्टी","रेतीली मिट्टी","लाल-कंकरीली मिट्टी","पीली दोमट मिट्टी"],"a":0,"e":"कन्हार = काली मिट्टी (अधिक जल-धारण क्षमता); मटासी = पीली-भूरी; भाठा = कंकरीली कम उपजाऊ।"},
    {"q":"छत्तीसगढ़ी में \"डोली\" शब्द खेती के संदर्भ में किसके लिए है?","o":["पालकी","खेत","झूला","टोकरी"],"a":1,"e":"खेती की बोली में डोली = खेत (धान का खेत)। सामान्य हिन्दी में डोली = पालकी — भ्रम से बचें।"},
    {"q":"छत्तीसगढ़ी में \"परछी\" का अर्थ है—","o":["परछाई","परदा","बरामदा","छत"],"a":2,"e":"परछी = घर का बरामदा; छानी = छप्पर; छइहाँ = परछाई।"},
    {"q":"छत्तीसगढ़ी में \"छानी\" किसे कहते हैं?","o":["छलनी","छाता","छाती","छप्पर"],"a":3,"e":"छानी = घर की छत/छप्पर; छलनी = चलनी।"},
    {"q":"छत्तीसगढ़ी शब्द \"भिथिया\" का अर्थ है—","o":["दीवार","भीतर","भीड़","भीख"],"a":0,"e":"भिथिया = दीवार (भीत)। हरेली/दीवाली पर भिथिया की लिपाई-पुताई होती है।"},
    {"q":"छत्तीसगढ़ी में \"लुगरा\" किस वस्त्र को कहते हैं?","o":["धोती","साड़ी","कुर्ता","लहँगा"],"a":1,"e":"लुगरा = साड़ी; पोलखा = ब्लाउज़; पागा = पगड़ी।"},
    {"q":"छत्तीसगढ़ी में \"बहरी\" किसे कहते हैं?","o":["बहरा व्यक्ति","बहन","झाड़ू","बाहर"],"a":2,"e":"बहरी = झाड़ू। ध्यान दें — \"बहरा\" कृषि में नीची भूमि को कहते हैं।"},
    {"q":"छत्तीसगढ़ी में \"ढेंकी\" क्या है?","o":["ढक्कन","ढोल","टेढ़ी लकड़ी","धान कूटने का लकड़ी का यंत्र"],"a":3,"e":"ढेंकी — पैर से चलाया जाने वाला धान कूटने का पारंपरिक यंत्र; जाँता = हाथ-चक्की।"},
    {"q":"छत्तीसगढ़ी शब्द \"पर्रा\" किसे कहते हैं?","o":["बाँस की बड़ी चपटी टोकरी","पर्दा","पंख","पड़ोसी"],"a":0,"e":"पर्रा — बाँस की बनी बड़ी चपटी टोकरी। जनऊला \"पर्रा भर लाई\" में आकाश को पर्रा कहा गया।"},
    {"q":"छत्तीसगढ़ी में \"उत्ती\" किस दिशा को कहते हैं?","o":["पश्चिम","पूर्व","उत्तर","दक्षिण"],"a":1,"e":"उत्ती = पूर्व (जहाँ सूर्य उगता है); बुड़ती = पश्चिम (जहाँ सूर्य डूबता है)। \"उत्ती\" को \"उत्तर\" समझना आम भूल है।"},
    {"q":"छत्तीसगढ़ी में \"रक्सहूँ\" किस दिशा का नाम है?","o":["उत्तर","पूर्व","दक्षिण","पश्चिम"],"a":2,"e":"रक्सहूँ = दक्षिण; भंडार = उत्तर।"},
    {"q":"छत्तीसगढ़ी में उत्तर दिशा को क्या कहते हैं?","o":["उत्ती","बुड़ती","रक्सहूँ","भंडार"],"a":3,"e":"भंडार = उत्तर। उत्ती = पूर्व, बुड़ती = पश्चिम, रक्सहूँ = दक्षिण।"},
    {"q":"छत्तीसगढ़ी शब्द \"चंदैनी\" का अर्थ है—","o":["तारे","चाँदनी रात","चंदन","चाँदी"],"a":0,"e":"चंदैनी = तारे; चंदा = चंद्रमा। जनऊला \"नंद बबा के नौ सौ गाय\" का उत्तर चंदैनी है।"},
    {"q":"छत्तीसगढ़ी में \"करा\" का अर्थ है—","o":["कड़ा","ओला","करवा","काला"],"a":1,"e":"करा = ओला (आकाश से गिरने वाली बर्फ़)। हाना \"मुड़ मुड़ावत ओला परगे\" में ओला शब्द है।"},
    {"q":"छत्तीसगढ़ी शब्द \"चिखला\" का अर्थ है—","o":["चीख","चिकना","कीचड़","चिड़िया"],"a":2,"e":"चिखला = कीचड़; धुर्रा = धूल। चिड़िया = चिरई।"},
    {"q":"छत्तीसगढ़ी में \"अबेर\" का अर्थ है—","o":["अभी","अबीर","जल्दी","देर"],"a":3,"e":"अबेर = देर; बेरा = समय। \"अबेर होगे\" = देर हो गई।"},
    {"q":"छत्तीसगढ़ी में \"काली\" शब्द का अर्थ है—","o":["कल (बीता हुआ या आने वाला दिन)","काला","देवी काली","खाली"],"a":0,"e":"काली = कल; काला रंग = करिया। \"काली आहूँ\" = कल आऊँगा।"},
    {"q":"छत्तीसगढ़ी में \"बघवा\" किस पशु को कहते हैं?","o":["बगुला","बाघ","बकरा","भेड़िया"],"a":1,"e":"बघवा = बाघ; बोकरा = बकरा; कोकड़ा = बगुला।"},
    {"q":"छत्तीसगढ़ी में \"परेवा\" का अर्थ है—","o":["परी","पड़वा (भैंस का बच्चा)","कबूतर","पपीहा"],"a":2,"e":"परेवा = कबूतर; सुवा = तोता; कौंवा = कौआ।"},
    {"q":"छत्तीसगढ़ी में \"मकरा\" का अर्थ है—","o":["मगरमच्छ","मक्का","मक्खी","मकड़ी"],"a":3,"e":"मकरा = मकड़ी; माछी = मक्खी; जोंधरी = मक्का।"},
    {"q":"छत्तीसगढ़ी में \"छेरी\" किसे कहते हैं?","o":["बकरी","भेड़","छिपकली","छलनी"],"a":0,"e":"छेरी = बकरी; बोकरा = बकरा। भेड़ = भेंड़।"},
    {"q":"छत्तीसगढ़ी में \"कोरी\" शब्द किस संख्या की इकाई है?","o":["दस","बीस","बारह (दर्जन)","सौ"],"a":1,"e":"एक कोरी = 20। पाँच कोरी = 100, अठारा कोरी = 360।"},
    {"q":"छत्तीसगढ़ी में \"सनिच्चर\" किस दिन को कहते हैं?","o":["रविवार","सोमवार","शनिवार","बृहस्पतिवार"],"a":2,"e":"सनिच्चर = शनिवार; इतवार = रविवार; बिरस्पत = बृहस्पतिवार।"},
    {"q":"छत्तीसगढ़ी में \"कुवाँर\" किस महीने का नाम है?","o":["कार्तिक","भाद्रपद","मार्गशीर्ष","आश्विन"],"a":3,"e":"कुवाँर (क्वार) = आश्विन; कातिक = कार्तिक; अग्घन = मार्गशीर्ष।"},
    {"q":"छत्तीसगढ़ी शब्द \"गरू\" का अर्थ है—","o":["भारी","गुरु","हल्का","गर्म"],"a":0,"e":"गरू = भारी; हरु = हल्का — दोनों विपरीतार्थक।"},
    {"q":"छत्तीसगढ़ी शब्द \"करू\" का अर्थ है—","o":["काला","कड़वा","करना","कमज़ोर"],"a":1,"e":"करू = कड़वा (करेला करू होथे); चुरपुर = तीखा; करिया = काला।"},
    {"q":"छत्तीसगढ़ी में \"जम्मो\" का अर्थ है—","o":["जमा करना","जामुन","सब / सारा","जंगल"],"a":2,"e":"जम्मो = सब, सारे। \"जम्मो झन\" = सब लोग।"},
    {"q":"छत्तीसगढ़ी में \"अड़बड़\" का अर्थ है—","o":["गड़बड़","अड़ियल","उलझा हुआ","बहुत"],"a":3,"e":"अड़बड़ = बहुत (अड़बड़ सुग्घर = बहुत सुंदर)। \"अबड़\" भी इसी अर्थ में।"},
    {"q":"छत्तीसगढ़ी शब्द \"खाल्हे\" का अर्थ है—","o":["नीचे","खाली","खाल","ऊपर"],"a":0,"e":"खाल्हे = नीचे; \"तरी\" भी नीचे के अर्थ में (दीया तरी अँधियार)।"},
    {"q":"छत्तीसगढ़ी में \"तीर\" शब्द प्रायः किस अर्थ में आता है?","o":["बाण","पास / निकट","तेज़","तीन"],"a":1,"e":"तीर = पास (मोर तीर आ = मेरे पास आओ); \"नदिया के तीर\" = नदी के किनारे।"},
    {"q":"छत्तीसगढ़ी क्रिया \"अगोरना\" का अर्थ है—","o":["आगे बढ़ना","उगना","प्रतीक्षा करना","अगोचर होना"],"a":2,"e":"अगोरना = राह देखना, प्रतीक्षा करना। \"थोरकुन अगोर\" = थोड़ा रुको।"},
    {"q":"छत्तीसगढ़ी क्रिया \"बिसाना\" का अर्थ है—","o":["बेचना","भूलना","बिछाना","खरीदना"],"a":3,"e":"बिसाना = खरीदना (हिन्दी \"बिसाहना\")। बेचने को \"बेचना\" ही कहते हैं।"},
    {"q":"छत्तीसगढ़ी क्रिया \"बुताना\" का अर्थ है—","o":["बुझाना","बुलाना","बोना","बताना"],"a":0,"e":"बुताना = (आग/दीया) बुझाना। \"दीया बुतागे\" = दीया बुझ गया।"},
    {"q":"छत्तीसगढ़ी क्रिया \"चिन्हना\" का अर्थ है—","o":["चिह्न लगाना","पहचानना","चीखना","छीनना"],"a":1,"e":"चिन्हना = पहचानना (हिन्दी \"चीन्हना\")। \"मोला चिन्हथस?\" = मुझे पहचानते हो?"},
    {"q":"छत्तीसगढ़ी क्रिया \"सकेलना\" का अर्थ है—","o":["सिकोड़ना","सेकना","समेटना / इकट्ठा करना","सहना"],"a":2,"e":"सकेलना = समेटना, बटोरना (धान सकेलना)।"},
    {"q":"छत्तीसगढ़ी क्रिया \"राँधना\" का अर्थ है—","o":["रोकना","रौंदना","बाँधना","भोजन पकाना"],"a":3,"e":"राँधना = भोजन पकाना (भात राँधना = चावल पकाना)।"},
    {"q":"छत्तीसगढ़ी क्रिया \"गोठियाना\" का अर्थ है—","o":["बात करना","गाँठ बाँधना","गोता लगाना","गाना"],"a":0,"e":"गोठ = बात, गोठियाना = बात करना।"},
    {"q":"हिन्दी \"मेरा\" के लिए छत्तीसगढ़ी शब्द है—","o":["मोला","मोर","मैं","हमर"],"a":1,"e":"मोर = मेरा/मेरी/मेरे (लिंग से नहीं बदलता); मोला = मुझे; हमर = हमारा।"},
    {"q":"छत्तीसगढ़ी \"तोला\" का हिन्दी अर्थ है—","o":["तेरा","तू","तुझे","तुम लोग"],"a":2,"e":"तोला = तुझे/तुमको; तोर = तेरा; तैं = तू; तुमन = तुम लोग।"},
    {"q":"छत्तीसगढ़ी में \"ओमन\" का अर्थ है—","o":["उसका","हम लोग","आप","वे (लोग)"],"a":3,"e":"ओमन = वे; ओकर = उसका; हमन = हम।"},
    {"q":"छत्तीसगढ़ी \"हमर\" का हिन्दी अर्थ है—","o":["हमारा","हम","हमें","हमेशा"],"a":0,"e":"हमर = हमारा (\"हमर छत्तीसगढ़\"); हमन = हम; हमन ल = हमें।"},
    {"q":"छत्तीसगढ़ी में \"ओकर\" का अर्थ है—","o":["उसे","उसका","वह","उधर"],"a":1,"e":"ओकर = उसका; ओला = उसे; वो/ओ = वह।"},
    {"q":"छत्तीसगढ़ी वाक्य \"मैं स्कूल जाथँव\" का हिन्दी अर्थ है—","o":["मैं स्कूल गया","मैं स्कूल जाऊँगा","मैं स्कूल जाता हूँ","मैं स्कूल जा रहा था"],"a":2,"e":"\"-थँव\" वर्तमान काल उत्तम पुरुष का प्रत्यय है: जाथँव = जाता हूँ। गेंव = गया, जाहूँ = जाऊँगा।"},
    {"q":"छत्तीसगढ़ी \"वो काली आही\" का हिन्दी अर्थ है—","o":["वह कल आया था","वह आज आया","वह आता है","वह कल आएगा"],"a":3,"e":"\"आही\" = आएगा (भविष्य, अन्य पुरुष); काली = कल।"},
    {"q":"छत्तीसगढ़ी \"हमन जाबो\" का अर्थ है—","o":["हम जाएँगे","हम गए","हम जाते हैं","हमें जाना है"],"a":0,"e":"\"-बो\" भविष्य काल बहुवचन उत्तम पुरुष: जाबो = जाएँगे। जाथन = जाते हैं, गेन = गए।"},
    {"q":"छत्तीसगढ़ी \"वो गिस\" का हिन्दी रूप है—","o":["वह जाएगा","वह गया","वह जाता है","वह जा रहा है"],"a":1,"e":"\"गिस\" = गया (भूतकाल, अन्य पुरुष)। इसी प्रकार करिस = किया, खाइस = खाया।"},
    {"q":"छत्तीसगढ़ी \"झन जा\" का अर्थ है—","o":["जल्दी जाओ","जा रहे हो","मत जाओ","चले जाओ"],"a":2,"e":"\"झन\" निषेध (मत) के लिए; \"नइ\" सामान्य नकार (नहीं) के लिए।"},
    {"q":"छत्तीसगढ़ी \"कइसे हस?\" का हिन्दी अर्थ है—","o":["कहाँ हो?","कौन हो?","क्या कर रहे हो?","कैसे हो?"],"a":3,"e":"कइसे = कैसे, हस = हो (मध्यम पुरुष)। उत्तर — \"बने हँव\" (ठीक हूँ)।"},
    {"q":"छत्तीसगढ़ी में \"मैं ___ हँव\" — रिक्त स्थान में \"ठीक\" के लिए उपयुक्त शब्द है—","o":["बने","बड़का","बाहिर","बरोबर"],"a":0,"e":"बने = अच्छा/ठीक; \"मैं बने हँव\" = मैं ठीक हूँ। बरोबर = बराबर।"},
    {"q":"छत्तीसगढ़ी कारक-चिह्न \"ल\" का हिन्दी समतुल्य है—","o":["से","को","में","के लिए"],"a":1,"e":"\"ल\" = को (राम ल बला = राम को बुलाओ); ले = से; म = में; बर = के लिए।"},
    {"q":"छत्तीसगढ़ी में \"बर\" कारक-चिह्न का अर्थ है—","o":["पर","में","के लिए","से"],"a":2,"e":"\"बर\" = के लिए। हाना \"बिलई चलिस हज बर\" = बिल्ली हज के लिए चली।"},
    {"q":"रिक्त स्थान भरिए — हाना \"जइसन बोंही, तइसन ___\" ","o":["पाही","खाही","जाही","लूही"],"a":3,"e":"पूर्ण हाना: \"जइसन बोंही, तइसन लूही\" (जैसा बोएगा वैसा काटेगा)। लूना = फसल काटना।"},
    {"q":"रिक्त स्थान भरिए — हाना \"आमा के आमा, ___ के दाम\"","o":["गोही","छिलका","रुख","डारा"],"a":0,"e":"गोही = गुठली। पूर्ण हाना: \"आमा के आमा, गोही के दाम\" — दोहरा लाभ।"},
    {"q":"रिक्त स्थान भरिए — हाना \"बूँद-बूँद ले ___ भरथे\"","o":["तरिया","घइला","कोठी","पेट"],"a":1,"e":"पूर्ण हाना: \"बूँद-बूँद ले घइला भरथे\" — थोड़ा-थोड़ा जोड़ने से बड़ा संचय। घइला = घड़ा।"},
    {"q":"रिक्त स्थान भरिए — हाना \"अपन गली म ___ घलो शेर\"","o":["बिलई","बेंदरा","कुकुर","मुसुवा"],"a":2,"e":"पूर्ण हाना: \"अपन गली म कुकुर घलो शेर\" — अपने क्षेत्र में दुर्बल भी बलवान बन जाता है।"},
    {"q":"रिक्त स्थान भरिए — हाना \"खेती अपन सेती, नइ त नदिया के ___\"","o":["पानी","धार","पार","रेती"],"a":3,"e":"पूर्ण हाना: \"खेती अपन सेती, नइ त नदिया के रेती\" — रेती = रेत।"},
    {"q":"सूची-I (जनऊला) को सूची-II (उत्तर) से सुमेलित कीजिए —<br>(A) पेट चिरहा, पीठ कुबरा (B) पहाड़ ले उतरे रेचकी घोड़ी, ओकर पीला अठारा कोरी (C) खटिया गाँथे तान-बितान, दू सुतइया बाइस कान (D) एक पेड़ के बारा डारा, तीस-तीस के झोंथा<br>1. रावन अउ मंदोदरी 2. कौड़ी 3. बछर, महीना अउ दिन 4. चलनी","o":["A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1","A-1, B-4, C-2, D-3"],"a":0,"e":"A-2: कौड़ी का पेट चिरा, पीठ उभरी।<br>B-4: अठारा कोरी = 360 छेद — चलनी।<br>C-1: 20 + 2 = 22 कान — रावण-मंदोदरी।<br>D-3: 12 महीने, 30-30 दिन — वर्ष।"},
    {"q":"सूची-I (जनऊला) को सूची-II (उत्तर) से सुमेलित कीजिए —<br>(A) सूखा डबरी म बगुला फड़फड़ाय (B) छिछिल तलैया म, डूब मरय सितलैया (C) पान के ओधा, माँस के घोंघा (D) दिखब म लाल, छुअब म गुजगुज<br>1. पूड़ी 2. पताल 3. लाई 4. भाटा","o":["A-1, B-3, C-4, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-2, D-4"],"a":1,"e":"A-3: सूखी कड़ाही में उछलता लावा (लाई)।<br>B-1: उथले तेल में तली जाती पूड़ी।<br>C-4: पत्तों की ओट में गूदेदार बैंगन (भाटा)।<br>D-2: लाल और नरम टमाटर (पताल)।"},
    {"q":"सूची-I (हाना) को सूची-II (अर्थ) से सुमेलित कीजिए —<br>(A) ठलहा बनिया का करय, ए कोठी के धान ओ कोठी करय (B) जतके ओढ़ना, ततके गोड़ लमाय (C) कुकरा नइ बासही त का बिहान नइ होही (D) काठ के हँड़िया एके बार चढ़थे<br>1. किसी एक के बिना संसार का काम नहीं रुकता 2. बेकार बैठा व्यक्ति व्यर्थ के काम करता है 3. छल-कपट एक ही बार सफल होता है 4. आय के अनुसार खर्च करना चाहिए","o":["A-4, B-2, C-1, D-3","A-2, B-1, C-4, D-3","A-2, B-4, C-1, D-3","A-2, B-4, C-3, D-1"],"a":2,"e":"A-2: ठलहा = खाली; निरर्थक व्यस्तता।<br>B-4: चादर जितनी, उतने पैर फैलाओ।<br>C-1: मुर्गा बाँग न दे तब भी सवेरा होता है।<br>D-3: लकड़ी की हांडी एक ही बार चढ़ती है।"},
    {"q":"सूची-I (हाना में आए शब्द) को सूची-II (अर्थ) से सुमेलित कीजिए —<br>(A) आरसी (B) गोही (C) पसेरी (D) दमड़ी<br>1. पाँच सेर का माप 2. सबसे छोटा सिक्का 3. दर्पण 4. गुठली","o":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-1, B-4, C-3, D-2","A-3, B-4, C-1, D-2"],"a":3,"e":"A-3: हाथ कंगन ल आरसी का — आरसी = दर्पण।<br>B-4: आमा के आमा, गोही के दाम — गोही = गुठली।<br>C-1: सबो धान बाईस पसेरी — पसेरी = पाँच सेर।<br>D-2: चमड़ी जाय फेर दमड़ी झन जाय — दमड़ी = छोटा सिक्का।"},
    {"q":"सूची-I (मुहावरा) को सूची-II (अर्थ) से सुमेलित कीजिए —<br>(A) मुँह म दही जमना (B) डूमर के फूल होना (C) थूक के चाटना (D) बेंदरा बाँट<br>1. दुर्लभ होना 2. अनुचित बँटवारा 3. चुप रह जाना 4. कही बात से मुकर जाना","o":["A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-2, D-4"],"a":0,"e":"A-3: मुँह में दही जमना = कुछ न बोल पाना।<br>B-1: गूलर (डूमर) का फूल दिखता नहीं = दुर्लभ।<br>C-4: थूककर चाटना = वचन से पलटना।<br>D-2: बंदर-बाँट = बीच वाले का सब हड़प लेना।"},
    {"q":"सूची-I (छत्तीसगढ़ी शब्द) को सूची-II (हिन्दी अर्थ) से सुमेलित कीजिए —<br>(A) डउका (B) फूफू (C) दमांद (D) नोनी<br>1. दामाद 2. पति 3. बेटी 4. बुआ","o":["A-4, B-2, C-1, D-3","A-2, B-4, C-1, D-3","A-2, B-1, C-4, D-3","A-3, B-4, C-1, D-2"],"a":1,"e":"A-2: डउका = पति (डउकी = पत्नी)।<br>B-4: फूफू = बुआ।<br>C-1: दमांद = दामाद।<br>D-3: नोनी = बेटी/लड़की।"},
    {"q":"सूची-I (छत्तीसगढ़ी अंग-नाम) को सूची-II (हिन्दी) से सुमेलित कीजिए —<br>(A) घेंच (B) माड़ी (C) खांध (D) अँगरी<br>1. कंधा 2. उँगली 3. गर्दन 4. घुटना","o":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2","A-1, B-4, C-3, D-2"],"a":2,"e":"A-3: घेंच = गर्दन।<br>B-4: माड़ी = घुटना।<br>C-1: खांध = कंधा।<br>D-2: अँगरी = उँगली।"},
    {"q":"सूची-I (कृषि-शब्द) को सूची-II (अर्थ) से सुमेलित कीजिए —<br>(A) बियासी (B) मिंजई (C) लुवई (D) खुर्रा बोनी<br>1. फसल की कटाई 2. सूखे खेत में बुवाई 3. खड़ी धान में हल चलाना 4. मड़ाई (दाना अलग करना)","o":["A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2"],"a":3,"e":"A-3: बियासी = खड़ी फसल में हल चलाना।<br>B-4: मिंजई = मड़ाई (कोठार में)।<br>C-1: लुवई = कटाई।<br>D-2: खुर्रा बोनी = वर्षा से पहले सूखे खेत में बुवाई।"},
    {"q":"सूची-I को सूची-II से सुमेलित कीजिए —<br>(A) कोठा (B) कोठी (C) कोठार (D) कुरिया<br>1. खलिहान 2. छोटा कमरा / झोपड़ी 3. पशुशाला 4. अनाज रखने का भंडार","o":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-1, B-4, C-3, D-2","A-3, B-1, C-4, D-2"],"a":0,"e":"A-3: कोठा = पशुशाला।<br>B-4: कोठी = अनाज-भंडार (\"ए कोठी के धान ओ कोठी\")।<br>C-1: कोठार = खलिहान।<br>D-2: कुरिया = छोटा कमरा।"},
    {"q":"सूची-I (छत्तीसगढ़ी दिशा-नाम) को सूची-II (दिशा) से सुमेलित कीजिए —<br>(A) उत्ती (B) बुड़ती (C) रक्सहूँ (D) भंडार<br>1. उत्तर 2. पूर्व 3. पश्चिम 4. दक्षिण","o":["A-3, B-2, C-4, D-1","A-2, B-3, C-4, D-1","A-2, B-4, C-3, D-1","A-1, B-3, C-4, D-2"],"a":1,"e":"A-2: उत्ती = पूर्व (सूर्य उगने की दिशा)।<br>B-3: बुड़ती = पश्चिम (सूर्य डूबने की दिशा)।<br>C-4: रक्सहूँ = दक्षिण।<br>D-1: भंडार = उत्तर।"},
    {"q":"सूची-I (छत्तीसगढ़ी) को सूची-II (हिन्दी) से सुमेलित कीजिए —<br>(A) तुमा (B) कुम्हड़ा (C) जिमीकांदा (D) तिवरा<br>1. कद्दू 2. खेसारी 3. लौकी 4. जमीकंद (सूरन)","o":["A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"a":2,"e":"A-3: तुमा = लौकी।<br>B-1: कुम्हड़ा = कद्दू।<br>C-4: जिमीकांदा = जमीकंद।<br>D-2: तिवरा = खेसारी (लाखड़ी)।"},
    {"q":"सूची-I (छत्तीसगढ़ी) को सूची-II (हिन्दी) से सुमेलित कीजिए —<br>(A) बिही (B) बोइर (C) अमली (D) कुसियार<br>1. गन्ना 2. इमली 3. बेर 4. अमरूद","o":["A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2","A-4, B-3, C-2, D-1"],"a":3,"e":"A-4: बिही = अमरूद।<br>B-3: बोइर = बेर।<br>C-2: अमली = इमली।<br>D-1: कुसियार = गन्ना।"},
    {"q":"सूची-I (छत्तीसगढ़ी सर्वनाम) को सूची-II (हिन्दी) से सुमेलित कीजिए —<br>(A) मोर (B) मोला (C) तोर (D) ओला<br>1. उसे 2. मेरा 3. तेरा 4. मुझे","o":["A-2, B-4, C-3, D-1","A-4, B-2, C-3, D-1","A-2, B-4, C-1, D-3","A-3, B-4, C-2, D-1"],"a":0,"e":"A-2: मोर = मेरा।<br>B-4: मोला = मुझे।<br>C-3: तोर = तेरा।<br>D-1: ओला = उसे।"},
    {"q":"सूची-I (छत्तीसगढ़ी क्रिया-रूप) को सूची-II (हिन्दी) से सुमेलित कीजिए —<br>(A) मैं जाथँव (B) मैं गेंव (C) मैं जाहूँ (D) मैं जावत हँव<br>1. मैं जा रहा हूँ 2. मैं जाऊँगा 3. मैं जाता हूँ 4. मैं गया","o":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-3, B-2, C-4, D-1","A-3, B-4, C-1, D-2"],"a":1,"e":"A-3: \"-थँव\" = वर्तमान (जाता हूँ)।<br>B-4: गेंव = गया।<br>C-2: \"-हूँ\" = भविष्य (जाऊँगा)।<br>D-1: \"जावत हँव\" = सतत वर्तमान (जा रहा हूँ)।"},
    {"q":"सूची-I (छत्तीसगढ़ी कारक-चिह्न) को सूची-II (हिन्दी) से सुमेलित कीजिए —<br>(A) ल (B) ले (C) म (D) बर<br>1. में 2. के लिए 3. को 4. से","o":["A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2"],"a":2,"e":"A-3: ल = को (मही ल = छाछ को)।<br>B-4: ले = से (बूँद-बूँद ले)।<br>C-1: म = में (गली म)।<br>D-2: बर = के लिए (हज बर)।"},
    {"q":"सूची-I (हिन्दी लोकोक्ति) को सूची-II (छत्तीसगढ़ी हाना) से सुमेलित कीजिए —<br>(A) चिराग तले अँधेरा (B) सिर मुँड़ाते ही ओले पड़े (C) ओखली में सिर दिया तो मूसल से क्या डरना (D) तेते पाँव पसारिए, जेती लाँबी सौर<br>1. बाहना म मुड़ डारे त मूसर ले का डर्राना 2. जतके ओढ़ना, ततके गोड़ लमाय 3. दीया तरी अँधियार 4. मुड़ मुड़ावत ओला परगे","o":["A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2"],"a":3,"e":"A-3: चिराग = दीया, तले = तरी।<br>B-4: सिर = मुड़, ओले = ओला।<br>C-1: ओखली = बाहना, मूसल = मूसर।<br>D-2: पाँव = गोड़, सौर (चादर) = ओढ़ना।"},
    {"q":"सूची-I (मुहावरा) को सूची-II (अर्थ) से सुमेलित कीजिए —<br>(A) कनिहा कसना (B) गोड़ उखड़ना (C) मुड़ उठाना (D) हाथ खींचना<br>1. सहयोग बंद कर देना 2. विद्रोह करना 3. हारकर भाग खड़ा होना 4. किसी काम के लिए तैयार होना","o":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-1, B-3, C-2, D-4"],"a":0,"e":"A-4: कनिहा (कमर) कसना = तैयार होना।<br>B-3: गोड़ (पैर) उखड़ना = हारकर भागना।<br>C-2: मुड़ (सिर) उठाना = विद्रोह।<br>D-1: हाथ खींचना = सहयोग रोकना।"},
    {"q":"सूची-I (छत्तीसगढ़ी विशेषण) को सूची-II (हिन्दी) से सुमेलित कीजिए —<br>(A) गरू (B) हरु (C) जुड़ (D) तात<br>1. गरम 2. हल्का 3. ठंडा 4. भारी","o":["A-2, B-4, C-3, D-1","A-4, B-2, C-3, D-1","A-4, B-2, C-1, D-3","A-4, B-3, C-2, D-1"],"a":1,"e":"A-4: गरू = भारी।<br>B-2: हरु = हल्का।<br>C-3: जुड़ = ठंडा (करेजा जुड़ाना = मन ठंडा होना)।<br>D-1: तात = गरम (ताते-तात)।"},
    {"q":"सूची-I (जनऊला) को सूची-II (उत्तर) से सुमेलित कीजिए —<br>(A) तरी पचरी, ऊपर परी, बीच म मोंगरी मछरी (B) दूनो कोठा के गोबर ल, एके हाथ म हेरय (C) करिया बन म रहिथँव, लाल पानी पीथँव (D) करिया हे फेर कौंवा नोहय, लंबा हे फेर साँप नोहय<br>1. नाक 2. बेनी (चोटी) 3. जीभ 4. जूँ","o":["A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-1, C-2, D-4"],"a":2,"e":"A-3: दाँतों के बीच हिलती जीभ।<br>B-1: दो नथुने = दो कोठा — नाक।<br>C-4: काले बालों में रहकर खून पीने वाली जूँ।<br>D-2: काली-लंबी चोटी (बेनी)।"},
    {"q":"सूची-I (छत्तीसगढ़ी) को सूची-II (हिन्दी) से सुमेलित कीजिए —<br>(A) कोकड़ा (B) परेवा (C) बघवा (D) मकरा<br>1. मकड़ी 2. बगुला 3. बाघ 4. कबूतर","o":["A-4, B-2, C-3, D-1","A-2, B-3, C-4, D-1","A-2, B-4, C-1, D-3","A-2, B-4, C-3, D-1"],"a":3,"e":"A-2: कोकड़ा = बगुला।<br>B-4: परेवा = कबूतर।<br>C-3: बघवा = बाघ।<br>D-1: मकरा = मकड़ी।"},
    {"q":"सूची-I (घर के भाग) को सूची-II (हिन्दी) से सुमेलित कीजिए —<br>(A) परछी (B) छानी (C) भिथिया (D) दुवारी<br>1. दरवाज़ा 2. बरामदा 3. दीवार 4. छप्पर","o":["A-2, B-4, C-3, D-1","A-4, B-2, C-3, D-1","A-2, B-3, C-4, D-1","A-1, B-4, C-3, D-2"],"a":0,"e":"A-2: परछी = बरामदा।<br>B-4: छानी = छप्पर।<br>C-3: भिथिया = दीवार।<br>D-1: दुवारी = द्वार/दरवाज़ा।"},
    {"q":"सूची-I (छत्तीसगढ़ी) को सूची-II (हिन्दी) से सुमेलित कीजिए —<br>(A) लुगरा (B) पागा (C) ककई (D) खुमरी<br>1. कंघी 2. साड़ी 3. बाँस-पत्तों की छतरीनुमा टोपी 4. पगड़ी","o":["A-4, B-2, C-1, D-3","A-2, B-4, C-1, D-3","A-2, B-1, C-4, D-3","A-2, B-4, C-3, D-1"],"a":1,"e":"A-2: लुगरा = साड़ी। B-4: पागा = पगड़ी। C-1: ककई = कंघी। D-3: खुमरी = छतरीनुमा टोपी।"},
    {"q":"सूची-I (हाना) को सूची-II (किसके लिए कहा जाता है) से सुमेलित कीजिए —<br>(A) गंगा गे त गंगादास, जमुना गे त जमुनादास (B) चमड़ी जाय फेर दमड़ी झन जाय (C) बेंदरा के हाथ म उस्तुरा (D) नौ सौ मुसुवा खा के बिलई चलिस हज बर<br>1. कंजूस 2. पाप करके धार्मिक ढोंग करने वाला 3. अवसरवादी 4. अधिकार पाया अयोग्य व्यक्ति","o":["A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4","A-3, B-1, C-4, D-2","A-4, B-1, C-3, D-2"],"a":2,"e":"A-3: जहाँ गया, वैसा बन गया — अवसरवादी।<br>B-1: चमड़ी जाए पर पैसा नहीं — कंजूस।<br>C-4: बंदर के हाथ उस्तरा — अयोग्य को अधिकार।<br>D-2: नौ सौ चूहे खाकर हज — पापी का ढोंग।"},
    {"q":"सूची-I (छत्तीसगढ़ी समय-सूचक) को सूची-II (हिन्दी) से सुमेलित कीजिए —<br>(A) बिहान (B) अबेर (C) बेरा (D) बछर<br>1. वर्ष 2. देर 3. समय 4. सवेरा / अगला दिन","o":["A-2, B-4, C-3, D-1","A-4, B-3, C-2, D-1","A-4, B-2, C-1, D-3","A-4, B-2, C-3, D-1"],"a":3,"e":"A-4: बिहान = सवेरा (\"का बिहान नइ होही\")।<br>B-2: अबेर = देर।<br>C-3: बेरा = समय (\"फाँदे के बेर\")।<br>D-1: बछर = वर्ष।"},
    {"q":"सूची-I (छत्तीसगढ़ी क्रिया) को सूची-II (हिन्दी) से सुमेलित कीजिए —<br>(A) अगोरना (B) बिसाना (C) बुताना (D) चिन्हना<br>1. पहचानना 2. बुझाना 3. खरीदना 4. प्रतीक्षा करना","o":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2"],"a":0,"e":"A-4: अगोरना = राह देखना।<br>B-3: बिसाना = खरीदना।<br>C-2: बुताना = बुझाना।<br>D-1: चिन्हना = पहचानना।"},
    {"q":"सूची-I (मुहावरा) को सूची-II (अर्थ) से सुमेलित कीजिए —<br>(A) पेट म दाढ़ी होना (B) छाती म साँप लोटना (C) माथा ठनकना (D) कान के कच्चा होना<br>1. ईर्ष्या होना 2. अनिष्ट की आशंका होना 3. कम उम्र में अधिक चतुर होना 4. सुनी-सुनाई बात पर विश्वास कर लेना","o":["A-1, B-3, C-2, D-4","A-3, B-1, C-2, D-4","A-3, B-2, C-1, D-4","A-3, B-1, C-4, D-2"],"a":1,"e":"A-3: पेट में दाढ़ी = छोटी उम्र में चालाक।<br>B-1: छाती पर साँप लोटना = जलन।<br>C-2: माथा ठनकना = बुरा होने का संदेह।<br>D-4: कान का कच्चा = जल्दी विश्वास करने वाला।"},
    {"q":"सूची-I (कोरी-गणना) को सूची-II (संख्या) से सुमेलित कीजिए —<br>(A) एक कोरी (B) पाँच कोरी (C) अठारा कोरी (D) दू कोरी<br>1. 100 2. 40 3. 20 4. 360","o":["A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-1, C-2, D-4"],"a":2,"e":"A-3: 1 × 20 = 20।<br>B-1: 5 × 20 = 100।<br>C-4: 18 × 20 = 360 (चलनी वाला जनऊला)।<br>D-2: 2 × 20 = 40।"},
    {"q":"सूची-I (छत्तीसगढ़ी मास-नाम) को सूची-II (हिन्दी मास) से सुमेलित कीजिए —<br>(A) कुवाँर (B) अग्घन (C) कातिक (D) चइत<br>1. चैत्र 2. कार्तिक 3. आश्विन 4. मार्गशीर्ष","o":["A-4, B-3, C-2, D-1","A-3, B-2, C-4, D-1","A-3, B-4, C-1, D-2","A-3, B-4, C-2, D-1"],"a":3,"e":"A-3: कुवाँर = आश्विन (क्वार)।<br>B-4: अग्घन = अगहन/मार्गशीर्ष।<br>C-2: कातिक = कार्तिक।<br>D-1: चइत = चैत्र।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (छत्तीसगढ़ी — हिन्दी) सही सुमेलित नहीं है?","o":["घेंच — घुटना","खांध — कंधा","नख — नाखून","ओंठ — होंठ"],"a":0,"e":"घेंच = गर्दन; घुटना = माड़ी। शेष युग्म सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (छत्तीसगढ़ी दिशा — अर्थ) सही सुमेलित नहीं है?","o":["उत्ती — पूर्व","बुड़ती — उत्तर","रक्सहूँ — दक्षिण","भंडार — उत्तर"],"a":1,"e":"बुड़ती = पश्चिम (सूर्य के डूबने की दिशा)। उत्ती = पूर्व, रक्सहूँ = दक्षिण, भंडार = उत्तर सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म सही सुमेलित नहीं है?","o":["तुमा — लौकी","कुम्हड़ा — कद्दू","बिही — सेब","बोइर — बेर"],"a":2,"e":"बिही = अमरूद, सेब नहीं। शेष तीनों युग्म सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (हाना — अर्थ) सही सुमेलित नहीं है?","o":["दीया तरी अँधियार — निकट की बुराई दिखाई नहीं देती","खोदिस पहाड़, निकलिस मुसुवा — परिश्रम अधिक, फल थोड़ा","जतके ओढ़ना, ततके गोड़ लमाय — आय के अनुसार खर्च","अकेल्ला चना भाड़ नइ फोरय — अकेले रहना श्रेष्ठ है"],"a":3,"e":"\"अकेल्ला चना भाड़ नइ फोरय\" का अर्थ है — अकेला व्यक्ति बड़ा काम नहीं कर सकता (संगठन का महत्त्व)। शेष युग्म सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (मुहावरा — अर्थ) सही सुमेलित नहीं है?","o":["मुँह के खाना — भरपेट भोजन करना","हाथ मलना — पछताना","नाक म दम करना — बहुत परेशान करना","पीठ ठोंकना — शाबाशी देना"],"a":0,"e":"\"मुँह के खाना\" = बुरी तरह पराजित होना। शेष तीनों सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (जनऊला — उत्तर) सही सुमेलित नहीं है?","o":["पेट चिरहा, पीठ कुबरा — कौड़ी","नानकुन डबरी, बूड़े भारी जहाज — डोंगा (नाव)","मूठा म धरे, खँचवा म भरे — जाँता","फाँदे के बेर एक ठन, छोरे के बेर दू ठन — दतवन"],"a":1,"e":"\"नानकुन डबरी, बूड़े भारी जहाज\" का उत्तर दीया है — तेल की डबरी में बाती रूपी जहाज डूबा रहता है। शेष सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (रिश्ता) सही सुमेलित नहीं है?","o":["डउका — पति","फूफू — बुआ","दमांद — देवर","संगवारी — साथी"],"a":2,"e":"दमांद = दामाद, देवर नहीं। शेष युग्म सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (कृषि-शब्द) सही सुमेलित नहीं है?","o":["नाँगर — हल","रापा — फावड़ा","खातू — खाद","कोठार — पशुशाला"],"a":3,"e":"कोठार = खलिहान; पशुशाला = कोठा। शेष तीनों युग्म सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (क्रिया) सही सुमेलित नहीं है?","o":["बिसाना — बेचना","राँधना — भोजन पकाना","टोरना — तोड़ना","हाँसना — हँसना"],"a":0,"e":"बिसाना = खरीदना, बेचना नहीं। शेष युग्म सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (हाना में आया शब्द — अर्थ) सही सुमेलित नहीं है?","o":["मही — छाछ","आरसी — आरती","गोही — गुठली","पगहा — पशु बाँधने की रस्सी"],"a":1,"e":"आरसी = दर्पण (\"हाथ कंगन ल आरसी का\")। शेष युग्म सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (जीव) सही सुमेलित नहीं है?","o":["मुसुवा — चूहा","परेवा — कबूतर","कोकड़ा — केकड़ा","छेरी — बकरी"],"a":2,"e":"कोकड़ा = बगुला; केकड़ा = केकरा। शेष तीनों सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (हाना — अर्थ) सही सुमेलित नहीं है?","o":["हाथी चलय बजार, कुकुर भूँकय हजार — महान लोग निंदा की परवाह नहीं करते","नौ नगद न तेरह उधार — नकद का थोड़ा लाभ उधार के अधिक लाभ से अच्छा","घर के भेदी लंका ढाहय — घर का भेदी सबसे बड़ा नुकसान करता है","बिलई के भाग ले सींका टूटिस — कठोर परिश्रम से सफलता मिलना"],"a":3,"e":"\"बिलई के भाग ले सींका टूटिस\" = संयोग से अचानक लाभ (बिना परिश्रम)। शेष सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (रंग) सही सुमेलित नहीं है?","o":["उज्जर — पीला","करिया — काला","हरियर — हरा","पीयर — पीला"],"a":0,"e":"उज्जर = सफ़ेद (उजला); पीला = पीयर। शेष सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (मुहावरा — अर्थ) सही सुमेलित नहीं है?","o":["आँखी बिछाना — प्रेम से स्वागत करना","आँखी चुराना — चोरी करना","आँखी खुलना — वास्तविकता का ज्ञान होना","आँखी के काँटा होना — अत्यंत अप्रिय लगना"],"a":1,"e":"\"आँखी चुराना\" = लज्जा या भय से सामने आने से बचना। शेष तीनों सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (सर्वनाम) सही सुमेलित नहीं है?","o":["हमर — हमारा","तोला — तुझे","ओमन — उसका","मोर — मेरा"],"a":2,"e":"ओमन = वे; उसका = ओकर। शेष सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (घरेलू वस्तु) सही सुमेलित नहीं है?","o":["बहरी — झाड़ू","घइला — घड़ा","बाहना — ओखली","जाँता — मूसल"],"a":3,"e":"जाँता = हाथ-चक्की; मूसल = मूसर। शेष युग्म सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (मुहावरा — अर्थ) सही सुमेलित नहीं है?","o":["गोड़ जमाना — स्थिर होना","पेट काटना — बहुत अधिक खाना","छाती फूलना — गर्व अनुभव होना","दाँत काटी रोटी — गहरी मित्रता"],"a":1,"e":"\"पेट काटना\" = खर्च घटाकर बचत करना। शेष तीनों सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (प्रकृति) सही सुमेलित नहीं है?","o":["पुरवाही — पूर्व से चलने वाली हवा","धुर्रा — धूल","करा — कड़ाही","चंदैनी — तारे"],"a":2,"e":"करा = ओला; कड़ाही = कराही। शेष युग्म सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (हाना — अर्थ) सही सुमेलित नहीं है?","o":["चार दिन के चाँदनी, फेर अँधियारी रात — सुख-वैभव थोड़े दिन का","डूबत ल तिनका के सहारा — संकट में छोटी मदद भी बड़ी","थोथा चना, बाजय घना — कम गुण वाला अधिक बोलता है","जइसन देस, तइसन भेस — अपने देश की वेशभूषा कभी न छोड़ें"],"a":3,"e":"\"जइसन देस, तइसन भेस\" = जहाँ रहें वहाँ के अनुसार आचरण करें। शेष सही हैं।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. छत्तीसगढ़ी में \"उत्ती\" पूर्व दिशा को कहते हैं।<br>2. छत्तीसगढ़ी में \"भंडार\" दक्षिण दिशा को कहते हैं।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही: उत्ती = पूर्व।<br>कथन 2 गलत: भंडार = उत्तर; दक्षिण = रक्सहूँ।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. छत्तीसगढ़ी शब्द \"गरू\" का अर्थ हल्का है।<br>2. छत्तीसगढ़ी शब्द \"जुड़\" का अर्थ ठंडा है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत: गरू = भारी; हल्का = हरु।<br>कथन 2 सही: जुड़ = ठंडा।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. हाना (लोकोक्ति) प्रायः पूर्ण वाक्य होता है, जबकि मुहावरा वाक्यांश होता है।<br>2. मुहावरे का अर्थ शब्दों के सामान्य अर्थ से भिन्न (लाक्षणिक) होता है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही: हाना स्वतंत्र वाक्य है, मुहावरा वाक्य में जुड़कर आता है।<br>कथन 2 सही: जैसे \"लबारी मारना\" में किसी को मारा नहीं जाता — अर्थ है झूठ बोलना।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. छत्तीसगढ़ी में \"तुमा\" कद्दू को कहते हैं।<br>2. छत्तीसगढ़ी में \"बिही\" सेब को कहते हैं।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":3,"e":"कथन 1 गलत: तुमा = लौकी; कद्दू = कुम्हड़ा।<br>कथन 2 गलत: बिही = अमरूद।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. जनऊला \"पहाड़ ले उतरे रेचकी घोड़ी, ओकर पीला अठारा कोरी\" में \"अठारा कोरी\" का मान 360 है।<br>2. छत्तीसगढ़ी गणना में \"कोरी\" दस की इकाई है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही: 18 × 20 = 360।<br>कथन 2 गलत: एक कोरी = 20।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. छत्तीसगढ़ी में \"मोर\" सर्वनाम स्त्रीलिंग संज्ञा के साथ बदलकर \"मोरी\" हो जाता है।<br>2. छत्तीसगढ़ी में बहुवचन प्रायः \"-मन\" जोड़कर बनता है (जैसे लइकामन, ओमन)।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत: \"मोर दाई\", \"मोर ददा\" — दोनों में \"मोर\" ही रहता है।<br>कथन 2 सही: हमन, तुमन, ओमन, लइकामन।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. छत्तीसगढ़ी में \"झन\" शब्द निषेध (मत) के लिए प्रयुक्त होता है।<br>2. छत्तीसगढ़ी में \"नइ\" का अर्थ \"नहीं\" है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही: \"झन जा\" = मत जाओ।<br>कथन 2 सही: \"मोला नइ पता\" = मुझे नहीं पता।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. हाना \"जेकर बेंदरा, तेकरे ले नाचय\" का अर्थ है — बंदर हर किसी के कहने पर नाचता है।<br>2. मुहावरा \"बेंदरा बाँट\" का अर्थ न्यायपूर्ण बँटवारा है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":3,"e":"कथन 1 गलत: बंदर केवल अपने मालिक के कहने पर नाचता है — व्यक्ति अपने स्वामी का ही कहा मानता है।<br>कथन 2 गलत: बेंदरा बाँट = बीच वाले द्वारा सब हड़प लेने वाला अनुचित बँटवारा।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. \"कोठार\" खलिहान को कहते हैं, जहाँ फसल की मिंजई होती है।<br>2. \"बियासी\" फसल की कटाई को कहते हैं।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही: कोठार = खलिहान।<br>कथन 2 गलत: बियासी = खड़ी धान में हल चलाना; कटाई = लुवई।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. छत्तीसगढ़ी शब्द \"पताल\" का अर्थ पाताल लोक है।<br>2. छत्तीसगढ़ी में \"मंजूर\" मोर को कहते हैं।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत: पताल = टमाटर।<br>कथन 2 सही: मंजूर = मोर (हिन्दी \"मंज़ूर\" नहीं)।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. जनऊला \"खटिया गाँथे तान-बितान, दू सुतइया बाइस कान\" का उत्तर रावण और मंदोदरी है।<br>2. इस जनऊला में \"बाइस\" का अर्थ बाईस (22) है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही।<br>कथन 2 सही: रावण के 20 और मंदोदरी के 2 कान = 22।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. छत्तीसगढ़ी में \"कन्हार\" कंकरीली लाल मिट्टी को कहते हैं।<br>2. \"भाठा\" भूमि सबसे उपजाऊ काली मिट्टी वाली होती है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":3,"e":"कथन 1 गलत: कन्हार = काली भारी मिट्टी।<br>कथन 2 गलत: भाठा = कंकरीली, कम उपजाऊ भूमि।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. छत्तीसगढ़ी वाक्य \"वो गिस\" का अर्थ है \"वह गया\"।<br>2. छत्तीसगढ़ी वाक्य \"हमन जाबो\" का अर्थ है \"हम गए\"।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही: गिस = गया।<br>कथन 2 गलत: जाबो = जाएँगे; \"हम गए\" = हमन गेन।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. हाना \"बाहना म मुड़ डारे त मूसर ले का डर्राना\" में \"बाहना\" का अर्थ बहाना है।<br>2. इसी हाना में \"मूसर\" का अर्थ मूसल है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत: बाहना = ओखली।<br>कथन 2 सही: मूसर = मूसल। (हिन्दी: ओखली में सिर दिया तो मूसल से क्या डरना।)"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. \"दार-भात म मूसरचंद\" बिना बुलाए दखल देने वाले के लिए कहा जाता है।<br>2. \"आगू नाथ न पाछू पगहा\" ऐसे व्यक्ति के लिए कहा जाता है जिस पर कोई बंधन या ज़िम्मेदारी न हो।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही: दाल-भात में मूसलचंद।<br>कथन 2 सही: न आगे नाथ, न पीछे पगहा — बंधनमुक्त।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. छत्तीसगढ़ी क्रिया \"बिसाना\" का अर्थ बेचना है।<br>2. छत्तीसगढ़ी क्रिया \"अगोरना\" का अर्थ आगे बढ़ना है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":3,"e":"कथन 1 गलत: बिसाना = खरीदना।<br>कथन 2 गलत: अगोरना = प्रतीक्षा करना।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. मुहावरा \"डूमर के फूल होना\" में \"डूमर\" गूलर वृक्ष है।<br>2. \"डूमर के फूल होना\" का अर्थ है — किसी वस्तु का बहुत अधिक मात्रा में मिलना।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":0,"e":"कथन 1 सही: डूमर = गूलर।<br>कथन 2 गलत: गूलर का फूल दिखाई नहीं देता, इसलिए अर्थ है — दुर्लभ होना।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. छत्तीसगढ़ी में \"पहुना\" का अर्थ पड़ोसी है।<br>2. छत्तीसगढ़ी में \"सगा\" का अर्थ रिश्तेदार है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत: पहुना = मेहमान (विशेषकर दामाद)।<br>कथन 2 सही: सगा = रिश्तेदार, स्वजन।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. \"चंदैनी\" का अर्थ तारे है।<br>2. \"करा\" का अर्थ कड़ाही है।<br>3. \"पुरवाही\" पूर्व दिशा से चलने वाली हवा है।<br>सही कथन हैं —","o":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"a":2,"e":"कथन 1 सही: चंदैनी = तारे।<br>कथन 2 गलत: करा = ओला; कड़ाही = कराही।<br>कथन 3 सही: पुरवाही = पुरवाई।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. \"जाथँव\" वर्तमान काल का रूप है।<br>2. \"जाहूँ\" भविष्य काल का रूप है।<br>3. \"गेंव\" भूतकाल का रूप है।<br>सही कथन हैं —","o":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"a":3,"e":"कथन 1 सही: जाथँव = जाता हूँ।<br>कथन 2 सही: जाहूँ = जाऊँगा।<br>कथन 3 सही: गेंव = गया।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. \"करू\" का अर्थ कड़वा है।<br>2. \"चुरपुर\" का अर्थ तीखा है।<br>3. \"अलोना\" का अर्थ अधिक नमक वाला है।<br>सही कथन हैं —","o":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"a":0,"e":"कथन 1 सही: करू = कड़वा।<br>कथन 2 सही: चुरपुर = तीखा।<br>कथन 3 गलत: अलोना = बिना नमक का (\"खवइया ल अलोना\")।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. \"नोनी\" का अर्थ नानी है।<br>2. \"बाबू\" स्नेह से बेटे/लड़के के लिए कहा जाता है।<br>3. \"डोकरी दाई\" का अर्थ दादी है।<br>सही कथन हैं —","o":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"a":1,"e":"कथन 1 गलत: नोनी = लड़की/बेटी।<br>कथन 2 सही।<br>कथन 3 सही: डोकरी दाई = दादी।"},
    {"q":"अभिकथन (A): हाना \"जइसन बोंही, तइसन लूही\" कर्मफल की सीख देता है।<br>कारण (R): इसमें \"बोंही\" का अर्थ \"बोएगा\" और \"लूही\" का अर्थ \"काटेगा\" है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A सही: कर्म के अनुसार फल।<br>R सही और व्याख्या: जैसा बोएगा वैसा काटेगा — इसी शब्दार्थ से कर्मफल का भाव निकलता है।"},
    {"q":"अभिकथन (A): जनऊला \"पेट चिरहा, पीठ कुबरा\" का उत्तर कौड़ी है।<br>कारण (R): प्राचीन काल में कौड़ी का प्रयोग मुद्रा (लेन-देन) के रूप में होता था।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":1,"e":"A सही: कौड़ी का पेट चिरा, पीठ उभरी होती है।<br>R सही, पर व्याख्या नहीं: उत्तर कौड़ी की आकृति से निकलता है, मुद्रा होने से नहीं।"},
    {"q":"अभिकथन (A): छत्तीसगढ़ी में \"उत्ती\" पूर्व दिशा को कहते हैं।<br>कारण (R): \"उत्ती\" शब्द \"उत्तर\" दिशा के नाम से बना है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":2,"e":"A सही: उत्ती = पूर्व।<br>R गलत: उत्ती सूर्य के उदय (उगने) की दिशा है, \"उत्तर\" से इसका संबंध नहीं; उत्तर दिशा को \"भंडार\" कहते हैं।"},
    {"q":"अभिकथन (A): छत्तीसगढ़ी में \"भाटा\" कंकरीली बंजर भूमि को कहते हैं।<br>कारण (R): छत्तीसगढ़ी में \"भाठा\" कम उपजाऊ, कंकरीली ऊँची भूमि को कहते हैं।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":3,"e":"A गलत: भाटा = बैंगन।<br>R सही: भाठा (ठ से) = कंकरीली भूमि। दोनों शब्दों में केवल \"ट/ठ\" का अंतर है।"},
    {"q":"अभिकथन (A): हाना \"दीया तरी अँधियार\" का प्रयोग तब होता है जब ज्ञानी या अधिकारी के निकट ही गड़बड़ी हो रही हो।<br>कारण (R): दीये का प्रकाश चारों ओर फैलता है, पर उसके ठीक नीचे अँधेरा रहता है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":0,"e":"A सही।<br>R सही और व्याख्या: जैसे दीये के नीचे अँधेरा, वैसे ही प्रकाश (ज्ञान/अधिकार) के ठीक पास की बुराई अनदेखी रह जाती है। तरी = नीचे।"},
    {"q":"अभिकथन (A): छत्तीसगढ़ी में \"मोर दाई\" और \"मोर ददा\" दोनों में \"मोर\" शब्द ही प्रयुक्त होता है।<br>कारण (R): छत्तीसगढ़ी में संबंधवाचक सर्वनाम संज्ञा के लिंग के अनुसार बदल जाता है।","o":["A और R दोनों सही हैं तथा R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है, R गलत है","A गलत है, R सही है"],"a":2,"e":"A सही।<br>R गलत: छत्तीसगढ़ी में मेरा/मेरी जैसा लिंग-भेद नहीं होता — इसीलिए दोनों में \"मोर\" आता है।"},
    {"q":"सूची-I (हाना में आए शब्द) को सूची-II (अर्थ) से सुमेलित कीजिए —<br>(A) ठलहा (B) अलोना (C) बिरवा (D) चिरई<br>1. पौधा 2. चिड़िया 3. खाली / बेकार 4. बिना नमक का","o":["A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1","A-1, B-4, C-3, D-2"],"a":0,"e":"A-3: \"ठलहा बनिया का करय\" — ठलहा = खाली।<br>B-4: \"खवइया ल अलोना\" — बिना नमक का।<br>C-1: \"होनहार बिरवान\" — बिरवा = पौधा।<br>D-2: \"चिरई चुग गे खेत\" — चिरई = चिड़िया।"},
    {"q":"सूची-I (मुहावरा) को सूची-II (अर्थ) से सुमेलित कीजिए —<br>(A) गागर म सागर भरना (B) तिल के ताड़ बनाना (C) खिचरी पकाना (D) घी-खिचरी होना<br>1. गुप्त योजना बनाना 2. बहुत घुलमिल जाना 3. थोड़े शब्दों में बहुत कहना 4. छोटी बात को बहुत बढ़ा देना","o":["A-4, B-3, C-1, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-2, D-1"],"a":1,"e":"A-3: गागर में सागर = संक्षेप में बहुत कहना।<br>B-4: तिल का ताड़ = बात का बतंगड़।<br>C-1: खिचड़ी पकाना = गुप्त योजना।<br>D-2: घी-खिचड़ी होना = घुलमिल जाना।"},
    {"q":"सूची-I (छत्तीसगढ़ी वाक्यांश) को सूची-II (हिन्दी अर्थ) से सुमेलित कीजिए —<br>(A) जय जोहार (B) बने हँव (C) थोरकुन अगोर (D) मोला नइ पता<br>1. मुझे नहीं पता 2. थोड़ा रुको 3. ठीक हूँ 4. नमस्कार (अभिवादन)","o":["A-3, B-4, C-2, D-1","A-4, B-2, C-3, D-1","A-4, B-3, C-1, D-2","A-4, B-3, C-2, D-1"],"a":3,"e":"A-4: जय जोहार = अभिवादन।<br>B-3: बने हँव = ठीक हूँ।<br>C-2: थोरकुन अगोर = थोड़ा रुको (प्रतीक्षा करो)।<br>D-1: मोला नइ पता = मुझे नहीं पता।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (कृषि-शब्द — अर्थ) सही सुमेलित नहीं है?","o":["पैरा — पैर","बरदी — मवेशियों का झुंड","धरसा — खेतों के बीच का कच्चा रास्ता","खुमरी — छतरीनुमा टोपी"],"a":0,"e":"पैरा = धान का पुआल; पैर = गोड़। शेष तीनों सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (मुहावरा — अर्थ) सही सुमेलित नहीं है?","o":["कान खड़ा होना — सतर्क हो जाना","मुड़ धुनना — बाल सँवारना","हाथ बँटाना — सहायता करना","गाल बजाना — डींग मारना"],"a":1,"e":"\"मुड़ धुनना\" = पछताना / शोक करना। शेष सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (हाना — अर्थ) सही सुमेलित नहीं है?","o":["सौ दिन चोर के, एक दिन साहूकार के — अपराधी एक दिन अवश्य पकड़ा जाता है","जल्दी के काम सैतान के — जल्दबाज़ी का काम बिगड़ता है","अपन दही ल कोनो खट्टा नइ कहय — दही को खट्टा होने से बचाना चाहिए","मुँह म राम, बगल म छुरी — ऊपर से मित्रता, भीतर से शत्रुता"],"a":2,"e":"\"अपन दही ल कोनो खट्टा नइ कहय\" = अपनी वस्तु के दोष कोई नहीं मानता। शेष सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (अन्न — हिन्दी) सही सुमेलित नहीं है?","o":["राहेर — अरहर","उरिद — उड़द","गहूँ — गेहूँ","मुर्रा — मूँग"],"a":3,"e":"मुर्रा = मुरमुरा (फुलाया चावल)। शेष युग्म सही हैं।"},
    {"q":"निम्नलिखित में से कौन-सा युग्म (रिश्ता) सही सुमेलित नहीं है?","o":["मनखे — मनुष्य","नाती — नाना","बहिनी — बहन","सारा — साला"],"a":1,"e":"नाती = पोता/नाती (बेटे या बेटी का पुत्र), नाना नहीं। शेष सही हैं।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. छत्तीसगढ़ी में \"तोर\" का अर्थ \"तेरा\" है।<br>2. छत्तीसगढ़ी में \"तुंहर\" का अर्थ \"तुम्हारा\" है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही: तोर = तेरा।<br>कथन 2 सही: तुंहर = तुम्हारा (तुमन का संबंध-रूप)।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. हाना \"आगी लगे म कुआँ खोदना\" पहले से तैयारी करने वाले की प्रशंसा में कहा जाता है।<br>2. हाना \"का बरसा जब खेती सुखाय\" समय पर मिली सहायता की प्रशंसा है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":3,"e":"कथन 1 गलत: यह संकट आने पर ही उपाय करने (तैयारी न करने) पर व्यंग्य है।<br>कथन 2 गलत: यह देर से मिली व्यर्थ सहायता के लिए है।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. \"रहचुली\" एक प्रकार का हाथ-पंखा है।<br>2. \"अड़गसनी\" कपड़े टाँगने की रस्सी या बाँस है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":1,"e":"कथन 1 गलत: रहचुली = झूला (\"एक गोड़ के घोड़ा, दुइ झन भये सवार\")। कथन 2 सही: अड़गसनी = कपड़े सुखाने/टाँगने की रस्सी या बाँस।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. \"बासी\" छत्तीसगढ़ का पारंपरिक भोजन है, जिसमें पके भात को पानी में भिगोकर रखा जाता है।<br>2. \"पेज\" चावल से बना पतला पेय है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":2,"e":"कथन 1 सही।<br>कथन 2 सही: पेज = चावल को अधिक पानी में पकाकर बना माँड़-युक्त पेय।"},
    {"q":"निम्नलिखित कथनों पर विचार कीजिए —<br>1. छत्तीसगढ़ी \"हरियर\" का अर्थ पीला है।<br>2. छत्तीसगढ़ी \"उज्जर\" का अर्थ काला है।<br>सही कथन है/हैं —","o":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 न ही 2"],"a":3,"e":"कथन 1 गलत: हरियर = हरा; पीला = पीयर।<br>कथन 2 गलत: उज्जर = सफ़ेद; काला = करिया।"}
  ]
});
